): Promise<CheckRecord[]> {
  const limit = options?.limit || 50;
  const offset = options?.offset || 0;

  let rows: FleetCheckRecordRow[];

  if (options?.status) {
    rows = await sql`
      SELECT * FROM fleet_check_records
      WHERE vehicle_id = ${vehicleId} AND status = ${options.status}
      ORDER BY check_date DESC, check_time DESC
      LIMIT ${limit} OFFSET ${offset}
    ` as FleetCheckRecordRow[];
  } else {
    rows = await sql`
      SELECT * FROM fleet_check_records
      WHERE vehicle_id = ${vehicleId}
      ORDER BY check_date DESC, check_time DESC
      LIMIT ${limit} OFFSET ${offset}
    ` as FleetCheckRecordRow[];
  }

  return rows.map(rowToCheckRecord);
}

/**
 * Get all check records with pagination
 */
export async function getCheckRecords(options?: {
  limit?: number;
  offset?: number;
  status?: CheckRecordStatus;
  driverId?: string;
  vehicleId?: string;
  dateFrom?: string;
  dateTo?: string;
}): Promise<{ records: CheckRecordWithDetails[]; total: number }> {
  const limit = options?.limit || 50;
  const offset = options?.offset || 0;

  // Explicit query branches — sql.unsafe() is not available on the Neon HTTP driver
  type RecordRow = FleetCheckRecordRow & { registration: string; make: string | null; model: string | null };
  let rows: RecordRow[];
  let countResult: { count: string }[];

  const { status, driverId, vehicleId, dateFrom, dateTo } = options || {};

  if (vehicleId && status) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.vehicle_id = ${vehicleId} AND r.status = ${status}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.vehicle_id = ${vehicleId} AND r.status = ${status}
    ` as { count: string }[];
  } else if (vehicleId) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.vehicle_id = ${vehicleId}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.vehicle_id = ${vehicleId}
    ` as { count: string }[];
  } else if (status && dateFrom && dateTo) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.status = ${status} AND r.check_date >= ${dateFrom} AND r.check_date <= ${dateTo}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.status = ${status} AND r.check_date >= ${dateFrom} AND r.check_date <= ${dateTo}
    ` as { count: string }[];
  } else if (status) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.status = ${status}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.status = ${status}
    ` as { count: string }[];
  } else if (driverId) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.driver_id = ${driverId}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.driver_id = ${driverId}
    ` as { count: string }[];
  } else if (dateFrom && dateTo) {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      WHERE r.check_date >= ${dateFrom} AND r.check_date <= ${dateTo}
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
      WHERE r.check_date >= ${dateFrom} AND r.check_date <= ${dateTo}
    ` as { count: string }[];
  } else {
    rows = await sql`
      SELECT r.*, v.registration, v.make, v.model
      FROM fleet_check_records r JOIN fleet_vehicles v ON v.id = r.vehicle_id
      ORDER BY r.check_date DESC, r.check_time DESC LIMIT ${limit} OFFSET ${offset}
    ` as RecordRow[];
    countResult = await sql`
      SELECT COUNT(*)::text as count FROM fleet_check_records r
    ` as { count: string }[];
  }

  const count = countResult[0]?.count ?? '0';

  // Get responses and photos for each record
  const records: CheckRecordWithDetails[] = [];
  for (const row of rows) {
    const responseRows = await sql`
      SELECT
        r.*,
        i.id as item_id,
        i.template_id as item_template_id,
        i.name as item_name,
        i.description as item_description,
        i.category as item_category,
        i.is_critical as item_is_critical,
        i.display_order as item_display_order,
        i.is_active as item_is_active,
        i.created_at as item_created_at
      FROM fleet_check_responses r
      JOIN fleet_check_items i ON i.id = r.item_id
      WHERE r.record_id = ${row.id}
      ORDER BY i.display_order ASC
    `;

    const photoRows = await sql`
      SELECT * FROM fleet_check_photos WHERE record_id = ${row.id}
    ` as FleetCheckPhotoRow[];

    records.push({
      ...rowToCheckRecord(row),
      vehicle: {
        registration: row.registration,
        make: row.make,
        model: row.model,
      },
      responses: responseRows.map(r => ({
        ...rowToCheckResponse(r as FleetCheckResponseRow),
        item: {
          id: r.item_id,
          templateId: r.item_template_id,
          name: r.item_name,
          description: r.item_description,
          category: r.item_category,
          isCritical: r.item_is_critical,
          displayOrder: r.item_display_order,
          isActive: r.item_is_active,
          createdAt: r.item_created_at,
        },
      })),
      photos: photoRows.map(rowToCheckPhoto),
    });
  }

  return { records, total: parseInt(count, 10) };
}

