/**
 * Fleet Portal - Verify License Plate API
 * POST: Extract plate from photo and match to vehicle
 *
 * Uses VLM to:
 * 1. Extract text from license plate image
 * 2. Look up vehicle in database by registration
 * 3. Return vehicle details or error
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { verifyLicensePlate } from '@/modules/fleet/services/fleetVlmService';
import fs from 'fs';
import path from 'path';
import sharp from 'sharp';
import { withAuth } from '@/lib/auth';

const sql = neon(process.env.DATABASE_URL!);

// Debug folder for saving plate photos
const DEBUG_PHOTO_DIR = '/tmp/fleet-plate-debug';

// Max image dimensions for VLM (to stay under token limit)
const MAX_IMAGE_WIDTH = 1024;
const MAX_IMAGE_HEIGHT = 768;

/**
 * Resize image to fit within VLM token limits
 * iPhone photos can be 4000x3000 which exceeds the model's context
 */
async function resizeImageForVlm(base64Image: string): Promise<string> {
  const inputBuffer = Buffer.from(base64Image, 'base64');

  // Get image metadata
  const metadata = await sharp(inputBuffer).metadata();
  const { width = 0, height = 0 } = metadata;

  // Only resize if image is too large
  if (width <= MAX_IMAGE_WIDTH && height <= MAX_IMAGE_HEIGHT) {
    log.info('Image within limits, no resize needed', { width, height });
    return base64Image;
  }

  log.info('Resizing large image for VLM', {
    originalWidth: width,
    originalHeight: height,
    targetMax: `${MAX_IMAGE_WIDTH}x${MAX_IMAGE_HEIGHT}`
  });

  // Resize maintaining aspect ratio
  const resizedBuffer = await sharp(inputBuffer)
    .resize(MAX_IMAGE_WIDTH, MAX_IMAGE_HEIGHT, {
      fit: 'inside',
      withoutEnlargement: true,
    })
    .jpeg({ quality: 85 })
    .toBuffer();

  const newMetadata = await sharp(resizedBuffer).metadata();
  log.info('Image resized', {
    newWidth: newMetadata.width,
    newHeight: newMetadata.height,
    originalSize: inputBuffer.length,
    newSize: resizedBuffer.length
  });

  return resizedBuffer.toString('base64');
}

interface VerifyPlateRequest {
  platePhotoBase64: string;
}

interface VehicleRow {
  id: string;
  registration: string;
  vehicle_type: string;
  make: string | null;
  model: string | null;
  year: number | null;
  color: string | null;
  status: string;
  assigned_driver_id: string | null;
}

interface StaffRow {
  id: string;
  first_name: string;
  last_name: string;
  id_number: string | null;
  phone: string | null;
}

interface OdometerRow {
  reading: number;
  recorded_at: string;
  source: string;
}

interface FuelRow {
  fuel_level: number;
  recorded_at: string;
  source: string;
}

interface CheckInRow {
  id: string;
  check_type: string;
  status: string;
  check_date: string;
  created_at: string;
  driver_name: string | null;
}

export const config = {
  api: {
    bodyParser: {
      sizeLimit: '10mb', // Allow larger images
    },
  },
};

async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'Unknown', ['POST']);
  }

  try {
    const body = req.body as VerifyPlateRequest;

    if (!body.platePhotoBase64) {
      return apiResponse.error(
        res,
        ErrorCode.BAD_REQUEST,
        'Plate photo is required'
      );
    }

    // Step 1: Extract plate text using VLM
    // We'll call verifyLicensePlate with a dummy expected plate first to get the extracted text
    // Then search for the vehicle by that registration
    let extractedPlate: string;
    let confidence: number;

    try {
      // Log incoming request details for debugging
      const imageSize = body.platePhotoBase64?.length || 0;
      log.info('Plate verification request', {
        imageSize,
        imageSizeKb: Math.round(imageSize / 1024),
      });

      // Save debug photo to disk for troubleshooting
      try {
        if (!fs.existsSync(DEBUG_PHOTO_DIR)) {
          fs.mkdirSync(DEBUG_PHOTO_DIR, { recursive: true });
        }
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const debugFilePath = path.join(DEBUG_PHOTO_DIR, `plate-${timestamp}.jpg`);
        const imageBuffer = Buffer.from(body.platePhotoBase64, 'base64');
        fs.writeFileSync(debugFilePath, imageBuffer);
        log.info('Debug photo saved', { path: debugFilePath, size: imageBuffer.length });
      } catch (saveErr) {
        log.warn('Failed to save debug photo', { error: saveErr });
      }

      // Resize image to fit VLM token limits (iPhone photos can be huge)
      const resizedBase64 = await resizeImageForVlm(body.platePhotoBase64);

      // Use the VLM service to extract plate
      const vlmResult = await verifyLicensePlate(resizedBase64, '');
      extractedPlate = vlmResult.plateText || '';
      confidence = vlmResult.confidence || 0;

      log.info('VLM plate extraction result', {
        extractedPlate,
        confidence,
        hasError: !!vlmResult.error,
        error: vlmResult.error,
      });

      if (!extractedPlate || extractedPlate.length < 3) {
        log.warn('Plate extraction failed - invalid result', {
          extractedPlate,
          confidence,
          vlmError: vlmResult.error,
          rawResponse: JSON.stringify(vlmResult).substring(0, 500),
        });

        // Rename debug file to indicate failure
        try {
          const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
          const failedPath = path.join(DEBUG_PHOTO_DIR, `FAILED-plate-${timestamp}.jpg`);
          const imageBuffer = Buffer.from(body.platePhotoBase64, 'base64');
          fs.writeFileSync(failedPath, imageBuffer);
          log.info('Failed extraction photo saved', { path: failedPath });
        } catch (saveErr) {
          log.error('VerifyPlateApi', 'Operation failed', { error });
          // Ignore save errors
        }

        return apiResponse.success(res, {
          success: false,
          extractedPlate: extractedPlate || '',
          confidence,
          vehicle: null,
          error: vlmResult.error || 'Could not extract a valid license plate from the image',
        });
      }
    } catch (vlmError) {
      const errorMessage = vlmError instanceof Error ? vlmError.message : 'Unknown error';
      log.error('VLM plate extraction failed', {
        error: errorMessage,
        stack: vlmError instanceof Error ? vlmError.stack : undefined,
      });
      return apiResponse.success(res, {
        success: false,
        extractedPlate: '',
        confidence: 0,
        vehicle: null,
        error: `Failed to process plate image: ${errorMessage}`,
      });
    }

    // Step 2: Normalize the extracted plate for database lookup
    // Remove spaces and convert to uppercase
    const normalizedPlate = extractedPlate
      .toUpperCase()
      .replace(/[\s-]/g, '');

    // Step 3: Search for vehicle in database
    // Try exact match first, then fuzzy match
    let vehicleRows = await sql`
      SELECT
        id, registration, vehicle_type, make, model, year, color, status, assigned_driver_id
      FROM fleet_vehicles
      WHERE UPPER(REPLACE(REPLACE(registration, ' ', ''), '-', '')) = ${normalizedPlate}
        AND status = 'active'
      LIMIT 1
    ` as VehicleRow[];

    // If no exact match, try partial matching (first 6 characters match)
    if (vehicleRows.length === 0 && normalizedPlate.length >= 6) {
      const partialPlate = normalizedPlate.substring(0, 6);
      vehicleRows = await sql`
        SELECT
          id, registration, vehicle_type, make, model, year, color, status, assigned_driver_id
        FROM fleet_vehicles
        WHERE UPPER(REPLACE(REPLACE(registration, ' ', ''), '-', '')) LIKE ${partialPlate + '%'}
          AND status = 'active'
        LIMIT 1
      ` as VehicleRow[];
    }

    if (vehicleRows.length === 0) {
      log.info('No vehicle found for plate', {
        extractedPlate,
        normalizedPlate,
      });
      return apiResponse.success(res, {
        success: false,
        extractedPlate,
        confidence,
        vehicle: null,
        error: `No active vehicle found with registration "${extractedPlate}"`,
      });
    }

    const vehicle = vehicleRows[0];

    // Step 4: Get assigned driver details if exists
    let assignedDriver: {
      name: string;
      idNumber: string | null;
      phone: string | null;
    } | null = null;

    if (vehicle.assigned_driver_id) {
      const staffRows = await sql`
        SELECT id, first_name, last_name, id_number, phone
        FROM staff
        WHERE id = ${vehicle.assigned_driver_id}
        LIMIT 1
      ` as StaffRow[];

      if (staffRows.length > 0) {
        assignedDriver = {
          name: `${staffRows[0].first_name} ${staffRows[0].last_name}`.trim(),
          idNumber: staffRows[0].id_number,
          phone: staffRows[0].phone,
        };
      }
    }

    // Step 5: Get last confirmed odometer and fuel readings
    let lastOdometer: { reading: number; recordedAt: string; source: string } | null = null;
    let lastFuel: { level: number; recordedAt: string; source: string } | null = null;

    // Fetch last odometer reading from history table
    const odometerRows = await sql`
      SELECT reading, recorded_at, source
      FROM fleet_odometer_history
      WHERE vehicle_id = ${vehicle.id}
      ORDER BY recorded_at DESC
      LIMIT 1
    ` as OdometerRow[];

    if (odometerRows.length > 0) {
      lastOdometer = {
        reading: odometerRows[0].reading,
        recordedAt: odometerRows[0].recorded_at,
        source: odometerRows[0].source,
      };
    } else {
      // Fallback: Get last ODO from check-in records if history is empty
      const checkInOdoRows = await sql`
        SELECT odometer_reading, check_date
        FROM fleet_check_records
        WHERE vehicle_id = ${vehicle.id}
          AND odometer_reading IS NOT NULL
        ORDER BY check_date DESC, created_at DESC
        LIMIT 1
      ` as { odometer_reading: number; check_date: string }[];

      if (checkInOdoRows.length > 0) {
        lastOdometer = {
          reading: checkInOdoRows[0].odometer_reading,
          recordedAt: checkInOdoRows[0].check_date,
          source: 'check-in',
        };
      }
    }

    // Fetch last fuel level from VLM results
    const fuelRows = await sql`
      SELECT fuel_level, recorded_at, source
      FROM fleet_fuel_history
      WHERE vehicle_id = ${vehicle.id}
      ORDER BY recorded_at DESC
      LIMIT 1
    ` as FuelRow[];

    if (fuelRows.length > 0) {
      lastFuel = {
        level: fuelRows[0].fuel_level,
        recordedAt: fuelRows[0].recorded_at,
        source: fuelRows[0].source,
      };
    }

    // Step 6: Get last check-in record
    let lastCheckIn: {
      id: string;
      checkType: string;
      status: string;
      completedAt: string | null;
      completedBy: string | null;
    } | null = null;

    const checkInRows = await sql`
      SELECT
        id,
        check_type,
        status,
        check_date,
        created_at,
        driver_name
      FROM fleet_check_records
      WHERE vehicle_id = ${vehicle.id}
      ORDER BY created_at DESC
      LIMIT 1
    ` as CheckInRow[];

    if (checkInRows.length > 0) {
      const row = checkInRows[0];
      lastCheckIn = {
        id: row.id,
        checkType: row.check_type,
        status: row.status,
        completedAt: row.check_date || row.created_at,
        completedBy: row.driver_name,
      };
    }

    log.info('Vehicle verified via plate', {
      extractedPlate,
      vehicleId: vehicle.id,
      registration: vehicle.registration,
      confidence,
      hasDriver: !!assignedDriver,
      hasLastOdometer: !!lastOdometer,
    });

    return apiResponse.success(res, {
      extractedPlate,
      confidence,
      vehicle: {
        id: vehicle.id,
        registration: vehicle.registration,
        make: vehicle.make,
        model: vehicle.model,
        year: vehicle.year,
        vehicleType: vehicle.vehicle_type,
        color: vehicle.color,
        assignedStaffName: assignedDriver?.name || null,
        assignedDriver,
        lastOdometer,
        lastFuel,
        lastCheckIn,
      },
    });
  } catch (error) {
    log.error('Plate verification error', { error });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Staff Disciplinary API
 * GET /api/staff/[staffId]/disciplinary - Get all disciplinary incidents
 * POST /api/staff/[staffId]/disciplinary - Create new disciplinary incident
 * PUT /api/staff/[staffId]/disciplinary?id=xxx - Update disciplinary incident
 * DELETE /api/staff/[staffId]/disciplinary?id=xxx - Delete disciplinary incident
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withArcjetProtection, aj } from '@/lib/arcjet';
import { createLogger } from '@/lib/logger';
import { withAuth } from '@/lib/auth';
import type {
  DisciplinaryIncident,
  DisciplinaryIncidentCreate,
  DisciplinaryIncidentUpdate,
} from '@/types/staff';

const sql = neon(process.env.DATABASE_URL || '');
const logger = createLogger('StaffDisciplinaryAPI');

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { staffId, id } = req.query;

  if (!staffId || typeof staffId !== 'string') {
    return res.status(400).json({ error: 'Staff ID is required' });
  }

  // GET - Fetch disciplinary incidents
  if (req.method === 'GET') {
    try {
      const incidents = await sql`
        SELECT
          d.*,
          CONCAT(i.first_name, ' ', i.last_name) as issued_by_name,
          i.position as issued_by_position
        FROM disciplinary_incidents d
        LEFT JOIN staff i ON i.id = d.issued_by
        WHERE d.staff_id = ${staffId}
        ORDER BY d.incident_date DESC, d.created_at DESC
      `;

      // Fetch witnesses for each incident
      const incidentsWithWitnesses = await Promise.all(
        incidents.map(async (incident) => {
          let witnesses: Array<{ id: string; name: string }> = [];
          if (incident.witness_ids && incident.witness_ids.length > 0) {
            const witnessData = await sql`
              SELECT id, CONCAT(first_name, ' ', last_name) as name
              FROM staff
              WHERE id = ANY(${incident.witness_ids})
            `;
            witnesses = witnessData.map((w) => ({
              id: w.id as string,
              name: w.name as string,
            }));
          }
          return mapDbToIncident(incident, witnesses);
        })
      );

      return res.status(200).json({
        success: true,
        incidents: incidentsWithWitnesses,
        count: incidentsWithWitnesses.length,
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error('Failed to fetch disciplinary incidents', { staffId, error: errorMessage });
      return res.status(500).json({ error: 'Failed to fetch disciplinary incidents', message: errorMessage });
    }
  }

  // POST - Create disciplinary incident
  if (req.method === 'POST') {
    try {
      const body = req.body as DisciplinaryIncidentCreate;

      if (!body.incidentDate || !body.incidentType || !body.description) {
        return res.status(400).json({ error: 'Incident date, type, and description are required' });
      }

      const [created] = await sql`
        INSERT INTO disciplinary_incidents (
          staff_id,
          incident_date,
          incident_type,
          description,
          outcome,
          issued_by,
          witness_ids,
          follow_up_date,
          follow_up_notes,
          attachments
        ) VALUES (
          ${staffId},
          ${body.incidentDate},
          ${body.incidentType},
          ${body.description},
          ${body.outcome || 'pending'},
          ${body.issuedBy || null},
          ${body.witnessIds || []},
          ${body.followUpDate || null},
          ${body.followUpNotes || null},
          ${JSON.stringify(body.attachments || [])}
        )
        RETURNING *
      `;

      if (!created) {
        return res.status(500).json({ error: 'Failed to create disciplinary incident' });
      }

      logger.info('Disciplinary incident created', { staffId, incidentId: created.id });

      // Fetch with joins
      const [incident] = await sql`
        SELECT
          d.*,
          CONCAT(i.first_name, ' ', i.last_name) as issued_by_name,
          i.position as issued_by_position
        FROM disciplinary_incidents d
        LEFT JOIN staff i ON i.id = d.issued_by
        WHERE d.id = ${created.id}
      `;

      return res.status(201).json({
        success: true,
        incident: incident ? mapDbToIncident(incident as Record<string, unknown>, []) : null,
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error('Failed to create disciplinary incident', { staffId, error: errorMessage });
      return res.status(500).json({ error: 'Failed to create disciplinary incident', message: errorMessage });
    }
  }

  // PUT - Update disciplinary incident
  if (req.method === 'PUT') {
    if (!id || typeof id !== 'string') {
      return res.status(400).json({ error: 'Incident ID is required' });
    }

    try {
      const body = req.body as DisciplinaryIncidentUpdate;

      // Verify incident belongs to staff member
      const [existing] = await sql`
        SELECT id FROM disciplinary_incidents
        WHERE id = ${id} AND staff_id = ${staffId}
      `;

      if (!existing) {
        return res.status(404).json({ error: 'Disciplinary incident not found' });
      }

      const [updated] = await sql`
        UPDATE disciplinary_incidents
        SET
          incident_date = COALESCE(${body.incidentDate || null}, incident_date),
          incident_type = COALESCE(${body.incidentType || null}, incident_type),
          description = COALESCE(${body.description || null}, description),
          outcome = COALESCE(${body.outcome || null}, outcome),
          issued_by = COALESCE(${body.issuedBy || null}, issued_by),
          witness_ids = COALESCE(${body.witnessIds || null}, witness_ids),
          follow_up_date = COALESCE(${body.followUpDate || null}, follow_up_date),
          follow_up_notes = COALESCE(${body.followUpNotes || null}, follow_up_notes),
          is_resolved = COALESCE(${body.isResolved ?? null}, is_resolved),
          resolved_date = COALESCE(${body.resolvedDate || null}, resolved_date),
          attachments = COALESCE(${body.attachments ? JSON.stringify(body.attachments) : null}, attachments),
          updated_at = NOW()
        WHERE id = ${id}
        RETURNING *
      `;

      if (!updated) {
        return res.status(500).json({ error: 'Failed to update disciplinary incident' });
      }

      logger.info('Disciplinary incident updated', { staffId, incidentId: id });

      // Fetch with joins
      const [incident] = await sql`
        SELECT
          d.*,
          CONCAT(i.first_name, ' ', i.last_name) as issued_by_name,
          i.position as issued_by_position
        FROM disciplinary_incidents d
        LEFT JOIN staff i ON i.id = d.issued_by
        WHERE d.id = ${updated.id}
      `;

      return res.status(200).json({
        success: true,
        incident: incident ? mapDbToIncident(incident as Record<string, unknown>, []) : null,
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error('Failed to update disciplinary incident', { staffId, id, error: errorMessage });
      return res.status(500).json({ error: 'Failed to update disciplinary incident', message: errorMessage });
    }
  }

  // DELETE - Delete disciplinary incident
  if (req.method === 'DELETE') {
    if (!id || typeof id !== 'string') {
      return res.status(400).json({ error: 'Incident ID is required' });
    }

    try {
      // Verify incident belongs to staff member
      const [existing] = await sql`
        SELECT id FROM disciplinary_incidents
        WHERE id = ${id} AND staff_id = ${staffId}
      `;

      if (!existing) {
        return res.status(404).json({ error: 'Disciplinary incident not found' });
      }

      await sql`DELETE FROM disciplinary_incidents WHERE id = ${id}`;

      logger.info('Disciplinary incident deleted', { staffId, incidentId: id });

      return res.status(200).json({
        success: true,
        message: 'Disciplinary incident deleted',
      });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error('Failed to delete disciplinary incident', { staffId, id, error: errorMessage });
      return res.status(500).json({ error: 'Failed to delete disciplinary incident', message: errorMessage });
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(withArcjetProtection(handler, aj));

// Map database row to DisciplinaryIncident interface
function mapDbToIncident(
  row: Record<string, unknown>,
  witnesses: Array<{ id: string; name: string }>
): DisciplinaryIncident {
  return {
    id: row.id as string,
    staffId: row.staff_id as string,
    incidentDate: (row.incident_date
      ? new Date(row.incident_date as string).toISOString().split('T')[0]
      : '') as string,
    incidentType: row.incident_type as DisciplinaryIncident['incidentType'],
    description: row.description as string,
    outcome: row.outcome as DisciplinaryIncident['outcome'],
    issuedBy: row.issued_by as string | undefined,
    witnessIds: (row.witness_ids as string[]) || [],
    followUpDate: row.follow_up_date
      ? new Date(row.follow_up_date as string).toISOString().split('T')[0]
      : undefined,
    followUpNotes: row.follow_up_notes as string | undefined,
    isResolved: row.is_resolved as boolean,
    resolvedDate: row.resolved_date
      ? new Date(row.resolved_date as string).toISOString().split('T')[0]
      : undefined,
    attachments: typeof row.attachments === 'string'
      ? JSON.parse(row.attachments)
      : (row.attachments as DisciplinaryIncident['attachments']) || [],
    createdAt: new Date(row.created_at as string).toISOString(),
    updatedAt: new Date(row.updated_at as string).toISOString(),
    issuedByStaff: row.issued_by_name
      ? {
          id: row.issued_by as string,
          name: row.issued_by_name as string,
          position: row.issued_by_position as string | undefined,
        }
      : undefined,
    witnesses,
  };
}

/**
 * Staff Compliance Status API
 * GET /api/staff/[staffId]/compliance - Get compliance document status
 */

import type { NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withArcjetProtection, aj } from '@/lib/arcjet';
import { createLogger } from '@/lib/logger';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { SA_CONTRACT_CONFIG, SAContractType, mapLegacyContractType } from '@/types/staff/compliance.types';
import { canAccessStaffDocuments } from '@/services/staff/staffAccessService';

const sql = neon(process.env.DATABASE_URL || '');
const logger = createLogger('StaffComplianceAPI');

// Get required documents based on contract type
function getRequiredDocuments(contractType: SAContractType | null) {
  const config = contractType ? SA_CONTRACT_CONFIG[contractType] : null;
  const isEmployee = config?.isEmployee ?? true; // Default to employee if unknown

  return [
    { type: 'id_document', alternativeTypes: ['sa_id', 'passport'], label: 'ID Document / Passport', required: true },
    {
      type: 'employment_contract',
      alternativeTypes: [],
      label: isEmployee ? 'Employment Contract' : 'IC Agreement',
      required: true
    },
    { type: 'bank_details', alternativeTypes: ['bank_statement'], label: 'Bank Confirmation Letter', required: true },
    {
      type: 'tax_document',
      alternativeTypes: [],
      label: isEmployee ? 'Tax Document (IRP5)' : 'Tax Document (IT3a)',
      required: false
    },
    { type: 'police_clearance', alternativeTypes: [], label: 'Police Clearance', required: false },
    { type: 'drivers_license', alternativeTypes: [], label: "Driver's License", required: false },
    { type: 'medical_certificate', alternativeTypes: [], label: 'Medical Certificate', required: false },
  ];
}

interface DocumentStatus {
  type: string;
  label: string;
  required: boolean;
  uploaded: boolean;
  verified: boolean;
  pending: boolean;
  rejected: boolean;
  expired: boolean;
  documentId?: string;
  documentNumber?: string;
  expiryDate?: string;
  verifiedAt?: string;
}

interface ComplianceStatus {
  isCompliant: boolean;
  requiredComplete: number;
  requiredTotal: number;
  optionalComplete: number;
  optionalTotal: number;
  documents: DocumentStatus[];
  contractType: SAContractType | null;
  isEmployee: boolean;
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { staffId } = req.query;
  const userId = req.user.id;

  if (!staffId || typeof staffId !== 'string') {
    return res.status(400).json({ error: 'Staff ID is required' });
  }

  if (req.method === 'GET') {
    try {
      // Check if user can access compliance data for this staff member
      // Compliance contains bank, tax, UIF info - requires sensitive access or self-view
      const canAccess = await canAccessStaffDocuments(userId, staffId);
      if (!canAccess) {
        return res.status(403).json({
          error: 'Access denied',
          message: 'You do not have permission to view compliance data for this staff member'
        });
      }
      // Fetch staff member's contract type
      const staffResult = await sql`
        SELECT contract_type FROM staff WHERE id = ${staffId}
      `;
      const staffContractType = staffResult[0]?.contract_type as string | null;
      const contractType = staffContractType ? mapLegacyContractType(staffContractType) : null;

      // Get required documents based on contract type
      const requiredDocuments = getRequiredDocuments(contractType);

      // Fetch all documents for this staff member
      const documents = await sql`
        SELECT
          id,
          document_type,
          document_number,
          verification_status,
          verified_at,
          expiry_date
        FROM staff_documents
        WHERE staff_id = ${staffId}
        ORDER BY created_at DESC
      `;

      // Group documents by type and get the best status for each
      const documentsByType = new Map<string, typeof documents[0]>();

      for (const doc of documents) {
        const type = doc.document_type as string;
        const existing = documentsByType.get(type);

        // Prefer verified documents, then pending, then most recent
        if (!existing ||
            (doc.verification_status === 'verified' && existing.verification_status !== 'verified') ||
            (doc.verification_status === 'pending' && existing.verification_status === 'rejected')) {
          documentsByType.set(type, doc);
        }
      }

      // Build compliance status for each required document type
      const documentStatuses: DocumentStatus[] = requiredDocuments.map(reqDoc => {
        // Check primary type first, then alternatives
        let doc = documentsByType.get(reqDoc.type);
        if (!doc && reqDoc.alternativeTypes.length > 0) {
          for (const altType of reqDoc.alternativeTypes) {
            doc = documentsByType.get(altType);
            if (doc) break;
          }
        }

        const now = new Date();

        if (!doc) {
          return {
            type: reqDoc.type,
            label: reqDoc.label,
            required: reqDoc.required,
            uploaded: false,
            verified: false,
            pending: false,
            rejected: false,
            expired: false,
          };
        }

        const expiryDate = doc.expiry_date ? new Date(doc.expiry_date as string) : null;
        const isExpired = expiryDate ? expiryDate < now : false;

        return {
          type: reqDoc.type,
          label: reqDoc.label,
          required: reqDoc.required,
          uploaded: true,
          verified: doc.verification_status === 'verified' && !isExpired,
          pending: doc.verification_status === 'pending',
          rejected: doc.verification_status === 'rejected',
          expired: isExpired,
          documentId: doc.id as string,
          documentNumber: doc.document_number as string | undefined,
          expiryDate: expiryDate?.toISOString(),
          verifiedAt: doc.verified_at ? new Date(doc.verified_at as string).toISOString() : undefined,
        };
      });

      // Calculate compliance summary
      const requiredDocs = documentStatuses.filter(d => d.required);
      const optionalDocs = documentStatuses.filter(d => !d.required);

      const requiredComplete = requiredDocs.filter(d => d.verified).length;
      const requiredTotal = requiredDocs.length;
      const optionalComplete = optionalDocs.filter(d => d.verified).length;
      const optionalTotal = optionalDocs.length;

      // Full compliance requires all required documents to be verified
      const isCompliant = requiredComplete === requiredTotal;

      const config = contractType ? SA_CONTRACT_CONFIG[contractType] : null;
      const complianceStatus: ComplianceStatus = {
        isCompliant,
        requiredComplete,
        requiredTotal,
        optionalComplete,
        optionalTotal,
        documents: documentStatuses,
        contractType,
        isEmployee: config?.isEmployee ?? true,
      };

      return res.status(200).json(complianceStatus);
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      logger.error('Failed to fetch compliance status', { staffId, error: errorMessage });
      return res.status(500).json({ error: 'Failed to fetch compliance status', message: errorMessage });
    }
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

export default withAuth(withArcjetProtection(handler, aj));

