/**
 * Expiring Documents API
 * GET /api/staff-documents/expiring
 * Get documents expiring within N days
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withArcjetProtection, aj } from '@/lib/arcjet';
import { withAuth } from '@/lib/auth';
import { createLogger } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL || '');
const logger = createLogger('ExpiringDocumentsAPI');

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const { days = '30', staffId } = req.query;

    const daysNum = parseInt(days as string, 10);
    if (isNaN(daysNum) || daysNum < 1 || daysNum > 365) {
      return res.status(400).json({
        error: 'Invalid days parameter. Must be between 1 and 365',
      });
    }

    let documents;

    if (staffId && typeof staffId === 'string') {
      // Get expiring documents for specific staff member
      documents = await sql`
        SELECT
          sd.*,
          s.name as staff_name,
          s.email as staff_email
        FROM staff_documents sd
        LEFT JOIN staff s ON s.id = sd.staff_id
        WHERE sd.staff_id = ${staffId}
          AND sd.expiry_date IS NOT NULL
          AND sd.expiry_date <= CURRENT_DATE + INTERVAL '1 day' * ${daysNum}
          AND sd.expiry_date >= CURRENT_DATE
          AND sd.verification_status != 'expired'
        ORDER BY sd.expiry_date ASC
      `;
    } else {
      // Get all expiring documents
      documents = await sql`
        SELECT
          sd.*,
          s.name as staff_name,
          s.email as staff_email
        FROM staff_documents sd
        LEFT JOIN staff s ON s.id = sd.staff_id
        WHERE sd.expiry_date IS NOT NULL
          AND sd.expiry_date <= CURRENT_DATE + INTERVAL '1 day' * ${daysNum}
          AND sd.expiry_date >= CURRENT_DATE
          AND sd.verification_status != 'expired'
        ORDER BY sd.expiry_date ASC
      `;
    }

    // Also get already expired documents
    let expiredDocuments;
    if (staffId && typeof staffId === 'string') {
      expiredDocuments = await sql`
        SELECT
          sd.*,
          s.name as staff_name,
          s.email as staff_email
        FROM staff_documents sd
        LEFT JOIN staff s ON s.id = sd.staff_id
        WHERE sd.staff_id = ${staffId}
          AND sd.expiry_date IS NOT NULL
          AND sd.expiry_date < CURRENT_DATE
        ORDER BY sd.expiry_date DESC
      `;
    } else {
      expiredDocuments = await sql`
        SELECT
          sd.*,
          s.name as staff_name,
          s.email as staff_email
        FROM staff_documents sd
        LEFT JOIN staff s ON s.id = sd.staff_id
        WHERE sd.expiry_date IS NOT NULL
          AND sd.expiry_date < CURRENT_DATE
        ORDER BY sd.expiry_date DESC
      `;
    }

    // Calculate days until expiry for each document
    const now = new Date();
    const enrichedDocuments = documents.map((doc: Record<string, unknown>) => {
      const expiryDate = new Date(doc.expiry_date as string);
      const diffTime = expiryDate.getTime() - now.getTime();
      const daysUntilExpiry = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      return {
        ...mapDbToDocument(doc),
        daysUntilExpiry,
        urgency: daysUntilExpiry <= 7 ? 'critical' : daysUntilExpiry <= 30 ? 'warning' : 'info',
      };
    });

    const enrichedExpired = expiredDocuments.map((doc: Record<string, unknown>) => {
      const expiryDate = new Date(doc.expiry_date as string);
      const diffTime = now.getTime() - expiryDate.getTime();
      const daysExpired = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      return {
        ...mapDbToDocument(doc),
        daysExpired,
        urgency: 'expired',
      };
    });

    return res.status(200).json({
      success: true,
      expiring: enrichedDocuments,
      expired: enrichedExpired,
      summary: {
        expiringCount: enrichedDocuments.length,
        expiredCount: enrichedExpired.length,
        criticalCount: enrichedDocuments.filter((d: { urgency: string }) => d.urgency === 'critical').length,
        warningCount: enrichedDocuments.filter((d: { urgency: string }) => d.urgency === 'warning').length,
      },
    });
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Failed to fetch expiring documents', { error: errorMessage });
    return res.status(500).json({ error: 'Failed to fetch expiring documents', message: errorMessage });
  }
}

export default withAuth(withArcjetProtection(handler, aj));

// Map database row to StaffDocument interface
function mapDbToDocument(row: Record<string, unknown>) {
  return {
    id: row.id,
    staffId: row.staff_id,
    documentType: row.document_type,
    documentName: row.document_name,
    fileUrl: row.file_url,
    fileSize: row.file_size,
    mimeType: row.mime_type,
    expiryDate: row.expiry_date ? new Date(row.expiry_date as string).toISOString() : undefined,
    issuedDate: row.issued_date ? new Date(row.issued_date as string).toISOString() : undefined,
    issuingAuthority: row.issuing_authority,
    documentNumber: row.document_number,
    verificationStatus: row.verification_status,
    verifiedBy: row.verified_by,
    verifiedAt: row.verified_at ? new Date(row.verified_at as string).toISOString() : undefined,
    verificationNotes: row.verification_notes,
    createdAt: new Date(row.created_at as string).toISOString(),
    updatedAt: new Date(row.updated_at as string).toISOString(),
    staff: row.staff_name
      ? {
          id: row.staff_id,
          name: row.staff_name,
          email: row.staff_email,
        }
      : undefined,
  };
}

/**
 * Project H&S Summary API
 * GET /api/projects/[projectId]/hs-summary
 *
 * Returns H&S audit summary and compliance status
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const getSql = () => neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { projectId } = req.query;

  if (!projectId || typeof projectId !== 'string') {
    return apiResponse.validationError(res, { projectId: 'Project ID is required' });
  }

  try {
    const sql = getSql();

    // Check project exists
    const projectExists = await sql`
      SELECT id FROM projects WHERE id = ${projectId}
    `;

    if (!projectExists || projectExists.length === 0) {
      return apiResponse.notFound(res, 'Project', projectId);
    }

    // Get latest audit
    const latestAudit = await sql`
      SELECT
        id,
        overall_score,
        audit_type,
        status,
        conducted_by,
        created_at
      FROM hs_project_audits
      WHERE project_id = ${projectId}
      ORDER BY created_at DESC
      LIMIT 1
    `;

    // Get audit history stats
    const auditStats = await sql`
      SELECT
        COUNT(*) as total_audits,
        AVG(overall_score) as avg_score,
        MIN(overall_score) as min_score,
        MAX(overall_score) as max_score,
        COUNT(*) FILTER (WHERE overall_score >= 80) as passing_audits
      FROM hs_project_audits
      WHERE project_id = ${projectId}
    `;

    // Get incident counts
    const incidents = await sql`
      SELECT
        COUNT(*) as total,
        COUNT(*) FILTER (WHERE severity = 'critical') as critical,
        COUNT(*) FILTER (WHERE severity = 'high') as high,
        COUNT(*) FILTER (WHERE severity = 'medium') as medium,
        COUNT(*) FILTER (WHERE severity = 'low') as low,
        COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '30 days') as last_30_days
      FROM hs_incidents
      WHERE project_id = ${projectId}
    `;

    // Determine compliance status
    const latestScore = latestAudit[0]?.overall_score;
    let complianceStatus: 'compliant' | 'non-compliant' | 'unknown' = 'unknown';

    if (latestScore !== null && latestScore !== undefined) {
      complianceStatus = Number(latestScore) >= 80 ? 'compliant' : 'non-compliant';
    }

    // Format response
    const response = {
      latestScore: latestScore ? Number(latestScore) : null,
      lastAuditDate: latestAudit[0]?.created_at?.toISOString() || null,
      lastAuditType: latestAudit[0]?.audit_type || null,
      lastAuditStatus: latestAudit[0]?.status || null,
      complianceStatus,

      totalAudits: Number(auditStats[0]?.total_audits) || 0,
      avgScore: auditStats[0]?.avg_score
        ? Math.round(Number(auditStats[0].avg_score) * 10) / 10
        : null,
      passingAudits: Number(auditStats[0]?.passing_audits) || 0,

      incidents: {
        total: Number(incidents[0]?.total) || 0,
        critical: Number(incidents[0]?.critical) || 0,
        high: Number(incidents[0]?.high) || 0,
        medium: Number(incidents[0]?.medium) || 0,
        low: Number(incidents[0]?.low) || 0,
        last30Days: Number(incidents[0]?.last_30_days) || 0,
      },
    };

    return apiResponse.success(res, response);
  } catch (error) {
    log.error('Error fetching H&S summary', { error, projectId });
    return apiResponse.internalError(res, error as Error);
  }
}

