/**
 * Data Sync Page
 * Unified data sync management page combining maintenance, activate, and OLT report syncs
 *
 * URL Structure:
 * - /system/data-sync - Overview dashboard
 * - /system/data-sync?group=maintenance - Maintenance tabs
 * - /system/data-sync?group=activate - Activate tabs
 * - /system/data-sync?group=olt - OLT Report tabs
 */

import Head from 'next/head';
import { AppLayout } from '@/components/layout/AppLayout';
import { DataSyncPage } from '@/modules/data-sync';
import { usePermission } from '@/hooks/usePermission';
import { AlertTriangle, Loader2 } from 'lucide-react';

export default function DataSyncRoute() {
  const { can, isLoading } = usePermission();

  // Check RBAC permission for data-sync page
  const hasAccess = can('system.data-sync', 'view');

  // Show loading while checking permissions
  if (isLoading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="w-8 h-8 animate-spin text-[var(--ff-accent)]" />
        </div>

/**
 * Singleton Database Connection Pool
 *
 * Provides a shared PostgreSQL connection pool to prevent connection exhaustion
 * under load. All API routes should import this instead of creating their own pools.
 *
 * @example
 * ```typescript
 * import pool from '@/lib/db';
 *
 * const result = await pool.query('SELECT * FROM users');
 * ```
 *
 * For transactions:
 * ```typescript
 * const client = await pool.connect();
 * try {
 *   await client.query('BEGIN');
 *   // ... transaction queries
 *   await client.query('COMMIT');
 * } finally {
 *   client.release();
 * }
 * ```
 */

import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false },
});

export default pool;
export { pool };
/** Alias for pool — used by system services that import { db } */
export const db = pool;

/**
 * Neon HTTP Driver — Singleton with Connection Pooling
 *
 * Sets neonConfig.fetchConnectionCache = true globally so all neon() calls
 * reuse HTTP connections rather than opening a new connection per query.
 *
 * This resolves resource leak risk from 450+ direct neon() calls across the
 * codebase without requiring any query rewrites or API changes.
 *
 * Usage — replace:
 *   import { neon } from '@neondatabase/serverless';
 * with:
 *   import { neon } from '@/lib/db-neon';
 *
 * All existing sql`template literal` usage remains unchanged.
 *
 * @see https://neon.tech/docs/serverless/serverless-driver#use-the-cache-option
 */

import { neon, neonConfig, NeonQueryFunction } from '@neondatabase/serverless';

// Enable HTTP connection caching globally — reuses connections across queries
// rather than establishing a new HTTP connection per neon() call.
neonConfig.fetchConnectionCache = true;

export { neon, neonConfig };
export type { NeonQueryFunction };

/**
 * Cron Job: Auto-QA Pipeline
 *
 * GET/POST /api/cron/auto-qa
 *
 * Runs every 5 minutes. Finds DRs eligible for automated QA
 * (30+ min since WA receipt, photos categorized, data extracted)
 * and processes them through phases 1-4 programmatically.
 *
 * DRs are parked at phase 5 (feedback) for human review before
 * WhatsApp feedback is sent.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { findEligibleDRs, processOneDR, type AutoQaProcessResult } from '@/modules/activate/services/autoQaProcessor';

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'GET' && req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
  }

  // Always require bearer token regardless of environment
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('AutoQaCron', 'CRON_SECRET environment variable not configured');
    return apiResponse.error(res, ErrorCode.INTERNAL_ERROR, 'Server misconfigured: CRON_SECRET not set');
  }

  const authHeader = req.headers.authorization;
  if (authHeader !== `Bearer ${cronSecret}`) {
    log.error('AutoQaCron', 'Unauthorized request');
    return apiResponse.unauthorized(res, 'Invalid or missing cron secret');
  }

  const limit = Number(req.query.limit) || Number(req.body?.limit) || 10;

  log.info('AutoQaCron', `Starting auto-QA processing (limit: ${limit})`);

  try {
    const eligibleDRs = await findEligibleDRs(limit);

    if (eligibleDRs.length === 0) {
      log.info('AutoQaCron', 'No DRs eligible for auto-QA');
      return apiResponse.success(res, {
        processed: 0,
        succeeded: 0,
        failed: 0,
        skipped: 0,
        results: [] as AutoQaProcessResult[],
        timestamp: new Date().toISOString(),
      });
    }

    log.info('AutoQaCron', `Found ${eligibleDRs.length} eligible DRs`);

    const results: AutoQaProcessResult[] = [];
    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    // Process sequentially (no VLM calls, just DB reads + in-memory logic)
    for (const dr of eligibleDRs) {
      const result = await processOneDR(dr.drop_number);
      results.push(result);

      if (result.skipped) {
        skipped++;
      } else if (result.success) {
        succeeded++;
      } else {
        failed++;
      }
    }

    log.info('AutoQaCron', `Completed: ${succeeded} succeeded, ${skipped} skipped, ${failed} failed`);

    return apiResponse.success(res, {
      processed: eligibleDRs.length,
      succeeded,
      failed,
      skipped,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    log.error('AutoQaCron', `Fatal error: ${error instanceof Error ? error.message : String(error)}`);
    return apiResponse.internalError(res, error);
  }
}

/**
 * Cron Job: Backfill Missing OneMap Data
 *
 * POST /api/cron/backfill-onemap-data
 *
 * Purpose: Find DRs with missing photos/serials and fetch from OneMap
 *
 * This cron job handles the backfill case where:
 * - DRs exist in dr_photo_unified_reviews but have photo_count = 0
 * - DRs have no ONT/UPS serials even though data exists in OneMap
 *
 * Run schedule: Every 15 minutes (via vercel.json or external cron)
 * Limit: Processes up to 20 DRs per run to avoid timeout
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import { photoTypeToStep } from '@/modules/activate/utils/stepMapper';

const ONEMAP_HOST = process.env.ONEMAP_HOST || 'http://100.96.203.105:8003';

interface BackfillResult {
  dropNumber: string;
  success: boolean;
  photoCount: number;
  ontSerial: string | null;
  upsSerial: string | null;
  error?: string;
}

interface BackfillResponse {
  success: boolean;
  processed: number;
  succeeded: number;
  failed: number;
  results: BackfillResult[];
  timestamp: string;
}

/**
 * Fetch data from OneMap and update unified table
 */
async function fetchAndUpdateFromOneMap(dropNumber: string): Promise<BackfillResult> {
  const result: BackfillResult = {
    dropNumber,
    success: false,
    photoCount: 0,
    ontSerial: null,
    upsSerial: null,
  };

  try {
    // Try to get record from OneMap
    let response = await fetch(`${ONEMAP_HOST}/api/record/${dropNumber}`, {
      signal: AbortSignal.timeout(10000), // 10s timeout
    });

    // If 404, try to trigger download
    if (response.status === 404 || response.status === 422) {
      log.info('BackfillOneMap', `Record not found, triggering download for ${dropNumber}`);

      const downloadResponse = await fetch(`${ONEMAP_HOST}/api/download/${dropNumber}`, {
        method: 'POST',
        signal: AbortSignal.timeout(15000), // 15s timeout for download
      });

      if (downloadResponse.ok) {
        // Wait a moment for photos to be available
        await new Promise((resolve) => setTimeout(resolve, 2000));

        // Retry fetch
        response = await fetch(`${ONEMAP_HOST}/api/record/${dropNumber}`, {
          signal: AbortSignal.timeout(10000),
        });
      }
    }

    if (!response.ok) {
      result.error = `OneMap API returned ${response.status}`;
      return result;
    }

    const data = await response.json();
    let localPhotos = data.local_photos || [];

    // If record exists but no local photos, try downloading
    if (localPhotos.length === 0 && data.photo_count > 0) {
      log.info('BackfillOneMap', `Photos on cloud but not local for ${dropNumber}, triggering download`);

      await fetch(`${ONEMAP_HOST}/api/download/${dropNumber}`, {
        method: 'POST',
        signal: AbortSignal.timeout(15000),
      });

      // Wait and retry
      await new Promise((resolve) => setTimeout(resolve, 3000));

      const retryResponse = await fetch(`${ONEMAP_HOST}/api/record/${dropNumber}`, {
        signal: AbortSignal.timeout(10000),
      });

      if (retryResponse.ok) {
        const retryData = await retryResponse.json();
        localPhotos = retryData.local_photos || [];
        // Also update serials from retried data
        if (retryData.ont_barcode) data.ont_barcode = retryData.ont_barcode;
        if (retryData.ups_serial) data.ups_serial = retryData.ups_serial;
      }
    }

    // Map photos to our format
    const photos = localPhotos.map((photo: any) => ({
      filename: photo.filename,
      step: photoTypeToStep(photo.type) ?? 0,
      url: `/api/activate/photo/${dropNumber}/${photo.filename}`,
      size: photo.size,
      modified: photo.modified,
      original_type: photo.type,
    }));

    // Extract ONT serial from barcode data
    const ontSerial = extractOntSerial(data.ont_barcode);
    const upsSerial = data.ups_serial || null;

    // Update unified table
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET
         photo_source = 'onemap',
         photo_count = $1,
         photos_metadata = $2,
         ont_serial_scanned = COALESCE($3, ont_serial_scanned),
         ups_serial_scanned = COALESCE($4, ups_serial_scanned),
         updated_at = NOW()
       WHERE drop_number = $5`,
      [photos.length, JSON.stringify(photos), ontSerial, upsSerial, dropNumber]
    );

    result.success = true;
    result.photoCount = photos.length;
    result.ontSerial = ontSerial;
    result.upsSerial = upsSerial;

    log.info('BackfillOneMap', `Updated ${dropNumber}`, {
      photoCount: photos.length,
      ontSerial,
      upsSerial,
    });

    return result;
  } catch (error) {
    result.error = error instanceof Error ? error.message : 'Unknown error';
    log.error('BackfillOneMap', `Error processing ${dropNumber}`, { error: result.error });
    return result;
  }
}

/**
 * Extract ONT serial from barcode data
 * Format: (S)SERIAL(23S)CODE... → extracts SERIAL
 */
function extractOntSerial(barcodeData: string | null): string | null {
  if (!barcodeData) return null;

  // Pattern: (S)SERIAL(23S)...
  const serialMatch = barcodeData.match(/\(S\)([^(]+)/);
  if (serialMatch && serialMatch[1]) {
    return serialMatch[1].trim();
  }

  // If no pattern, return raw barcode (might already be clean serial)
  if (!barcodeData.includes('(')) {
    return barcodeData.trim();
  }

  return null;
}

/**
 * Main handler
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<BackfillResponse | { error: string }>
): Promise<void> {
  // Accept both GET and POST for flexibility
  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', ['GET', 'POST']);
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // Verify cron secret in production (if configured)
  const authHeader = req.headers.authorization;
  const cronSecret = process.env.CRON_SECRET;

  if (process.env.NODE_ENV === 'production' && cronSecret) {
    if (authHeader !== `Bearer ${cronSecret}`) {
      log.error('BackfillOneMap', 'Unauthorized request');
      return res.status(401).json({ error: 'Unauthorized' });
    }
  }

  const limit = Number(req.query.limit) || Number(req.body?.limit) || 20;
  const mode = (req.query.mode as string) || (req.body?.mode as string) || 'missing_photos';

  log.info('BackfillOneMap', `Starting backfill job (limit: ${limit}, mode: ${mode})`);

  try {
    // Find DRs that need backfill
    let query = '';

    switch (mode) {
      case 'missing_photos':
        // DRs with no photos
        query = `
          SELECT drop_number
          FROM dr_photo_unified_reviews
          WHERE (photo_count IS NULL OR photo_count = 0)
            AND created_at > NOW() - INTERVAL '30 days'
          ORDER BY created_at DESC
          LIMIT $1
        `;
        break;

      case 'missing_serials':
        // DRs missing serials (regardless of photo count - serials come from 1Map API)
        query = `
          SELECT drop_number
          FROM dr_photo_unified_reviews
          WHERE (ont_serial_scanned IS NULL OR ont_serial_scanned = '')
            AND created_at > NOW() - INTERVAL '30 days'
          ORDER BY created_at DESC
          LIMIT $1
        `;
        break;

      case 'all_missing':
      default:
        // DRs missing either photos OR serials
        query = `
          SELECT drop_number
          FROM dr_photo_unified_reviews
          WHERE (
            (photo_count IS NULL OR photo_count = 0)
            OR (ont_serial_scanned IS NULL AND ups_serial_scanned IS NULL)
          )
            AND created_at > NOW() - INTERVAL '30 days'
          ORDER BY created_at DESC
          LIMIT $1
        `;
        break;
    }

    const pendingResult = await pool.query(query, [limit]);
    const pendingDRs = pendingResult.rows;

    if (pendingDRs.length === 0) {
      log.info('BackfillOneMap', 'No DRs need backfill');
      return res.status(200).json({
        success: true,
        processed: 0,
        succeeded: 0,
        failed: 0,
        results: [],
        timestamp: new Date().toISOString(),
      });
    }

    log.info('BackfillOneMap', `Found ${pendingDRs.length} DRs to process`);

    const results: BackfillResult[] = [];
    let succeeded = 0;
    let failed = 0;

    // Process each DR sequentially (to avoid overwhelming OneMap API)
    for (const row of pendingDRs) {
      const result = await fetchAndUpdateFromOneMap(row.drop_number);
      results.push(result);

      if (result.success && (result.photoCount > 0 || result.ontSerial || result.upsSerial)) {
        succeeded++;
      } else {
        failed++;
      }

      // Small delay between requests to be nice to OneMap
      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    log.info('BackfillOneMap', `Completed: ${succeeded}/${pendingDRs.length} succeeded`, {
      failed,
      results: results.slice(0, 5), // Log first 5 for brevity
    });

    return res.status(200).json({
      success: true,
      processed: pendingDRs.length,
      succeeded,
      failed,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    log.error('BackfillOneMap', 'Fatal error during backfill', { error });
    return res.status(500).json({
      error: error instanceof Error ? error.message : 'Failed to run backfill',
    });
  }
}

// 🟢 WORKING: Cron — enables auto-recording on upcoming Teams meetings
// Scans org calendars for the next 24h and PATCHes meetings to record automatically
// Schedule: every 30 minutes via system cron
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { enableAutoRecordingForUpcomingMeetings } from '@/lib/graph/auto-recording';

const LOGGER = 'AutoRecordCron';

/**
 * POST /api/cron/enable-auto-recording
 *
 * Scans all org users' upcoming Teams meetings (next 24h) and enables
 * auto-recording via Graph API PATCH.
 *
 * Auth: CRON_SECRET bearer token.
 * Schedule: every 30 minutes via system cron.
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/enable-auto-recording \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const hoursAhead = typeof req.body?.hours === 'number' ? req.body.hours : 24;
    const result = await enableAutoRecordingForUpcomingMeetings(hoursAhead);

    log.info('Auto-recording cron complete', result, LOGGER);

    res.status(200).json({ success: true, ...result });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Auto-recording cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

/**
 * Fleet Check-In Reminders Cron Job
 * Sends daily and weekly check reminders to drivers
 *
 * Schedule: 0 7 * * 1-6 (7 AM Mon-Sat)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  getVehiclesNeedingDailyCheck,
  getVehiclesNeedingWeeklyCheck,
  markReminderSent,
  getCheckSchedule,
} from '@/modules/fleet/services/checkInService';
import type { CheckType } from '@/modules/fleet/types/check-in.types';

const sql = neon(process.env.DATABASE_URL!);

// WAHA WhatsApp API configuration
const WAHA_API_URL = process.env.WAHA_API_URL || 'http://100.96.203.105:3001';
const WAHA_SESSION = process.env.WAHA_SESSION || 'default';

// Resend Email API
const RESEND_API_KEY = process.env.RESEND_API_KEY;
const FROM_EMAIL = 'noreply@fibreflow.app';

interface VehicleWithDriver {
  vehicleId: string;
  registration: string;
  make: string | null;
  model: string | null;
  driverId: string;
  driverName: string;
  driverEmail: string | null;
  driverPhone: string | null;
}

// Database row type (snake_case)
interface VehicleWithDriverRow {
  vehicle_id: string;
  registration: string;
  make: string | null;
  model: string | null;
  driver_id: string;
  driver_name: string;
  driver_email: string | null;
  driver_phone: string | null;
}

/**
 * Get vehicles with assigned drivers
 */
async function getVehiclesWithDrivers(): Promise<VehicleWithDriver[]> {
  const rows = await sql`
    SELECT
      v.id as vehicle_id,
      v.registration,
      v.make,
      v.model,
      s.id as driver_id,
      s.name as driver_name,
      s.email as driver_email,
      s.phone as driver_phone
    FROM fleet_vehicles v
    JOIN staff s ON s.id = v.assigned_driver_id
    WHERE v.status = 'active'
    AND v.assigned_driver_id IS NOT NULL
  ` as VehicleWithDriverRow[];

  return rows.map(r => ({
    vehicleId: r.vehicle_id,
    registration: r.registration,
    make: r.make,
    model: r.model,
    driverId: r.driver_id,
    driverName: r.driver_name,
    driverEmail: r.driver_email,
    driverPhone: r.driver_phone,
  }));
}

/**
 * Send WhatsApp reminder
 */
async function sendWhatsAppReminder(
  phone: string,
  message: string
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  try {
    // Format phone number (remove spaces, ensure country code)
    let formattedPhone = phone.replace(/\s+/g, '');
    if (formattedPhone.startsWith('0')) {
      formattedPhone = '27' + formattedPhone.substring(1); // South Africa
    }
    if (!formattedPhone.startsWith('+')) {
      formattedPhone = '+' + formattedPhone;
    }

    const response = await fetch(`${WAHA_API_URL}/api/sendText`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session: WAHA_SESSION,
        chatId: `${formattedPhone.replace('+', '')}@c.us`,
        text: message,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      return { success: false, error };
    }

    const data = await response.json();
    return { success: true, messageId: data.id };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * Send email reminder
 */
async function sendEmailReminder(
  email: string,
  subject: string,
  message: string
): Promise<{ success: boolean; messageId?: string; error?: string }> {
  if (!RESEND_API_KEY) {
    return { success: false, error: 'Resend API key not configured' };
  }

  try {
    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${RESEND_API_KEY}`,
      },
      body: JSON.stringify({
        from: FROM_EMAIL,
        to: email,
        subject,
        text: message,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      return { success: false, error };
    }

    const data = await response.json();
    return { success: true, messageId: data.id };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

/**
 * Build reminder message
 */
function buildReminderMessage(
  checkType: CheckType,
  driverName: string,
  registration: string,
  make: string | null,
  model: string | null
): string {
  const vehicleDesc = [registration, make, model].filter(Boolean).join(' ');
  const checkUrl = `${process.env.NEXT_PUBLIC_APP_URL || 'https://app.fibreflow.app'}/fleet/check-in`;

  if (checkType === 'weekly') {
    return `Hi ${driverName},

It's Monday - time for your weekly vehicle inspection!

Vehicle: ${vehicleDesc}

Please complete the full pre-trip inspection checklist including:
- Exterior check (tyres, lights, mirrors)
- Interior check (seats, doors, seatbelts)
- Switch-on check (warning lights, horn)

Open FibreFlow to start: ${checkUrl}`;
  }

  return `Hi ${driverName},

Please complete your daily vehicle check for ${registration}.

Quick check required:
- Odometer photo
- Fuel gauge photo

Open FibreFlow: ${checkUrl}`;
}

/**
 * Log reminder to database
 */
async function logReminder(
  vehicleId: string,
  driverId: string,
  checkType: CheckType,
  channel: 'whatsapp' | 'email',
  messageId: string | null,
  status: 'sent' | 'failed'
): Promise<void> {
  await sql`
    INSERT INTO fleet_check_reminders (
      vehicle_id, driver_id, check_type, reminder_channel,
      message_id, delivery_status
    )
    VALUES (
      ${vehicleId}, ${driverId}, ${checkType}, ${channel},
      ${messageId}, ${status}
    )
  `;
}

/**
 * Send reminder to a driver (WhatsApp primary, Email fallback)
 */
async function sendReminder(
  vehicle: VehicleWithDriver,
  checkType: CheckType
): Promise<{ success: boolean; channel?: string }> {
  const message = buildReminderMessage(
    checkType,
    vehicle.driverName,
    vehicle.registration,
    vehicle.make,
    vehicle.model
  );

  // Try WhatsApp first
  if (vehicle.driverPhone) {
    const waResult = await sendWhatsAppReminder(vehicle.driverPhone, message);
    if (waResult.success) {
      await logReminder(
        vehicle.vehicleId,
        vehicle.driverId,
        checkType,
        'whatsapp',
        waResult.messageId || null,
        'sent'
      );
      await markReminderSent(vehicle.vehicleId, checkType);
      return { success: true, channel: 'whatsapp' };
    }
    log.warn('FleetReminders', `WhatsApp failed for ${vehicle.driverName}: ${waResult.error}`);
  }

  // Fallback to email
  if (vehicle.driverEmail) {
    const subject = checkType === 'weekly'
      ? `Weekly Vehicle Inspection Required - ${vehicle.registration}`
      : `Daily Vehicle Check Required - ${vehicle.registration}`;

    const emailResult = await sendEmailReminder(vehicle.driverEmail, subject, message);
    if (emailResult.success) {
      await logReminder(
        vehicle.vehicleId,
        vehicle.driverId,
        checkType,
        'email',
        emailResult.messageId || null,
        'sent'
      );
      await markReminderSent(vehicle.vehicleId, checkType);
      return { success: true, channel: 'email' };
    }
    log.warn('FleetReminders', `Email failed for ${vehicle.driverName}: ${emailResult.error}`);
  }

  // Both failed
  await logReminder(
    vehicle.vehicleId,
    vehicle.driverId,
    checkType,
    'whatsapp',
    null,
    'failed'
  );
  return { success: false };
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Verify cron secret (optional security)
  const cronSecret = req.headers['x-cron-secret'];
  if (process.env.CRON_SECRET && cronSecret !== process.env.CRON_SECRET) {
    return apiResponse.unauthorized(res, 'Invalid cron secret');
  }

  const today = new Date();
  const dayOfWeek = today.getDay(); // 0=Sun, 1=Mon

  // Skip Sundays
  if (dayOfWeek === 0) {
    return apiResponse.success(res, { message: 'Sunday - no reminders sent', sent: 0 });
  }

  log.info('FleetReminders', `Starting reminder job for ${today.toISOString().split('T')[0]}`);

  try {
    const vehicles = await getVehiclesWithDrivers();
    log.info('FleetReminders', `Found ${vehicles.length} vehicles with assigned drivers`);

    let sentCount = 0;
    let failedCount = 0;
    const results: Array<{
      vehicle: string;
      driver: string;
      checkType: CheckType;
      success: boolean;
      channel?: string;
    }> = [];

    // Monday = Weekly check day
    if (dayOfWeek === 1) {
      const needsWeekly = await getVehiclesNeedingWeeklyCheck();
      log.info('FleetReminders', `${needsWeekly.length} vehicles need weekly check`);

      for (const vehicle of vehicles) {
        if (needsWeekly.includes(vehicle.vehicleId)) {
          const schedule = await getCheckSchedule(vehicle.vehicleId);
          if (!schedule?.reminderSentWeekly) {
            const result = await sendReminder(vehicle, 'weekly');
            results.push({
              vehicle: vehicle.registration,
              driver: vehicle.driverName,
              checkType: 'weekly',
              success: result.success,
              channel: result.channel,
            });
            if (result.success) sentCount++;
            else failedCount++;
          }
        }
      }
    }

    // Daily check for remaining vehicles
    const needsDaily = await getVehiclesNeedingDailyCheck();
    log.info('FleetReminders', `${needsDaily.length} vehicles need daily check`);

    for (const vehicle of vehicles) {
      if (needsDaily.includes(vehicle.vehicleId)) {
        const schedule = await getCheckSchedule(vehicle.vehicleId);
        if (!schedule?.reminderSentDaily) {
          const result = await sendReminder(vehicle, 'daily');
          results.push({
            vehicle: vehicle.registration,
            driver: vehicle.driverName,
            checkType: 'daily',
            success: result.success,
            channel: result.channel,
          });
          if (result.success) sentCount++;
          else failedCount++;
        }
      }
    }

    log.info('FleetReminders', `Reminder job complete: ${sentCount} sent, ${failedCount} failed`);

    return apiResponse.success(res, {
      date: today.toISOString().split('T')[0],
      sent: sentCount,
      failed: failedCount,
      results,
    });
  } catch (error) {
    log.error('FleetReminders', `Reminder job failed: ${error}`);
    return apiResponse.internalError(res, error);
  }
}

