// Cron: Manage presence subscriptions — renew every 45 minutes (60-min max lifetime)
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { neon } from '@/lib/db-neon';
import { graphFetch } from '@/lib/graph/auth';
import { createPresenceSubscription } from '@/lib/graph/presence';

const sql = neon(process.env.DATABASE_URL!);
const GRAPH_BASE = 'https://graph.microsoft.com/v1.0';
const LOGGER = 'PresenceSubCron';

const PRESENCE_WEBHOOK_URL = 'https://app.fibreflow.app/api/meetings/presence-webhook';

/**
 * POST /api/cron/manage-presence-subscriptions
 *
 * Manages presence webhook subscriptions:
 *   1. Creates a new subscription if none exists
 *   2. Renews existing subscriptions expiring in the next 15 minutes
 *   3. Cleans up expired subscriptions
 *
 * Schedule: Every 45 minutes (presence subs max lifetime = 60 min)
 *
 * Auth: CRON_SECRET bearer token
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;
  const authHeader = req.headers.authorization;
  if (!cronSecret || !authHeader || authHeader !== `Bearer ${cronSecret}`) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    let renewed = 0;
    let created = 0;
    let failed = 0;
    let cleaned = 0;

    // Clean up expired presence subscriptions
    const expiredRows = await sql`
      UPDATE graph_subscriptions
      SET status = 'expired'
      WHERE resource = 'presence'
        AND status = 'active'
        AND expires_at < NOW()
      RETURNING subscription_id
    `;
    cleaned = expiredRows.length;

    // Check for active presence subscriptions
    const activeRows = await sql`
      SELECT subscription_id, expires_at
      FROM graph_subscriptions
      WHERE resource = 'presence'
        AND status = 'active'
        AND expires_at > NOW()
    `;

    if (activeRows.length === 0) {
      // No active presence subscription — create one
      log.info('No active presence subscription — creating new one', {}, LOGGER);
      try {
        await createPresenceSubscription(PRESENCE_WEBHOOK_URL);
        created++;
      } catch (err: unknown) {
        failed++;
        const msg = err instanceof Error ? err.message : String(err);
        log.error('Failed to create presence subscription', { error: msg }, LOGGER);
      }
    } else {
      // Renew subscriptions expiring in the next 15 minutes
      for (const row of activeRows) {
        const expiresAt = new Date(row.expires_at as string);
        const fifteenMinFromNow = new Date(Date.now() + 15 * 60 * 1000);

        if (expiresAt < fifteenMinFromNow) {
          try {
            const newExpiry = new Date(Date.now() + 60 * 60 * 1000);
            const response = await graphFetch(
              `${GRAPH_BASE}/subscriptions/${row.subscription_id}`,
              {
                method: 'PATCH',
                body: JSON.stringify({ expirationDateTime: newExpiry.toISOString() }),
              }
            );

            if (response.ok) {
              await sql`
                UPDATE graph_subscriptions
                SET expires_at = ${newExpiry.toISOString()}, renewed_at = NOW()
                WHERE subscription_id = ${row.subscription_id as string}
              `;
              renewed++;
            } else {
              // Renewal failed — delete old and create new
              await sql`
                UPDATE graph_subscriptions
                SET status = 'expired'
                WHERE subscription_id = ${row.subscription_id as string}
              `;
              await createPresenceSubscription(PRESENCE_WEBHOOK_URL);
              created++;
            }
          } catch (err: unknown) {
            failed++;
            const msg = err instanceof Error ? err.message : String(err);
            log.warn('Presence subscription renewal failed', { error: msg }, LOGGER);
          }
        }
      }
    }

    const result = { active: activeRows.length, renewed, created, failed, cleaned };
    log.info('Presence subscription management complete', result, LOGGER);

    res.status(200).json({ success: true, ...result });
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    log.error('Presence subscription cron failed', { error: msg }, LOGGER);
    res.status(500).json({ success: false, error: msg });
  }
}

// 🟢 WORKING: Fallback cron — polls Teams call records every 15 min via CRON_SECRET
// Used as a safety net when Graph webhook subscriptions lapse or miss events
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { fetchRecentCallRecords } from '@/lib/graph/call-records';
import { processMeetingFromCallRecord } from '@/lib/graph/meeting-processor';
import { neon } from '@neondatabase/serverless';

const sql = neon(process.env.DATABASE_URL!);

const LOGGER = 'TeamsCron';

/** Look-back window — covers two cron intervals with overlap for safety */
const POLL_WINDOW_MINUTES = 60;

/**
 * POST /api/cron/poll-teams
 *
 * Polls the Graph callRecords API for the last POLL_WINDOW_MINUTES and processes
 * any call records that do not yet have a meetings row.
 *
 * Auth: CRON_SECRET bearer token (same pattern as meetings-sync-cron.ts).
 * Schedule: every 15 minutes via system cron or Vercel Cron.
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/poll-teams \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const since = new Date(Date.now() - POLL_WINDOW_MINUTES * 60 * 1000);
    const records = await fetchRecentCallRecords(since);

    log.info(
      'Teams poll: call records fetched',
      { count: records.length, since: since.toISOString() },
      LOGGER
    );

    let processed = 0;
    let skipped = 0;
    let failed = 0;

    for (const record of records) {
      // Any non-failed status means we have already attempted this record
      const existing = await sql`
        SELECT id
        FROM meetings
        WHERE teams_call_record_id = ${record.id}
      `;

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      try {
        const meetingId = await processMeetingFromCallRecord(record.id);
        if (meetingId > 0) processed++;
      } catch (error: unknown) {
        failed++;
        const errorMsg = error instanceof Error ? error.message : String(error);
        log.error(
          'Teams poll: failed to process call record',
          { callRecordId: record.id, error: errorMsg },
          LOGGER
        );
      }
    }

    log.info(
      'Teams poll cron complete',
      { total: records.length, processed, skipped, failed },
      LOGGER
    );

    res.status(200).json({
      success: true,
      fetched: records.length,
      processed,
      skipped,
      failed,
    });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Teams poll cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

/**
 * Cron Job: Process VLM Queue
 *
 * POST /api/cron/process-vlm-queue
 *
 * Purpose: Run VLM categorization and extraction for DRs with photos but no VLM data
 *
 * This cron job handles DRs where:
 * - Photos exist (photo_count > 0)
 * - But VLM extraction hasn't run (vlm_power_meter_dbm IS NULL, etc.)
 *
 * Run schedule: Every 5 minutes (via vercel.json)
 * Limit: Processes up to 20 DRs per run with 3 concurrent workers
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';
import { log } from '@/lib/logger';
import {
  categorizePhotos,
  PhotoInput,
} from '@/modules/activate/services/categorizationVlmService';
import {
  runFullExtraction,
} from '@/modules/activate/services/vlmExtractionService';
import {
  validatePowerMeter,
  validateSerialCrossReference,
  type DrValidationData,
} from '@/modules/activate/services/qaAutoFailService';

const ONEMAP_HOST = process.env.ONEMAP_HOST || 'http://100.96.203.105:8003';

interface ProcessResult {
  dropNumber: string;
  success: boolean;
  categorized: boolean;
  extracted: boolean;
  powerMeter: number | null;
  ontSerial: string | null;
  drNumber: string | null;
  error?: string;
}

interface ProcessResponse {
  success: boolean;
  processed: number;
  succeeded: number;
  failed: number;
  results: ProcessResult[];
  timestamp: string;
}

/**
 * Process a single DR through VLM pipeline
 */
async function processVlmForDr(dropNumber: string): Promise<ProcessResult> {
  const result: ProcessResult = {
    dropNumber,
    success: false,
    categorized: false,
    extracted: false,
    powerMeter: null,
    ontSerial: null,
    drNumber: null,
  };

  try {
    // Get DR data (all from unified table after migration 127)
    const drResult = await pool.query(
      `SELECT
         drop_number,
         photos_metadata::text as photos,
         vlm_categorization_status,
         vlm_categorization_results::text as categorization,
         ont_serial_scanned as onemap_ont_serial,
         ups_serial_scanned as onemap_ups_serial,
         vlm_power_meter_dbm,
         vlm_ont_serial_step6,
         vlm_ont_serial_step9,
         vlm_dr_number_step9
       FROM dr_photo_unified_reviews
       WHERE drop_number = $1`,
      [dropNumber]
    );

    if (drResult.rows.length === 0) {
      result.error = 'DR not found';
      return result;
    }

    const dr = drResult.rows[0];
    let photos: Array<{ filename: string; url: string; step?: number }> = [];

    try {
      photos = dr.photos ? JSON.parse(dr.photos) : [];
    } catch {
      result.error = 'Failed to parse photos';
      return result;
    }

    if (photos.length === 0) {
      result.error = 'No photos available';
      return result;
    }

    // Step 1: Categorize if not done
    let categorization = dr.categorization ? JSON.parse(dr.categorization) : [];

    if (dr.vlm_categorization_status !== 'categorized' && dr.vlm_categorization_status !== 'approved') {
      log.info('ProcessVlmQueue', `Categorizing photos for ${dropNumber}`);

      // Prepare photos for categorization - pass URLs, categorizePhotos will fetch them
      const photoInputs: PhotoInput[] = photos.map((photo) => ({
        filename: photo.filename,
        url: `${ONEMAP_HOST}/api/photo/${dropNumber}/${photo.filename}`,
        original_type: null,
        original_step: photo.step ?? null,
      }));

      if (photoInputs.length > 0) {
        // Run VLM categorization
        const catResult = await categorizePhotos(dropNumber, photoInputs);

        // Store the full VlmCategorizationResult objects (use correct property names!)
        categorization = catResult;

        // Save categorization results with proper timestamp
        await pool.query(
          `UPDATE dr_photo_unified_reviews
           SET vlm_categorization_status = 'categorized',
               vlm_categorization_results = $1,
               vlm_categorized_at = NOW(),
               updated_at = NOW()
           WHERE drop_number = $2`,
          [JSON.stringify(categorization), dropNumber]
        );

        result.categorized = true;
        log.info('ProcessVlmQueue', `Categorized ${photoInputs.length} photos for ${dropNumber}`);
      }
    } else {
      result.categorized = true;
    }

    // Step 2: Extract data from Step 6, 7, 9 photos
    // Find photos for each step
    const photosWithSteps = photos.map((p) => {
      const cat = categorization.find(
        (c: { photo_filename: string; vlm_predicted_step?: number; human_override_step?: number }) =>
          c.photo_filename === p.filename
      );
      return {
        ...p,
        step: cat?.human_override_step ?? cat?.vlm_predicted_step ?? p.step ?? null,
      };
    });

    // Get ALL photos for each step - VLM will try each to find best result
    const step6Photos = photosWithSteps.filter((p) => p.step === 6);
    const step7Photos = photosWithSteps.filter((p) => p.step === 7);
    const step9Photos = photosWithSteps.filter((p) => p.step === 9);

    // Only run extraction if we have at least one of these photos
    if (step6Photos.length > 0 || step7Photos.length > 0 || step9Photos.length > 0) {
      log.info('ProcessVlmQueue', `Extracting data for ${dropNumber}`, {
        step6Count: step6Photos.length,
        step7Count: step7Photos.length,
        step9Count: step9Photos.length,
      });

      const extraction = await runFullExtraction(dropNumber, {
        step6Urls: step6Photos.length > 0 ? step6Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
        step7Urls: step7Photos.length > 0 ? step7Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
        step9Urls: step9Photos.length > 0 ? step9Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
      });

      // Build validation data
      const validationData: DrValidationData = {
        drNumber: dropNumber,
        photoCount: photos.length,
        photos: photosWithSteps.map((p) => ({ filename: p.filename, step: p.step ?? null })),
        ontSerial: dr.onemap_ont_serial,
        upsSerial: dr.onemap_ups_serial,
        powerMeterDbm: extraction.powerMeter?.value ?? null,
        vlmOntSerialStep6: extraction.ontSerialStep6?.serial ?? null,
        vlmOntSerialStep9: extraction.step9?.ontSerial.serial ?? null,
        vlmDrNumberStep9: extraction.step9?.drNumber.drNumber ?? null,
      };

      const powerMeterResult = validatePowerMeter(validationData.powerMeterDbm);
      const serialResult = validateSerialCrossReference(validationData);

      const serialValidationDetails = JSON.stringify({
        onemapSerial: serialResult.onemapSerial,
        step6Serial: serialResult.step6Serial,
        step9Serial: serialResult.step9Serial,
        step9DrNumber: serialResult.step9DrNumber,
        ontMatch: serialResult.ontMatch,
        drMatch: serialResult.drMatch,
      });

      // Save extraction results directly to unified table (migration 127)
      await pool.query(
        `UPDATE dr_photo_unified_reviews SET
           vlm_power_meter_dbm = $1,
           vlm_power_meter_status = $2,
           vlm_ont_serial_step6 = $3,
           vlm_ont_serial_step9 = $4,
           vlm_dr_number_step9 = $5,
           serial_validation_status = $6,
           serial_validation_details = $7,
           serial_extraction_method_step6 = $8,
           serial_extraction_method_step9 = $9,
           data_validation_completed = true,
           data_validation_completed_at = NOW(),
           qa_phase = 'final_decision',
           onemap_ont_serial = COALESCE($10, onemap_ont_serial),
           onemap_ups_serial = COALESCE($11, onemap_ups_serial),
           overall_status = 'PASS',
           updated_at = NOW()
         WHERE drop_number = $12`,
        [
          extraction.powerMeter?.value ?? null,
          powerMeterResult.status,
          extraction.ontSerialStep6?.serial ?? null,
          extraction.step9?.ontSerial.serial ?? null,
          extraction.step9?.drNumber.drNumber ?? null,
          serialResult.status,
          serialValidationDetails,
          extraction.ontSerialStep6?.extractionMethod ?? 'vlm',
          extraction.step9?.ontSerial.extractionMethod ?? 'vlm',
          dr.onemap_ont_serial ?? null,
          dr.onemap_ups_serial ?? null,
          dropNumber,
        ]
      );

      result.extracted = true;
      result.powerMeter = extraction.powerMeter?.value ?? null;
      result.ontSerial = extraction.ontSerialStep6?.serial ?? extraction.step9?.ontSerial.serial ?? null;
      result.drNumber = extraction.step9?.drNumber.drNumber ?? null;

      log.info('ProcessVlmQueue', `Extraction complete for ${dropNumber}`, {
        powerMeter: result.powerMeter,
        ontSerial: result.ontSerial,
        drNumber: result.drNumber,
      });
    } else {
      // No step 6/7/9 photos found — mark as done so cron doesn't re-process
      log.info('ProcessVlmQueue', `No step 6/7/9 photos for ${dropNumber}, marking extraction complete`);
      await pool.query(
        `UPDATE dr_photo_unified_reviews SET
           data_validation_completed = true,
           data_validation_completed_at = NOW(),
           vlm_power_meter_status = 'no_photo',
           serial_validation_status = 'no_photo',
           qa_phase = 'final_decision',
           overall_status = 'NEEDS_REVIEW',
           updated_at = NOW()
         WHERE drop_number = $1`,
        [dropNumber]
      );
      result.extracted = false;
    }

    result.success = true;
    return result;
  } catch (error) {
    result.error = error instanceof Error ? error.message : 'Unknown error';
    log.error('ProcessVlmQueue', `Error processing ${dropNumber}`, { error: result.error });
    return result;
  }
}

/**
 * Main handler
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ProcessResponse | { error: string }>
): Promise<void> {
  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', ['GET', 'POST']);
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // Verify cron secret in production
  const authHeader = req.headers.authorization;
  const cronSecret = process.env.CRON_SECRET;

  if (process.env.NODE_ENV === 'production' && cronSecret) {
    if (authHeader !== `Bearer ${cronSecret}`) {
      log.error('ProcessVlmQueue', 'Unauthorized request');
      return res.status(401).json({ error: 'Unauthorized' });
    }
  }

  const limit = Number(req.query.limit) || Number(req.body?.limit) || 20;
  const concurrency = Number(req.query.concurrency) || Number(req.body?.concurrency) || 3;

  log.info('ProcessVlmQueue', `Starting VLM queue processing (limit: ${limit}, concurrency: ${concurrency})`);

  try {
    // Find DRs that need VLM processing:
    // 1. Uncategorized DRs (need full pipeline: categorize + extract)
    // 2. Categorized but not extracted (need extraction only - faster)
    const pendingResult = await pool.query(
      `SELECT drop_number
       FROM dr_photo_unified_reviews
       WHERE photo_count > 0
         AND (
           -- Uncategorized: need full pipeline
           (vlm_categorization_status IS NULL OR vlm_categorization_status = 'pending')
           OR
           -- Categorized but missing extraction data (and not already marked as no-photo)
           (vlm_categorization_status IN ('categorized', 'approved')
            AND vlm_power_meter_dbm IS NULL
            AND vlm_ont_serial_step6 IS NULL
            AND vlm_ont_serial_step9 IS NULL
            AND (data_validation_completed IS NULL OR data_validation_completed = false))
         )
       ORDER BY
         -- Prioritize already-categorized (extraction-only = faster)
         CASE WHEN vlm_categorization_status IN ('categorized', 'approved') THEN 0 ELSE 1 END,
         created_at DESC
       LIMIT $1`,
      [limit]
    );

    const pendingDRs = pendingResult.rows;

    if (pendingDRs.length === 0) {
      log.info('ProcessVlmQueue', 'No DRs need VLM processing');
      return res.status(200).json({
        success: true,
        processed: 0,
        succeeded: 0,
        failed: 0,
        results: [],
        timestamp: new Date().toISOString(),
      });
    }

    log.info('ProcessVlmQueue', `Found ${pendingDRs.length} DRs to process (${concurrency} concurrent)`);

    const results: ProcessResult[] = [];
    let succeeded = 0;
    let failed = 0;

    // Process DRs in parallel batches of `concurrency`
    for (let i = 0; i < pendingDRs.length; i += concurrency) {
      const batch = pendingDRs.slice(i, i + concurrency);
      const batchResults = await Promise.allSettled(
        batch.map((row) => processVlmForDr(row.drop_number))
      );

      for (const settled of batchResults) {
        if (settled.status === 'fulfilled') {
          results.push(settled.value);
          if (settled.value.success) succeeded++;
          else failed++;
        } else {
          failed++;
          results.push({
            dropNumber: 'unknown',
            success: false,
            categorized: false,
            extracted: false,
            powerMeter: null,
            ontSerial: null,
            drNumber: null,
            error: settled.reason?.message || 'Promise rejected',
          });
        }
      }

      // Brief pause between batches to let VLM breathe
      if (i + concurrency < pendingDRs.length) {
        await new Promise((resolve) => setTimeout(resolve, 500));
      }
    }

    log.info('ProcessVlmQueue', `Completed: ${succeeded}/${pendingDRs.length} succeeded`, {
      failed,
    });

    return res.status(200).json({
      success: true,
      processed: pendingDRs.length,
      succeeded,
      failed,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    const errorStack = error instanceof Error ? error.stack : undefined;
    log.error('ProcessVlmQueue', `Fatal error: ${errorMessage}`, { stack: errorStack });
    return res.status(500).json({
      error: errorMessage || 'Failed to process VLM queue',
    });
  }
}

/**
 * Cron Job: Re-check OneMap Status for Not-Found DRs
 *
 * POST /api/cron/recheck-onemap-status
 *
 * Purpose: Periodically re-check DRs that were submitted via WhatsApp
 * but weren't found in 1Map at submission time (onemap_status = 'not_found').
 * When they appear in 1Map, marks them as 'resolved'.
 *
 * Run schedule: Every 30 minutes (via external cron)
 * Limit: Processes up to 50 DRs per run (configurable via ?limit=N)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import pool from '@/lib/db';

import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const BOSS_API_HOST = process.env.BOSS_API_HOST || 'http://100.96.203.105:8003';

interface RecheckResult {
  dropNumber: string;
  previousStatus: string;
  newStatus: string;
  foundInOneMap: boolean;
}

async function recheckDR(dropNumber: string): Promise<RecheckResult> {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    const response = await fetch(`${BOSS_API_HOST}/api/record/${dropNumber}`, {
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (response.ok) {
      // DR now exists in 1Map - mark as resolved
      await pool.query(
        `UPDATE dr_photo_unified_reviews
         SET onemap_status = 'resolved', onemap_checked_at = NOW(), updated_at = NOW()
         WHERE drop_number = $1`,
        [dropNumber]
      );
      return { dropNumber, previousStatus: 'not_found', newStatus: 'resolved', foundInOneMap: true };
    }

    // Still not in 1Map - update checked_at timestamp
    await pool.query(
      `UPDATE dr_photo_unified_reviews
       SET onemap_checked_at = NOW(), updated_at = NOW()
       WHERE drop_number = $1`,
      [dropNumber]
    );
    return { dropNumber, previousStatus: 'not_found', newStatus: 'not_found', foundInOneMap: false };
  } catch (error) {
    log.warn('RecheckOneMap', `Failed to re-check ${dropNumber}`, { error });
    return { dropNumber, previousStatus: 'not_found', newStatus: 'not_found', foundInOneMap: false };
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse): Promise<void> {
  if (req.method !== 'POST') {
    return apiResponse.error(res, ErrorCode.METHOD_NOT_ALLOWED, 'Method not allowed');
  }

  // Verify cron secret
  const authHeader = req.headers.authorization;
  const cronSecret = process.env.CRON_SECRET;

  if (process.env.NODE_ENV === 'production' && cronSecret) {
    if (authHeader !== `Bearer ${cronSecret}`) {
      log.error('RecheckOneMap', 'Unauthorized request');
      return res.status(401).json({ error: 'Unauthorized' });
    }
  }

  const limit = Number(req.query.limit) || 50;

  log.info('RecheckOneMap', `Starting re-check of not_found DRs (limit: ${limit})`);

  try {
    // Find DRs that are still not_found, oldest checked first
    const notFoundDRs = await pool.query(
      `SELECT drop_number, onemap_checked_at
       FROM dr_photo_unified_reviews
       WHERE onemap_status = 'not_found'
       ORDER BY COALESCE(onemap_checked_at, created_at) ASC
       LIMIT $1`,
      [limit]
    );

    if (notFoundDRs.rows.length === 0) {
      log.info('RecheckOneMap', 'No not_found DRs to re-check');
      return apiResponse.success(res, {
        processed: 0,
        resolved: 0,
        stillNotFound: 0,
        results: [],
        timestamp: new Date().toISOString(),
      });
    }

    log.info('RecheckOneMap', `Found ${notFoundDRs.rows.length} DRs to re-check`);

    const results: RecheckResult[] = [];
    let resolved = 0;
    let stillNotFound = 0;

    for (const row of notFoundDRs.rows) {
      const result = await recheckDR(row.drop_number);
      results.push(result);

      if (result.foundInOneMap) {
        resolved++;
        log.info('RecheckOneMap', `DR ${row.drop_number} now FOUND in 1Map - resolved!`);
      } else {
        stillNotFound++;
      }
    }

    log.info('RecheckOneMap', `Re-check complete`, {
      processed: results.length,
      resolved,
      stillNotFound,
    });

    return apiResponse.success(res, {
      processed: results.length,
      resolved,
      stillNotFound,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    log.error('RecheckOneMap', 'Re-check job failed', { error });
    return apiResponse.internalError(res, error);
  }
}

export default handler;

/**
 * Recurring Invoices Cron
 * Generates customer invoices for all active recurring templates that are due
 *
 * Schedule: 0 6 * * * (6 AM daily)
 * Auth: CRON_SECRET header or withAuth
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoiceFromRecurring } from '@/modules/accounting/services/recurringInvoiceService';

const CRON_SECRET = process.env.CRON_SECRET || '';
const SYSTEM_USER_ID = '00000000-0000-0000-0000-000000000000';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  // Auth: cron secret or session cookie
  const cronSecret = req.headers['x-cron-secret'] || req.query.secret;
  if (cronSecret !== CRON_SECRET && !req.headers.cookie) {
    return apiResponse.unauthorized(res, 'Invalid cron secret');
  }

  try {
    // Find all active recurring invoices due today or earlier
    const dueItems = await sql`
      SELECT id, template_name, client_id
      FROM recurring_invoices
      WHERE status = 'active'
        AND next_run_date <= CURRENT_DATE
      ORDER BY next_run_date ASC
    `;

    if (dueItems.length === 0) {
      return apiResponse.success(res, { processed: 0, message: 'No recurring invoices due' });
    }

    const results: { id: string; templateName: string; invoiceId?: string; error?: string }[] = [];

    for (const item of dueItems) {
      try {
        const invoiceId = await generateInvoiceFromRecurring(String(item.id), SYSTEM_USER_ID);
        results.push({ id: String(item.id), templateName: String(item.template_name), invoiceId });
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error';
        log.error('Failed to generate recurring invoice', { id: item.id, error: message }, 'cron');
        results.push({ id: String(item.id), templateName: String(item.template_name), error: message });
      }
    }

    const succeeded = results.filter(r => r.invoiceId).length;
    const failed = results.filter(r => r.error).length;

    log.info('Recurring invoices cron completed', { total: dueItems.length, succeeded, failed }, 'cron');

    return apiResponse.success(res, {
      processed: dueItems.length,
      succeeded,
      failed,
      results,
    });
  } catch (err) {
    log.error('Recurring invoices cron failed', { error: err }, 'cron');
    return apiResponse.badRequest(res, 'Cron job failed');
  }
}

export default withErrorHandler(handler);

