// 🟢 WORKING: Daily cron — renews expiring Graph webhook subscriptions
// Graph callRecord subscriptions have a 3-day maximum lifetime
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import {
  getExpiringSubscriptions,
  getActiveSubscriptionCount,
  renewSubscription,
  createWebhookSubscription,
} from '@/lib/graph/subscriptions';

const LOGGER = 'GraphSubRenewal';

/** Public HTTPS URL Graph will POST change notifications to */
const WEBHOOK_URL = 'https://app.fibreflow.app/api/meetings/webhook';

/**
 * POST /api/cron/renew-graph-subscriptions
 *
 * Finds all active Graph subscriptions expiring within the next 12 hours and:
 *   1. Attempts to renew each via PATCH /subscriptions/{id}
 *   2. Falls back to creating a new subscription if renewal fails
 *
 * Auth: CRON_SECRET bearer token.
 * Recommended schedule: once daily (e.g. 06:00 SAST).
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/renew-graph-subscriptions \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt on subscription renewal',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    let renewed = 0;
    let recreated = 0;
    let failed = 0;
    let bootstrapped = false;

    // Bootstrap: create a subscription if none exist (first run or all expired)
    const activeCount = await getActiveSubscriptionCount();
    if (activeCount === 0) {
      log.info('No active subscriptions found — bootstrapping new subscription', {}, LOGGER);
      try {
        await createWebhookSubscription(WEBHOOK_URL);
        bootstrapped = true;
        recreated++;
        log.info('Webhook subscription bootstrapped', { webhookUrl: WEBHOOK_URL }, LOGGER);
      } catch (bootstrapError: unknown) {
        failed++;
        const msg = bootstrapError instanceof Error ? bootstrapError.message : String(bootstrapError);
        log.error('Subscription bootstrap failed', { error: msg }, LOGGER);
      }
    }

    const expiring = await getExpiringSubscriptions();

    log.info(
      'Subscription renewal check',
      { expiringSoon: expiring.length, activeCount, bootstrapped },
      LOGGER
    );

    for (const sub of expiring) {
      try {
        await renewSubscription(sub.subscriptionId);
        renewed++;
        log.info(
          'Subscription renewed',
          { subscriptionId: sub.subscriptionId, expiresAt: sub.expiresAt },
          LOGGER
        );
      } catch (renewError: unknown) {
        const renewMsg = renewError instanceof Error ? renewError.message : String(renewError);

        log.warn(
          'Subscription renewal failed — attempting recreation',
          { subscriptionId: sub.subscriptionId, error: renewMsg },
          LOGGER
        );

        try {
          await createWebhookSubscription(WEBHOOK_URL);
          recreated++;
        } catch (createError: unknown) {
          failed++;
          const createMsg = createError instanceof Error ? createError.message : String(createError);
          log.error(
            'Subscription recreation failed',
            { subscriptionId: sub.subscriptionId, error: createMsg },
            LOGGER
          );
        }
      }
    }

    log.info(
      'Subscription renewal cron complete',
      { expiring: expiring.length, renewed, recreated, failed },
      LOGGER
    );

    res.status(200).json({
      success: true,
      activeCount,
      bootstrapped,
      expiring: expiring.length,
      renewed,
      recreated,
      failed,
    });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('Subscription renewal cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

/**
 * Sage Scheduled Sync Cron Job
 *
 * Runs every 15 minutes to:
 * 1. Pull new invoices from Sage
 * 2. Pull new payments from Sage
 * 3. Update budget transactions
 *
 * Triggered by external cron service (Vercel Cron, GitHub Actions, etc.)
 * Protected by CRON_SECRET header
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { createLogger } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { createSageClientFromConfig } from '@/services/sage';
import { pullInvoicesFromSage } from '@/services/sage/entities/invoiceSync';
import { pullPaymentsFromSage } from '@/services/sage/entities/paymentSync';

const logger = createLogger({ module: 'api:cron:sage-sync' });

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Only accept POST requests
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, ['POST']);
  }

  // Verify cron secret
  const cronSecret = req.headers['x-cron-secret'] || req.headers['authorization']?.replace('Bearer ', '');

  if (process.env.CRON_SECRET && cronSecret !== process.env.CRON_SECRET) {
    logger.warn('Unauthorized cron request attempt');
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const sql = neon(process.env.DATABASE_URL!);
  const startTime = Date.now();

  const results = {
    success: true,
    invoices: null as unknown,
    payments: null as unknown,
    duration: 0,
    errors: [] as string[],
  };

  try {
    logger.info('Starting scheduled Sage sync');

    // Check if Sage is configured and connected
    const configResult = await sql`
      SELECT
        id,
        client_id,
        client_secret,
        company_id,
        base_url,
        access_token,
        refresh_token,
        token_expires_at,
        sync_enabled,
        last_sync_at
      FROM sage_api_config
      WHERE is_active = true AND is_connected = true
      LIMIT 1
    `;

    if (configResult.length === 0) {
      logger.info('Sage sync skipped - not configured or not connected');
      return apiResponse.success(res, {
        message: 'Sage sync skipped - not configured or not connected',
        skipped: true,
      });
    }

    const config = configResult[0];

    // Check if sync is enabled
    if (config.sync_enabled === false) {
      logger.info('Sage sync skipped - sync disabled in config');
      return apiResponse.success(res, {
        message: 'Sage sync skipped - sync disabled',
        skipped: true,
      });
    }

    // Create Sage client
    const client = createSageClientFromConfig({
      clientId: config.client_id,
      clientSecret: config.client_secret,
      companyId: config.company_id,
      baseUrl: config.base_url,
      accessToken: config.access_token,
      refreshToken: config.refresh_token,
      expiresAt: config.token_expires_at ? new Date(config.token_expires_at) : undefined,
    });

    // Calculate since date (last sync or 24 hours ago)
    const sinceDate = config.last_sync_at
      ? new Date(config.last_sync_at)
      : new Date(Date.now() - 24 * 60 * 60 * 1000);

    // Step 1: Sync invoices
    try {
      logger.info('Syncing invoices from Sage');
      results.invoices = await pullInvoicesFromSage(client, sql, { sinceDate });
    } catch (error) {
      results.errors.push(`Invoice sync failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
      logger.error('Invoice sync failed', { error });
    }

    // Step 2: Sync payments
    try {
      logger.info('Syncing payments from Sage');
      results.payments = await pullPaymentsFromSage(client, sql, { sinceDate });
    } catch (error) {
      results.errors.push(`Payment sync failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
      logger.error('Payment sync failed', { error });
    }

    // Update tokens if refreshed
    const tokens = client.getTokens();
    if (tokens && tokens.accessToken !== config.access_token) {
      await sql`
        UPDATE sage_api_config
        SET
          access_token = ${tokens.accessToken},
          refresh_token = ${tokens.refreshToken},
          token_expires_at = ${tokens.expiresAt.toISOString()},
          last_token_refresh_at = NOW(),
          updated_at = NOW()
        WHERE id = ${config.id}
      `;
      logger.info('Sage tokens refreshed');
    }

    // Update last sync timestamp
    await sql`
      UPDATE sage_api_config
      SET
        last_sync_at = NOW(),
        updated_at = NOW()
      WHERE id = ${config.id}
    `;

    results.duration = Date.now() - startTime;
    results.success = results.errors.length === 0;

    // Log overall sync result
    await sql`
      INSERT INTO sage_sync_history (
        operation_type,
        direction,
        status,
        details
      ) VALUES (
        'scheduled_sync',
        'inbound',
        ${results.success ? 'success' : 'partial'},
        ${JSON.stringify(results)}
      )
    `;

    logger.info('Scheduled Sage sync completed', {
      duration: results.duration,
      success: results.success,
      errors: results.errors,
    });

    return apiResponse.success(res, results);
  } catch (error) {
    results.success = false;
    results.errors.push(error instanceof Error ? error.message : 'Unknown error');
    results.duration = Date.now() - startTime;

    logger.error('Scheduled Sage sync failed', { error });

    // Log failure
    await sql`
      INSERT INTO sage_sync_history (
        operation_type,
        direction,
        status,
        error_message,
        details
      ) VALUES (
        'scheduled_sync',
        'inbound',
        'failed',
        ${error instanceof Error ? error.message : 'Unknown error'},
        ${JSON.stringify(results)}
      )
    `;

    return apiResponse.success(res, results);
  }
}

import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Vercel Cron Job: Sync Action Items from Fireflies Meetings
 *
 * Runs every 6 hours to extract new action items from meetings.
 *
 * Vercel Cron documentation:
 * https://vercel.com/docs/cron-jobs
 *
 * Runs at: 00:00, 06:00, 12:00, 18:00 UTC
 * See vercel.json for cron schedule configuration
 */
export default async function handler(
