const sql = neon(process.env.DATABASE_URL!);
const LOGGER = 'OneDriveCron';

/**
 * POST /api/cron/scrape-onedrive
 *
 * Scans all internal users' OneDrive /Recordings/ folders for Teams meeting
 * recordings that haven't been captured by the regular pipeline (e.g. "Meet Now"
 * calls where someone manually clicked Record).
 *
 * Downloads recordings to local disk, matches to existing meetings or creates
 * new entries, and runs LLM enrichment.
 *
 * Auth: CRON_SECRET bearer token.
 * Schedule: every 30 minutes via system cron.
 *
 * Query params:
 *   ?lookbackDays=30  — how far back to check (default: 30)
 *   ?limit=50         — max recordings to process per run (default: 50)
 *
 * curl example:
 *   curl -X POST https://app.fibreflow.app/api/cron/scrape-onedrive \
 *        -H "Authorization: Bearer $CRON_SECRET"
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const cronSecret = process.env.CRON_SECRET;
  if (!cronSecret) {
    log.error('CRON_SECRET is not configured', {}, LOGGER);
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || authHeader !== `Bearer ${cronSecret}`) {
    log.warn(
      'Unauthorized cron attempt',
      { ip: req.headers['x-forwarded-for'] ?? req.socket.remoteAddress },
      LOGGER
    );
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    const lookbackDays = parseInt(req.query.lookbackDays as string) || 30;
    const limit = parseInt(req.query.limit as string) || 50;

    log.info('OneDrive scrape cron triggered', { lookbackDays, limit }, LOGGER);

    const result = await scrapeOneDriveRecordings(sql, { lookbackDays, limit });

    log.info('OneDrive scrape cron complete', result, LOGGER);

    res.status(200).json({ success: true, ...result });
  } catch (error: unknown) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    log.error('OneDrive scrape cron failed', { error: errorMsg }, LOGGER);
    res.status(500).json({ success: false, error: errorMsg });
  }
}

/**
 * System Feature Settings API
 *
 * GET: Returns all system feature settings
 * PUT: Updates a single feature setting
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

interface FeatureSetting {
  id: string;
  feature_key: string;
  enabled: boolean;
  config: Record<string, unknown>;
  updated_at: string;
  updated_by: string | null;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    return handleGet(res);
  }

  if (req.method === 'PUT') {
    return handlePut(req, res);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PUT']);
}

async function handleGet(res: NextApiResponse) {
  try {
    const features = await sql`
      SELECT
        id,
        feature_key,
        enabled,
        config,
        updated_at,
        updated_by
      FROM system_feature_settings
      ORDER BY feature_key
    `;

    return apiResponse.success(res, features as FeatureSetting[]);
  } catch (error) {
    log.error('SystemFeatures', 'Failed to fetch system feature settings', { error });
    return apiResponse.databaseError(res, error, 'Failed to fetch feature settings');
  }
}

async function handlePut(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { feature_key, enabled, config } = req.body;

    if (!feature_key) {
      return apiResponse.badRequest(res, 'feature_key is required');
    }

    if (typeof enabled !== 'boolean') {
      return apiResponse.badRequest(res, 'enabled must be a boolean');
    }

    // Get user ID from request if available
    const userId = req.user?.id || null;

    // Upsert the feature setting
    const result = await sql`
      INSERT INTO system_feature_settings (feature_key, enabled, config, updated_at, updated_by)
      VALUES (
        ${feature_key},
        ${enabled},
        ${config ? JSON.stringify(config) : '{}'}::jsonb,
        NOW(),
        ${userId}
      )
      ON CONFLICT (feature_key) DO UPDATE SET
        enabled = EXCLUDED.enabled,
        config = COALESCE(EXCLUDED.config, system_feature_settings.config),
        updated_at = NOW(),
        updated_by = EXCLUDED.updated_by
      RETURNING id, feature_key, enabled, config, updated_at
    `;

    log.info('SystemFeatures', 'Feature setting updated', {
      feature_key,
      enabled,
      updated_by: userId,
    });

    return apiResponse.success(res, result[0]);
  } catch (error) {
    log.error('SystemFeatures', 'Failed to update system feature setting', { error });
    return apiResponse.databaseError(res, error, 'Failed to update feature setting');
  }
}

