/**
 * Neon Database Connection Setup
 * Drizzle ORM with Neon Serverless PostgreSQL
 */

import { drizzle } from 'drizzle-orm/neon-http';
import { neonTables } from './schema';
import { log } from '@/lib/logger';
import { getNeonConnection, executeQuery } from './connectionPool';

// Lazy initialization to prevent connection attempts in browser
let sql: ReturnType<typeof getNeonConnection> | null = null;
let _neonDb: ReturnType<typeof drizzle> | null = null;

// Get SQL connection lazily
function getSql() {
  if (!sql) {
    sql = getNeonConnection();
  }
  return sql;
}

// Create Drizzle instance lazily
export const neonDb = new Proxy({} as ReturnType<typeof drizzle>, {
  get(target, prop) {
    if (!_neonDb) {
      _neonDb = drizzle(getSql(), { schema: neonTables });
    }
    return _neonDb[prop as keyof typeof _neonDb];
  }
});

// Alias for backward compatibility
export const db = neonDb;

// Connection test utility
export async function testNeonConnection(): Promise<boolean> {
  try {
    await getSql()`SELECT NOW() as current_time`;

    return true;
  } catch (error) {
    log.error('Neon connection failed:', { data: error }, 'connection');
    return false;
  }
}

// Database utilities
export const neonUtils = {
  /**
   * Test database connection
   */
  async ping(): Promise<{ success: boolean; timestamp?: string; error?: string }> {
    try {
      const result = await executeQuery(sql => sql`SELECT NOW() as timestamp`);
      const firstRow = Array.isArray(result) && result.length > 0 ? result[0] : null;
      return {
        success: true,
        timestamp: firstRow && typeof firstRow === 'object' && 'timestamp' in firstRow 
          ? (firstRow as any).timestamp 
          : new Date().toISOString(),
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  },

  /**
   * Get database version and info
   */
  async getInfo(): Promise<any> {
    try {
      const versionResult = await getSql()`SELECT VERSION() as version`;
      const sizeResult = await getSql()`
        SELECT 
          pg_size_pretty(pg_database_size(current_database())) as database_size,
          current_database() as database_name,
          current_user as user_name
      `;

      const versionRow = Array.isArray(versionResult) && versionResult.length > 0 ? versionResult[0] : null;
      const sizeRow = Array.isArray(sizeResult) && sizeResult.length > 0 ? sizeResult[0] : null;

      return {
        version: versionRow && typeof versionRow === 'object' && 'version' in versionRow
          ? (versionRow as any).version || 'Unknown'
          : 'Unknown',
        ...(sizeRow && typeof sizeRow === 'object' ? sizeRow : {}),
      };
    } catch (error) {
      log.error('Failed to get database info:', { data: error }, 'connection');
      return null;
    }
  },

  /**
   * Get table information
   */
  async getTableStats(): Promise<any> {
    try {
      const result = await getSql()`
        SELECT 
          schemaname,
          tablename,
          n_tup_ins as inserts,
          n_tup_upd as updates,
          n_tup_del as deletes,
          n_live_tup as live_tuples,
          n_dead_tup as dead_tuples
        FROM pg_stat_user_tables
        ORDER BY tablename;
      `;

      return result;
    } catch (error) {
      log.error('Failed to get table stats:', { data: error }, 'connection');
      return [];
    }
  },

  /**
   * Execute raw SQL (use with caution)
   */
  async rawQuery(query: string): Promise<any> {
    try {
      // Use template literal format for Neon
      return await getSql()([query] as any as TemplateStringsArray);
    } catch (error) {
      log.error('Raw query failed:', { data: error }, 'connection');
      throw error;
    }
  },
};

/**
 * Neon Database Connection Pool Configuration
 * Optimized connection management for better performance and reliability
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';


// Get the database URL with fallback
const getDatabaseUrl = (): string => {
  // Check if we're in the browser
  const isBrowser = typeof window !== 'undefined';

  if (isBrowser) {
    // In browser, return a dummy URL - we should use API routes instead
    log.warn('Database connection attempted from browser - use API routes instead', {}, 'connectionPool');
    return 'postgresql://dummy@localhost/dummy';
  }

  let databaseUrl: string | undefined;

  // Server-only: never use NEXT_PUBLIC_ prefix (leaks credentials to client bundle)
  if (typeof process !== 'undefined' && process.env) {
    databaseUrl = process.env.DATABASE_URL;
  }

  // No fallback - environment variable is required for security
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is required and not defined. Check your .env file.');
  }

  return databaseUrl;
};

// Create simple connection for Neon serverless
let simpleConnection: ReturnType<typeof neon> | null = null;

/**
 * Get or create the simple Neon connection (for serverless)
 */
export function getNeonConnection(): ReturnType<typeof neon> {
  if (!simpleConnection) {
    const databaseUrl = getDatabaseUrl();

    try {
      simpleConnection = neon(databaseUrl);

      log.info('Neon serverless connection created', {}, 'connectionPool');

    } catch (error) {
      log.error('Failed to create Neon connection:', { data: error }, 'connectionPool');
      throw error;
    }
  }

  return simpleConnection;
}

/**
 * Test database connection
 */
export async function testConnection(): Promise<{ success: boolean; error?: string | undefined; timing?: number | undefined }> {
  const startTime = Date.now();

  try {
    const sql = getNeonConnection();
    await sql`SELECT 1 as test`;

    const timing = Date.now() - startTime;

    return {
      success: true,
      error: undefined,
      timing
    };
  } catch (error) {
    const timing = Date.now() - startTime;

    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
      timing: timing
    };
  }
}

/**
 * Reset the cached connection (call on socket errors)
 */
export function resetConnection(): void {
  if (simpleConnection) {
    log.info('Resetting stale Neon connection', {}, 'connectionPool');
    simpleConnection = null;
  }
}

/**
 * Check if error is a recoverable socket/connection error
 */
function isRecoverableError(error: Error): boolean {
  const recoverablePatterns = [
    'socket hang up',
    'ECONNRESET',
    'ETIMEDOUT',
    'ENOTFOUND',
    'EAI_AGAIN',
    'fetch failed',
    'network error',
    'connection terminated',
    'Connection terminated unexpectedly',
  ];

  return recoverablePatterns.some(pattern =>
    error.message.toLowerCase().includes(pattern.toLowerCase())
  );
}

/**
 * Execute a query with automatic retry logic
 */
export async function executeQuery<T = any>(
  queryFn: (sql: ReturnType<typeof neon>) => Promise<T>,
  maxRetries: number = 2
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const sql = getNeonConnection();
      return await queryFn(sql);
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      log.warn(`Query attempt ${attempt + 1} failed:`, {
        data: { error: lastError.message, attempt }
      }, 'connectionPool');

      // Don't retry on authentication errors
      if (lastError.message.includes('password authentication failed')) {
        break;
      }

      // Reset connection on recoverable socket errors
      if (isRecoverableError(lastError)) {
        resetConnection();
      }

      // Wait before retrying (exponential backoff)
      if (attempt < maxRetries) {
        const delay = Math.min(1000 * Math.pow(2, attempt), 5000);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Query failed after retries');
}

/**
 * Health check for the connection
 */
export async function healthCheck(): Promise<{
  isHealthy: boolean;
  lastCheck: Date;
  error?: string | undefined;
  timing?: number | undefined;
}> {
  const result = await testConnection();

  return {
    isHealthy: result.success,
    lastCheck: new Date(),
    error: result.error || undefined,
    timing: result.timing || undefined
  };
}

/**
 * Gracefully close connections
 */
export async function closeConnections(): Promise<void> {
  try {
    // Simple connection doesn't need explicit closing in Neon serverless
    simpleConnection = null;
    log.info('Connection closed', {}, 'connectionPool');

  } catch (error) {
    log.error('Error closing connections:', { data: error }, 'connectionPool');
  }
}

// Export a function to get the connection (lazy loading)
export const getSql = () => getNeonConnection();

/**
 * Lazy-loaded Neon SQL client for Next.js
 * Prevents immediate DATABASE_URL access on client-side
 * Handles stale WebSocket connections with automatic reconnection
 */

import { neon } from '@/lib/db-neon';

// Lazy initialization to prevent connection attempts in browser
let sqlInstance: ReturnType<typeof neon> | null = null;

/**
 * Reset the cached SQL instance (call on socket errors)
 */
export function resetSqlConnection(): void {
  sqlInstance = null;
}

/**
 * Get the Neon SQL client with lazy initialization
 * This prevents immediate DATABASE_URL access on module import
 */
export function getSql(): ReturnType<typeof neon> {
  if (sqlInstance) {
    return sqlInstance;
  }

  // Check if we're in the browser
  const isBrowser = typeof window !== 'undefined';

  if (isBrowser) {
    // In browser, return a dummy client that throws informative errors
    // This prevents DATABASE_URL access on client side
    const dummySql = ((strings: TemplateStringsArray, ...values: any[]) => {
      throw new Error('Database operations cannot be performed in the browser. Use API routes instead.');
    }) as any as ReturnType<typeof neon>;

    dummySql.transaction = async (callback: any) => {
      throw new Error('Database transactions cannot be performed in the browser. Use API routes instead.');
    };

    sqlInstance = dummySql;
    return sqlInstance;
  }

  // Server-side: get DATABASE_URL safely
  let databaseUrl: string | undefined;

  // Server-only: never use NEXT_PUBLIC_ prefix (leaks credentials to client bundle)
  if (typeof process !== 'undefined' && process.env) {
    databaseUrl = process.env.DATABASE_URL;
  }

  // No fallback - environment variable is required for security
  if (!databaseUrl) {
    throw new Error('DATABASE_URL environment variable is required and not defined. Check your .env file.');
  }

  sqlInstance = neon(databaseUrl);
  return sqlInstance;
}

/**
 * Execute query with automatic retry on socket errors
 */
export async function executeWithRetry<T>(
  queryFn: () => Promise<T>,
  maxRetries: number = 2
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await queryFn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Check if it's a recoverable socket error
      const isSocketError = [
        'socket hang up',
        'ECONNRESET',
        'fetch failed',
        'connection terminated'
      ].some(pattern => lastError!.message.toLowerCase().includes(pattern.toLowerCase()));

      if (isSocketError) {
        resetSqlConnection();

        if (attempt < maxRetries) {
          const delay = Math.min(1000 * Math.pow(2, attempt), 5000);
          await new Promise(resolve => setTimeout(resolve, delay));
          continue;
        }
      }

      // Don't retry on auth errors
      if (lastError.message.includes('password authentication failed')) {
        break;
      }
    }
  }

  throw lastError || new Error('Query failed after retries');
}

/**
 * Convenience export for lazy SQL access
 * Use this instead of importing sql directly
 */
export const sql = getSql();

