  | 'other';

export type ExpiryUrgency = 'expired' | 'critical' | 'warning' | 'upcoming' | 'ok';

export type FollowupStatus = 'overdue' | 'today' | 'upcoming' | 'scheduled';

// ============================================================================
// Approval Type Configuration
