/**
 * GET /api/communications/feed
 * Unified feed API — queries messages, email outbox, notifications, and
 * meeting action items in parallel, normalizes to FeedItem[], merges
 * chronologically, and paginates.
 *
 * Query params:
 *   limit    — 1..50 (default 30)
 *   offset   — number (default 0)
 *   channels — comma-separated: message,email,notification,meeting (default: all)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import type { FeedItem } from '@/modules/communications/types/hub.types';

const sql = neon(process.env.DATABASE_URL!);

type Channel = 'message' | 'email' | 'notification' | 'meeting';
const ALL_CHANNELS: Channel[] = ['message', 'email', 'notification', 'meeting'];

// ---------------------------------------------------------------------------
// Channel query helpers
// ---------------------------------------------------------------------------

async function fetchMessages(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      m.id,
      m.subject,
      m.body,
      m.priority,
      m.context_module,
      m.created_at,
      u.first_name || ' ' || u.last_name AS sender_name,
      r.is_read,
      (
        SELECT COUNT(*)::int FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS reply_count,
      (
        SELECT MAX(sub.created_at) FROM internal_messages sub
        WHERE sub.thread_id = m.id
      ) AS latest_reply_at
    FROM internal_messages m
    JOIN internal_message_recipients r
      ON r.message_id = m.id AND r.recipient_id = ${userId}::uuid
    JOIN users u ON u.id = m.sender_id
    WHERE m.thread_id IS NULL
      AND r.is_archived = FALSE
    ORDER BY COALESCE(
      (SELECT MAX(sub.created_at) FROM internal_messages sub WHERE sub.thread_id = m.id),
      m.created_at
    ) DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'message',
    title: r.subject || r.sender_name,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.latest_reply_at || r.created_at,
    isRead: !!r.is_read,
    actionUrl: '/communications?tab=inbox',
    sourceModule: r.context_module || 'messaging',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      reply_count: Number(r.reply_count),
      sender_name: r.sender_name,
    },
  }));
}

async function fetchEmails(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      e.id,
      e.subject,
      e.recipient_email,
      e.recipient_name,
      e.source_module,
      e.status,
      e.sent_at,
      e.created_at
    FROM email_outbox e
    WHERE e.sender_id = ${userId}::uuid
    ORDER BY e.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'email',
    title: r.subject,
    body: r.recipient_name
      ? `To: ${r.recipient_name} <${r.recipient_email}>`
      : `To: ${r.recipient_email}`,
    timestamp: r.sent_at || r.created_at,
    isRead: true, // Sent by user
    actionUrl: null,
    sourceModule: r.source_module || 'email',
    sourceId: r.id,
    metadata: {
      status: r.status,
      recipient_name: r.recipient_name,
      recipient_email: r.recipient_email,
    },
  }));
}

async function fetchNotifications(userId: string): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      n.id,
      n.title,
      n.body,
      n.icon,
      n.severity,
      n.event_type,
      n.action_url,
      n.source_module,
      n.source_id,
      n.is_read,
      n.created_at
    FROM user_notifications n
    WHERE n.user_id = ${userId}::uuid
      AND n.event_type != 'messaging.new_message'
    ORDER BY n.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'notification',
    title: r.title,
    body: r.body ? String(r.body).slice(0, 200) : null,
    timestamp: r.created_at,
    isRead: !!r.is_read,
    actionUrl: r.action_url || null,
    sourceModule: r.source_module || null,
    sourceId: r.source_id || null,
    metadata: {
      severity: r.severity,
      event_type: r.event_type,
      icon: r.icon,
    },
  }));
}

async function fetchMeetingActions(
  userId: string,
  userEmail: string
): Promise<FeedItem[]> {
  const rows = await sql`
    SELECT
      ai.id,
      ai.description,
      ai.assignee_name,
      ai.status::text AS status,
      ai.priority::text AS priority,
      ai.due_date,
      ai.created_at,
      m.title AS meeting_title
    FROM meeting_action_items ai
    LEFT JOIN meetings m ON ai.meeting_id = m.id
    WHERE (ai.assignee_email = ${userEmail} OR ai.created_by = ${userId}::uuid)
      AND ai.status::text IN ('pending', 'in_progress')
    ORDER BY ai.created_at DESC
    LIMIT 50
  `;

  return rows.map((r): FeedItem => ({
    id: r.id,
    channel: 'meeting',
    title: r.description ? String(r.description).slice(0, 120) : 'Action item',
    body: r.meeting_title
      ? `${r.meeting_title}${r.due_date ? ` — Due: ${new Date(r.due_date).toLocaleDateString('en-ZA')}` : ''}`
      : null,
    timestamp: r.created_at,
    isRead: r.status !== 'pending',
    actionUrl: '/action-items',
    sourceModule: 'meetings',
    sourceId: r.id,
    metadata: {
      priority: r.priority,
      status: r.status,
      due_date: r.due_date,
      assignee: r.assignee_name,
    },
  }));
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;
  const userEmail = authUser.email;

  try {
    // Parse params
    const limit = Math.min(
      Math.max(parseInt(String(req.query.limit || '30'), 10) || 30, 1),
      50
    );
    const offset = Math.max(
      parseInt(String(req.query.offset || '0'), 10) || 0,
      0
    );

    const channelsParam = String(req.query.channels || '').trim();
    const requestedChannels: Channel[] = channelsParam
      ? (channelsParam.split(',').filter(c => ALL_CHANNELS.includes(c as Channel)) as Channel[])
      : ALL_CHANNELS;

    if (requestedChannels.length === 0) {
      return apiResponse.success(res, {
        items: [],
        total: 0,
        counts: { message: 0, email: 0, notification: 0, meeting: 0 },
      });
    }

    // Fetch all active channels in parallel
    const fetchers: Record<Channel, () => Promise<FeedItem[]>> = {
      message: () => fetchMessages(userId),
      email: () => fetchEmails(userId),
      notification: () => fetchNotifications(userId),
      meeting: () => fetchMeetingActions(userId, userEmail),
    };

    const results = await Promise.all(
      requestedChannels.map(async (ch) => ({
        channel: ch,
        items: await fetchers[ch](),
      }))
    );

    // Build per-channel counts
    const counts = { message: 0, email: 0, notification: 0, meeting: 0 };
    const allItems: FeedItem[] = [];

    for (const { channel, items } of results) {
      counts[channel] = items.length;
      allItems.push(...items);
    }

    // Sort by timestamp DESC
    allItems.sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    const total = allItems.length;
    const paginated = allItems.slice(offset, offset + limit);

    return apiResponse.success(res, {
      items: paginated,
      total,
      counts,
    });
  } catch (error) {
    log.error('Failed to fetch unified feed', { error }, 'CommunicationsFeed');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * GET/PUT /api/communications/settings
 * GET: Returns merged notification preferences + global user communication settings.
 * PUT: Upserts per-event notification preferences AND global settings atomically.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import {
  DEFAULT_CHANNEL_PREFERENCES,
  EVENT_LABELS,
  EVENT_GROUPS,
  getRegisteredEventTypes,
} from '@/modules/notifications/constants';
import type { MergedPreference } from '@/modules/notifications/types';
import type {
  UserCommunicationSettings,
  CommunicationsSettingsResponse,
} from '@/modules/communications/types/settings.types';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    return handleGet(req, res);
  }
  if (req.method === 'PUT') {
    return handlePut(req, res);
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PUT']);
}

/** GET: Return merged preferences + global settings */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  try {
    const userId = authReq.user.id;

    // Fetch per-event notification preference overrides
    const overrides = await sql`
      SELECT event_type, channel_in_app, channel_email, channel_whatsapp
      FROM notification_preferences
      WHERE user_id = ${userId}::uuid
    `;

    const overrideMap = new Map(overrides.map(r => [r.event_type, r]));

    // Merge registered event types with user overrides
    const fallback = DEFAULT_CHANNEL_PREFERENCES._fallback ?? { in_app: true, email: false, whatsapp: false };
    const eventTypes = getRegisteredEventTypes();

    const preferences: MergedPreference[] = eventTypes.map(eventType => {
      const defaults = DEFAULT_CHANNEL_PREFERENCES[eventType] ?? fallback;
      const userOverride = overrideMap.get(eventType);
      return {
        event_type: eventType,
        label: EVENT_LABELS[eventType] ?? eventType,
        group: EVENT_GROUPS[eventType] ?? 'Other',
        channel_in_app: userOverride ? Boolean(userOverride.channel_in_app) : defaults.in_app,
        channel_email: userOverride ? Boolean(userOverride.channel_email) : defaults.email,
        channel_whatsapp: userOverride ? Boolean(userOverride.channel_whatsapp) : defaults.whatsapp,
        is_user_override: !!userOverride,
      };
    });

    // Fetch global settings (returns 0 or 1 rows)
    const [globalRow] = await sql`
      SELECT quiet_hours_enabled, quiet_hours_start, quiet_hours_end,
             digest_frequency, email_signature
      FROM user_communication_settings
      WHERE user_id = ${userId}::uuid
    `;

    const globalSettings: UserCommunicationSettings = {
      quiet_hours_enabled: globalRow ? Boolean(globalRow.quiet_hours_enabled) : false,
      quiet_hours_start: globalRow?.quiet_hours_start ?? '22:00',
      quiet_hours_end: globalRow?.quiet_hours_end ?? '07:00',
      digest_frequency: (globalRow?.digest_frequency as UserCommunicationSettings['digest_frequency']) ?? 'immediate',
      email_signature: globalRow?.email_signature ?? null,
    };

    const payload: CommunicationsSettingsResponse = { preferences, globalSettings };
    return apiResponse.success(res, payload);
  } catch (error) {
    return apiResponse.internalError(res, error);
  }
}

/** PUT: Upsert per-event preferences + global settings */
async function handlePut(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  try {
    const userId = authReq.user.id;
    const { preferences, globalSettings } = req.body ?? {};

    // Validate preferences array when provided
    if (preferences !== undefined && !Array.isArray(preferences)) {
      return apiResponse.badRequest(
        res,
        'preferences must be an array of { event_type, channel_in_app, channel_email, channel_whatsapp }'
      );
    }

    // Validate globalSettings shape when provided
    if (globalSettings !== undefined && typeof globalSettings !== 'object') {
      return apiResponse.badRequest(res, 'globalSettings must be an object');
    }

    // Upsert per-event preferences
    let updatedCount = 0;
    if (Array.isArray(preferences)) {
      for (const pref of preferences) {
        if (!pref.event_type || typeof pref.event_type !== 'string') {
          continue;
        }
        await sql`
          INSERT INTO notification_preferences (
            user_id, event_type, channel_in_app, channel_email, channel_whatsapp, updated_at
          ) VALUES (
            ${userId}::uuid, ${pref.event_type},
            ${!!pref.channel_in_app}, ${!!pref.channel_email}, ${!!pref.channel_whatsapp},
            NOW()
          )
          ON CONFLICT (user_id, event_type)
          DO UPDATE SET
            channel_in_app = ${!!pref.channel_in_app},
            channel_email = ${!!pref.channel_email},
            channel_whatsapp = ${!!pref.channel_whatsapp},
            updated_at = NOW()
        `;
        updatedCount++;
      }
    }

    // Upsert global communication settings
    if (globalSettings && typeof globalSettings === 'object') {
      const quietEnabled = !!globalSettings.quiet_hours_enabled;
      const quietStart: string = globalSettings.quiet_hours_start ?? '22:00';
      const quietEnd: string = globalSettings.quiet_hours_end ?? '07:00';
      const validFrequencies = ['immediate', 'hourly', 'daily'];
      const digestFreq: string = validFrequencies.includes(globalSettings.digest_frequency)
        ? globalSettings.digest_frequency
        : 'immediate';
      const emailSig: string | null = globalSettings.email_signature ?? null;

      await sql`
        INSERT INTO user_communication_settings (
          user_id, quiet_hours_enabled, quiet_hours_start, quiet_hours_end,
          digest_frequency, email_signature, updated_at
        ) VALUES (
          ${userId}::uuid, ${quietEnabled}, ${quietStart}, ${quietEnd},
          ${digestFreq}, ${emailSig}, NOW()
        )
        ON CONFLICT (user_id)
        DO UPDATE SET
          quiet_hours_enabled = ${quietEnabled},
          quiet_hours_start = ${quietStart},
          quiet_hours_end = ${quietEnd},
          digest_frequency = ${digestFreq},
          email_signature = ${emailSig},
          updated_at = NOW()
      `;
    }

    return apiResponse.success(res, { updated: updatedCount });
  } catch (error) {
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

/**
 * Badge Counts API
 * GET /api/communications/badge-counts
 *
 * Returns unread/pending counts for inbox, notifications, and action items.
 * Used by useBadgeCounts hook to drive nav badge indicators.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const authUser = (req as AuthenticatedNextApiRequest).user;
  const userId = authUser.id;
  const userEmail = authUser.email;

  try {
    // Single CTE query — three counts in one round trip
    const result = await sql`
      WITH inbox_count AS (
        SELECT COUNT(*)::int AS cnt
        FROM internal_message_recipients r
        INNER JOIN internal_messages m ON m.id = r.message_id
        WHERE r.recipient_id = ${userId}::uuid
          AND r.is_read = FALSE
          AND r.is_archived = FALSE
          AND m.thread_id IS NULL
      ),
      notification_count AS (
        SELECT COUNT(*)::int AS cnt
        FROM user_notifications n
        WHERE n.user_id = ${userId}::uuid
          AND n.is_read = FALSE
      ),
      action_item_count AS (
        SELECT COUNT(*)::int AS cnt
        FROM meeting_action_items ai
        WHERE (ai.assignee_email = ${userEmail} OR ai.created_by = ${userId}::uuid)
          AND ai.status::text = 'pending'
      )
      SELECT
        (SELECT cnt FROM inbox_count)        AS inbox,
        (SELECT cnt FROM notification_count) AS notifications,
        (SELECT cnt FROM action_item_count)  AS action_items
    `;

    const row = result[0] ?? { inbox: 0, notifications: 0, action_items: 0 };

    return apiResponse.success(res, {
      inbox: Number(row.inbox ?? 0),
      notifications: Number(row.notifications ?? 0),
      actionItems: Number(row.action_items ?? 0),
    });
  } catch (error) {
    log.error('Failed to fetch badge counts', { error }, 'BadgeCounts');
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(handler);

