    warning: approvals.filter((a) => a.urgency === 'warning'),
    upcoming: approvals.filter((a) => a.urgency === 'upcoming'),
  };

  return apiResponse.success(res, {
    total: approvals.length,
    by_urgency: grouped,
    all: approvals,
  });
}

