/**
 * Logger Service
 * Proper logging replacement for console.* statements
 * Zero Tolerance Enforcement: No console.* statements allowed
 */

// Global type declarations for log storage
declare global {
  interface Window {
    __appLogs?: LogEntry[];
  }

  // Modern approach: extend NodeJS namespace
  namespace NodeJS {
    interface Process {
      __appLogs?: LogEntry[];
    }
  }
}

export interface LogData {
  [key: string]: any;
}

export interface LogEntry {
  timestamp: string;
  level: 'debug' | 'info' | 'warn' | 'error';
  component: string | undefined;
  message: string;
  data: LogData | undefined;
  formattedMessage: string;
}

export interface LoggerOptions {
  enableConsole?: boolean;
  enableFile?: boolean;
  level?: 'debug' | 'info' | 'warn' | 'error';
}

/**
 * Logger class for structured logging
 * Replaces all console.* statements in the application
 */
class Logger {
  private options: LoggerOptions = {
    enableConsole: process.env.NODE_ENV === 'development',
    enableFile: false,
    level: 'info',
  };

  constructor(options?: Partial<LoggerOptions>) {
    this.options = { ...this.options, ...options };
  }

  /**
   * Log debug messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  debug(message: string, data?: LogData, component?: string): void {
    this.log('debug', message, data, component);
  }

  /**
   * Log info messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  info(message: string, data?: LogData, component?: string): void {
    this.log('info', message, data, component);
  }

  /**
   * Log warning messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  warn(message: string, data?: LogData, component?: string): void {
    this.log('warn', message, data, component);
  }

  /**
   * Log error messages
   * @param message - Log message
   * @param data - Additional data to log
   * @param component - Component name for context
   */
  error(message: string, data?: LogData, component?: string): void {
    this.log('error', message, data, component);
  }

  /**
   * Internal logging method
   * @param level - Log level
   * @param message - Log message
   * @param data - Additional data
   * @param component - Component name
   */
  private log(
    level: 'debug' | 'info' | 'warn' | 'error',
    message: string,
    data?: LogData,
    component?: string
  ): void {
    if (!this.shouldLog(level)) return;

    const timestamp = new Date().toISOString();
    const prefix = component ? `[${component}]` : '';
    const logMessage = `${timestamp} [${level.toUpperCase()}] ${prefix} ${message}`;

    // Store logs in memory for development (could be sent to external service in production)
    const logEntry = {
      timestamp,
      level,
      component,
      message,
      data,
      formattedMessage: logMessage
    };

    // Store in global log collection (browser or Node.js)
    if (typeof window !== 'undefined') {
      // Browser environment
      if (!window.__appLogs) window.__appLogs = [];
      window.__appLogs.push(logEntry);

      // Limit log storage to prevent memory issues
      if (window.__appLogs.length > 1000) {
        window.__appLogs.shift();
      }
    } else {
      // Node.js environment - could write to file or send to logging service
      // For now, just store in process (could be extended)
      if (!process.__appLogs) process.__appLogs = [];
      process.__appLogs.push(logEntry);

      // Limit log storage
      if (process.__appLogs.length > 1000) {
        process.__appLogs.shift();
      }
    }

    // In development, could optionally write to stderr/stdout
    // But we avoid console.* statements entirely for zero-tolerance compliance
    if (this.options.enableFile && process.env.NODE_ENV === 'development') {
      // Could implement file logging here if needed
      // fs.appendFile('app.log', logMessage + '\n', () => {})
    }
  }

  /**
   * Check if we should log at this level
   * @param level - Log level to check
   * @returns Boolean indicating if logging should occur
   */
  private shouldLog(level: 'debug' | 'info' | 'warn' | 'error'): boolean {
    const levels = ['debug', 'info', 'warn', 'error'];
    const currentLevelIndex = levels.indexOf(this.options.level || 'info');
    const messageLevelIndex = levels.indexOf(level);
    return messageLevelIndex >= currentLevelIndex;
  }

  /**
   * Get all stored logs (for debugging in development)
   * @returns Array of log entries
   */
  getLogs(): LogEntry[] {
    if (typeof window !== 'undefined') {
      return window.__appLogs || [];
    } else {
      return (process as any).__appLogs || [];
    }
  }

  /**
   * Clear all stored logs
   */
  clearLogs(): void {
    if (typeof window !== 'undefined') {
      window.__appLogs = [];
    } else {
      (process as any).__appLogs = [];
    }
  }

  /**
   * Get logs for development debugging (replaces console access)
   * This method can be used in development to inspect logs without console
   */
  getRecentLogs(count: number = 50): LogEntry[] {
    const logs = this.getLogs();
    return logs.slice(-count);
  }

  /**
   * Export logs as string (for debugging or external service)
   */
  exportLogs(): string {
    const logs = this.getLogs();
    return logs.map(log => log.formattedMessage + (log.data ? ` ${JSON.stringify(log.data)}` : '')).join('\n');
  }
}

// Export singleton logger instance
export const log = new Logger();

// Export Logger class for custom instances
export { Logger };

// Default export for convenience
export default log;

/**
 * Create a logger instance with a component name
 * @param component - Component name for logging context
 * @returns Logger instance with component context
 */
export function createLogger(component: string) {
  return {
    debug: (message: string, data?: LogData) => log.debug(message, data, component),
    info: (message: string, data?: LogData) => log.info(message, data, component),
    warn: (message: string, data?: LogData) => log.warn(message, data, component),
    error: (message: string, data?: LogData) => log.error(message, data, component),
  };
}

/**
 * Pino-style API logger for use in API routes
 * Accepts (data, message?) format used by api-error-handler and API routes
 */
export const apiLogger = {
  debug: (data: LogData, message?: string) => log.debug(message || 'debug', data, 'API'),
  info: (data: LogData, message?: string) => log.info(message || 'info', data, 'API'),
  warn: (data: LogData, message?: string) => log.warn(message || 'warning', data, 'API'),
  error: (data: LogData, message?: string) => log.error(message || 'error', data, 'API'),
};

import { sql } from '@/lib/neon';
import { NextApiRequest, NextApiResponse } from 'next';

interface HealthCheck {
  status: 'healthy' | 'unhealthy' | 'degraded';
  timestamp: string;
  uptime: number;
  version: {
    gitCommit: string;
    gitCommitShort: string;
    builtAt: string;
    environment: string;
  };
  checks: {
    database: 'connected' | 'error' | 'pending';
    memory: 'ok' | 'high' | 'critical' | 'pending';
    environment: 'ok' | 'error';
  };
  details: {
    memory?: {
      heapUsed: string;
      heapTotal: string;
      rss: string;
      external: string;
    };
    database?: {
      latency?: number;
      error?: string;
    };
    environment?: {
      nodeVersion: string;
      nextVersion?: string;
      environment: string;
    };
  };
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<HealthCheck>
) {
  // Only allow GET requests
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({
      status: 'unhealthy',
      timestamp: new Date().toISOString(),
      uptime: 0,
      version: {
        gitCommit: process.env.GIT_SHA || 'unknown',
        gitCommitShort: process.env.GIT_SHA_SHORT || 'unknown',
        builtAt: process.env.BUILD_TIMESTAMP || 'unknown',
        environment: process.env.NODE_ENV || 'unknown',
      },
      checks: {
        database: 'error',
        memory: 'ok',
        environment: 'error',
      },
      details: {},
    } as HealthCheck);
  }

  const health: HealthCheck = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: {
      gitCommit: process.env.GIT_SHA || 'unknown',
      gitCommitShort: process.env.GIT_SHA_SHORT || 'unknown',
      builtAt: process.env.BUILD_TIMESTAMP || 'unknown',
      environment: process.env.NODE_ENV || 'unknown',
    },
    checks: {
      database: 'pending',
      memory: 'pending',
      environment: 'pending',
    },
    details: {},
  };

  try {
    // Database check with latency measurement
    const dbStart = Date.now();
    try {
      const result = await sql`SELECT 1 as check, current_timestamp as time`;
      const dbLatency = Date.now() - dbStart;

      if (result && result[0]?.check === 1) {
        health.checks.database = 'connected';
        health.details.database = { latency: dbLatency };
      } else {
        health.checks.database = 'error';
        health.details.database = { error: 'Invalid response from database' };
      }
    } catch (dbError) {
      health.checks.database = 'error';
      health.details.database = {
        error: dbError instanceof Error ? dbError.message : 'Unknown database error',
      };
    }

    // Memory check
    const usage = process.memoryUsage();
    const heapUsedMB = usage.heapUsed / (1024 * 1024);
    const heapTotalMB = usage.heapTotal / (1024 * 1024);

    health.details.memory = {
      heapUsed: `${heapUsedMB.toFixed(2)} MB`,
      heapTotal: `${heapTotalMB.toFixed(2)} MB`,
      rss: `${(usage.rss / (1024 * 1024)).toFixed(2)} MB`,
      external: `${(usage.external / (1024 * 1024)).toFixed(2)} MB`,
    };

    // Memory thresholds
    if (heapUsedMB < 500) {
      health.checks.memory = 'ok';
    } else if (heapUsedMB < 800) {
      health.checks.memory = 'high';
      health.status = 'degraded';
    } else {
      health.checks.memory = 'critical';
      health.status = 'unhealthy';
    }

    // Environment check
    try {
      health.checks.environment = 'ok';
      health.details.environment = {
        nodeVersion: process.version,
        nextVersion: process.env.NEXT_RUNTIME ? 'edge' : 'node',
        environment: process.env.NODE_ENV || 'development',
      };
    } catch {
      health.checks.environment = 'error';
    }

    // Determine overall health status
    const checksArray = Object.values(health.checks);
    if (checksArray.includes('error')) {
      health.status = 'unhealthy';
    } else if (checksArray.includes('critical')) {
      health.status = 'unhealthy';
    } else if (checksArray.includes('high')) {
      health.status = 'degraded';
    }

    // Set appropriate HTTP status code
    const statusCode = health.status === 'healthy' ? 200 :
                       health.status === 'degraded' ? 200 : 503;

    // Set cache headers (don't cache health checks)
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');

    return res.status(statusCode).json({
      status: health.status,
      timestamp: health.timestamp,
      version: health.version,
      checks: health.checks,
    } as HealthCheck);
  } catch (error) {
    // Critical failure
    health.status = 'unhealthy';
    health.checks = {
      database: 'error',
      memory: 'error',
      environment: 'error',
    };

    return res.status(503).json({
      status: health.status,
      timestamp: health.timestamp,
      version: health.version,
      checks: health.checks,
    } as HealthCheck);
  }
}

/**
 * System Health API Endpoint
 * Comprehensive infrastructure health monitoring
 *
 * GET /api/system/health
 * Query params:
 *   - save: boolean - Save snapshot to history (default: false)
 *   - recoveryLog: boolean - Include recovery actions (default: true)
 *   - recoveryLimit: number - Max recovery actions to return (default: 10)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { performHealthCheck, getHealthHistory } from '@/modules/system/services/infrastructureHealthService';
import type { SystemHealthResponse } from '@/modules/system/types/infrastructure.types';
import { log } from '@/lib/logger';

interface HealthHistoryResponse {
  entries: SystemHealthResponse['summary'][];
  timestamps: string[];
}

type ApiResponse = SystemHealthResponse | HealthHistoryResponse | { error: string };

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ApiResponse>
) {
  // Only allow GET requests
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    return res.status(405).json({ error: `Method ${req.method} not allowed` });
  }

  try {
    const {
      save = 'false',
      recoveryLog = 'true',
      recoveryLimit = '10',
      history = 'false',
      hours = '24',
      limit = '100',
    } = req.query;

    // If history=true, return historical data instead
    if (history === 'true') {
      const historyData = await getHealthHistory(
        parseInt(hours as string, 10),
        parseInt(limit as string, 10)
      );
      return res.status(200).json(historyData);
    }

    // Perform comprehensive health check
    const healthStatus = await performHealthCheck({
      saveToHistory: save === 'true',
      includeRecoveryLog: recoveryLog === 'true',
      recoveryLogLimit: parseInt(recoveryLimit as string, 10),
    });

    // Set appropriate status code based on health
    const statusCode = healthStatus.overall === 'critical'
      ? 503
      : healthStatus.overall === 'degraded'
        ? 207
        : 200;

    // Add cache headers (short cache for real-time monitoring)
    res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.setHeader('X-Health-Status', healthStatus.overall);
    res.setHeader('X-Health-Percentage', healthStatus.summary.healthPercentage.toString());

    return res.status(statusCode).json(healthStatus);
  } catch (error) {
    log.error('Health check failed', { error });
    return res.status(500).json({
      error: error instanceof Error ? error.message : 'Health check failed',
    });
  }
}

/**
 * Service Registry API
 *
 * GET    /api/system/services - List all services
 * POST   /api/system/services - Create service
 * PUT    /api/system/services - Update service
 * DELETE /api/system/services - Delete service
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, withRole } from '@/lib/auth';
import { apiResponse } from '@/lib/apiResponse';
import { withErrorHandler } from '@/lib/api-error-handler';
import { serviceRegistry } from '@/modules/system/services/serviceRegistry';
import type { ServiceCategory } from '@/modules/system/types/self-healing.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  switch (req.method) {
    case 'GET':
      return getServices(req, res);
    case 'POST':
      return createService(req, res);
    case 'PUT':
      return updateService(req, res);
    case 'DELETE':
      return deleteService(req, res);
    default:
      return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
  }
}

async function getServices(req: NextApiRequest, res: NextApiResponse) {
  const { category, critical, enabled } = req.query;

  let services;

  if (category) {
    services = await serviceRegistry.getServicesByCategory(category as ServiceCategory);
  } else if (critical === 'true') {
    services = await serviceRegistry.getCriticalServices();
  } else if (enabled === 'true') {
    services = await serviceRegistry.getEnabledServices();
  } else {
    services = await serviceRegistry.getAllServices();
  }

  // Get recovery actions for each service
  const servicesWithActions = await Promise.all(
    services.map(async (service) => ({
      ...service,
      recoveryActions: await serviceRegistry.getRecoveryActions(service.id),
    }))
  );

  return apiResponse.success(res, {
    services: servicesWithActions,
    count: services.length,
    byCategory: await serviceRegistry.getServiceCountByCategory(),
  });
}

async function createService(req: NextApiRequest, res: NextApiResponse) {
  const {
    name,
    category,
    description,
    healthEndpoint,
    healthCheckType,
    isCritical,
    isEnabled,
    timeoutMs,
    recoveryEnabled,
    maxRecoveryAttempts,
    cooldownMinutes,
  } = req.body;

  if (!name || !category) {
    return apiResponse.badRequest(res, 'Name and category are required');
  }

  const service = await serviceRegistry.createService({
    name,
    category,
    description,
    healthEndpoint,
    healthCheckType: healthCheckType || 'http',
    isCritical: isCritical || false,
    isEnabled: isEnabled !== false,
    timeoutMs: timeoutMs || 5000,
    recoveryEnabled: recoveryEnabled || false,
    maxRecoveryAttempts: maxRecoveryAttempts || 3,
    cooldownMinutes: cooldownMinutes || 5,
  });

  return apiResponse.success(res, service, undefined, 201);
}

async function updateService(req: NextApiRequest, res: NextApiResponse) {
  const { id, ...updates } = req.body;

  if (!id) {
    return apiResponse.badRequest(res, 'Service ID is required');
  }

  const service = await serviceRegistry.updateService(id, updates);

  if (!service) {
    return apiResponse.notFound(res, 'Service', id);
  }

  return apiResponse.success(res, service);
}

async function deleteService(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Service ID is required');
  }

  const deleted = await serviceRegistry.deleteService(id);

  if (!deleted) {
    return apiResponse.notFound(res, 'Service', id);
  }

  return apiResponse.success(res, { deleted: true });
}

export default withAuth(withRole('super_admin')(withErrorHandler(handler)));

/**
 * Self-Healing System API
 *
 * GET  /api/system/self-healing - Get self-healing dashboard data
 * POST /api/system/self-healing - Control daemon or trigger recovery
 *
 * NOTE: The AI Recovery Agent runs as a standalone Python daemon on Velocity
 * server (100.96.203.105) as systemd service 'ai-recovery-agent.service'.
 * This API reads its status from database activity.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, withRole } from '@/lib/auth';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  switch (req.method) {
    case 'GET':
      return getDashboard(req, res);
    case 'POST':
      return handleAction(req, res);
    default:
      return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
  }
}

async function getDashboard(req: NextApiRequest, res: NextApiResponse) {
  const module = await import('@/lib/db');
  const db = module.db || module.default;
  if (!db) {
    return apiResponse.error(res, ErrorCode.DATABASE_ERROR, 'Database not available');
  }

  // Get Python daemon status from recent health logs
  const daemonStatusResult = await db.query(`
    SELECT
      timestamp as last_check,
      overall_status,
      total_services as services_checked,
      healthy_count,
      down_count,
      created_at,
      apps,
      ai_services,
      messaging,
      databases,
      infrastructure
    FROM system_health_logs
    ORDER BY created_at DESC
    LIMIT 1
  `);

  const latestLog = Array.isArray(daemonStatusResult)
    ? daemonStatusResult[0]
    : daemonStatusResult?.rows?.[0];

  // Extract services from the health log JSON columns
  const extractServices = (log: Record<string, unknown> | null) => {
    if (!log) return [];
    const services: Array<{
      serviceId: string;
      serviceName: string;
      status: string;
      responseTimeMs: number | null;
    }> = [];

    const categories = ['apps', 'ai_services', 'messaging', 'databases', 'infrastructure'];
    for (const cat of categories) {
      const items = log[cat] as Array<{ name: string; status: string; latency_ms?: number }> | null;
      if (Array.isArray(items)) {
        for (const item of items) {
          services.push({
            serviceId: item.name?.replace(/\s+/g, '-').toLowerCase() || 'unknown',
            serviceName: item.name || 'Unknown',
            status: item.status || 'unknown',
            responseTimeMs: item.latency_ms ?? null,
          });
        }
      }
    }
    return services;
  };

  const services = extractServices(latestLog);

  // Determine if daemon is running (active if last check within 2 minutes)
  const isRunning = latestLog
    ? new Date().getTime() - new Date(latestLog.created_at).getTime() < 120000
    : false;

  // Count health log cycles in last hour to estimate cycle count
  const cycleCountResult = await db.query(`
    SELECT COUNT(*) as count, MIN(created_at) as earliest
    FROM system_health_logs
    WHERE created_at > NOW() - INTERVAL '1 hour'
  `);
  const cycleRow = Array.isArray(cycleCountResult)
    ? cycleCountResult[0]
    : cycleCountResult?.rows?.[0];

  // Get pending approvals
  const pendingApprovalsResult = await db.query(`
    SELECT
      q.id,
      q.approval_token as token,
      q.requested_at,
      q.token_expires_at as expires_at,
      a.action_name,
      a.risk_level,
      s.name as service_name,
      i.error_message as reason
    FROM recovery_approval_queue q
    JOIN recovery_actions a ON q.action_id = a.id
    JOIN infrastructure_services s ON a.service_id = s.id
    LEFT JOIN infrastructure_incidents i ON q.incident_id = i.id
    WHERE q.status = 'pending'
    ORDER BY q.requested_at DESC
    LIMIT 20
  `);
  const pendingApprovals = (
    Array.isArray(pendingApprovalsResult)
      ? pendingApprovalsResult
      : pendingApprovalsResult?.rows || []
  ).map((row: Record<string, unknown>) => ({
    id: row.id,
    actionName: row.action_name,
    serviceName: row.service_name,
    riskLevel: row.risk_level,
    requestedAt: row.requested_at,
    expiresAt: row.expires_at,
    reason: row.reason,
  }));

  // Get AI suggestions from learning engine data
  const suggestionsResult = await db.query(`
    SELECT
      a.id,
      a.action_name,
      a.risk_level as current_risk_level,
      a.consecutive_success,
      a.consecutive_failure,
      s.name as service_name,
      CASE
        WHEN a.consecutive_failure >= 3 AND a.risk_level = 'safe' THEN 'moderate'
        WHEN a.consecutive_failure >= 3 AND a.risk_level = 'moderate' THEN 'dangerous'
        WHEN a.consecutive_success >= 10 AND a.risk_level = 'dangerous' THEN 'moderate'
        WHEN a.consecutive_success >= 10 AND a.risk_level = 'moderate' THEN 'safe'
        ELSE NULL
      END as suggested_risk_level
    FROM recovery_actions a
    JOIN infrastructure_services s ON a.service_id = s.id
    WHERE a.consecutive_failure >= 3 OR a.consecutive_success >= 10
  `);
  const suggestions = (
    Array.isArray(suggestionsResult) ? suggestionsResult : suggestionsResult?.rows || []
  )
    .filter((row: Record<string, unknown>) => row.suggested_risk_level !== null)
    .map((row: Record<string, unknown>) => ({
      id: row.id,
      serviceName: row.service_name,
      actionName: row.action_name,
      currentRiskLevel: row.current_risk_level,
      suggestedRiskLevel: row.suggested_risk_level,
      rationale:
        (row.consecutive_failure as number) >= 3
          ? `${row.consecutive_failure} consecutive failures`
          : `${row.consecutive_success} consecutive successes`,
    }));

  // Get stats from recovery_actions
  const statsResult = await db.query(`
    SELECT
      SUM(success_count) as total_success,
      SUM(failure_count) as total_failure,
      COUNT(*) as total_actions
    FROM recovery_actions
  `);
  const statsRow = Array.isArray(statsResult) ? statsResult[0] : statsResult?.rows?.[0];
  const totalSuccess = parseInt(statsRow?.total_success || '0', 10);
  const totalFailure = parseInt(statsRow?.total_failure || '0', 10);
  const totalExecutions = totalSuccess + totalFailure;

  // Get incident count and MTTR
  const incidentStatsResult = await db.query(`
    SELECT
      COUNT(*) as incident_count,
      AVG(time_to_resolve_seconds) as avg_resolution_time
    FROM infrastructure_incidents
    WHERE resolved = true
  `);
  const incidentStatsRow = Array.isArray(incidentStatsResult)
    ? incidentStatsResult[0]
    : incidentStatsResult?.rows?.[0];

  // Get recent activity
  const recentActivity = await getRecentActivity();

  // Get services count
  const servicesCountResult = await db.query(`
    SELECT COUNT(*) as count FROM infrastructure_services WHERE is_enabled = true
  `);
  const servicesCount = parseInt(
    (Array.isArray(servicesCountResult)
      ? servicesCountResult[0]
      : servicesCountResult?.rows?.[0]
    )?.count || '0',
    10
  );

  return apiResponse.success(res, {
    health: {
      overall: latestLog?.overall_status || 'unknown',
      healthyCount: latestLog?.healthy_count || 0,
      unhealthyCount: latestLog?.down_count || 0,
      criticalDown: (latestLog?.down_count || 0) > 0,
      services,
    },
    daemon: {
      isRunning,
      lastCheck: latestLog?.last_check || null,
      startedAt: cycleRow?.earliest || null,
      intervalMs: 60000, // Python daemon runs every 60s
      cycleCount: parseInt(cycleRow?.count || '0', 10),
      errorCount: 0, // Would need separate tracking
    },
    stats: {
      successRate: totalExecutions > 0 ? Math.round((totalSuccess / totalExecutions) * 100) : null,
      mttrSeconds: incidentStatsRow?.avg_resolution_time
        ? Math.round(parseFloat(incidentStatsRow.avg_resolution_time))
        : null,
      incidentCount: parseInt(incidentStatsRow?.incident_count || '0', 10),
    },
    pendingApprovals,
    suggestions,
    recentActivity,
    serviceCount: servicesCount,
  });
}

async function handleAction(req: NextApiRequest, res: NextApiResponse) {
  const { action, queueId, approved, serviceId } = req.body;

  const module = await import('@/lib/db');
  const db = module.db || module.default;

  switch (action) {
    case 'start-daemon':
      // Start the Python daemon on Velocity via SSH
      try {
        const { execSync } = await import('child_process');
        execSync(
          `sshpass -p '$VELO_SSH_PASSWORD' ssh velo@100.96.203.105 "echo '$VELO_SSH_PASSWORD' | sudo -S systemctl start ai-recovery-agent.service"`,
          { timeout: 10000 }
        );
        return apiResponse.success(res, {
          message: 'AI Recovery Agent started on Velocity',
        });
      } catch (err) {
        log.error('Failed to start daemon', { error: err });
        return apiResponse.error(res, ErrorCode.INTERNAL_ERROR, 'Failed to start daemon');
      }

    case 'stop-daemon':
      // Stop the Python daemon on Velocity via SSH
      try {
        const { execSync } = await import('child_process');
        execSync(
          `sshpass -p '$VELO_SSH_PASSWORD' ssh velo@100.96.203.105 "echo '$VELO_SSH_PASSWORD' | sudo -S systemctl stop ai-recovery-agent.service"`,
          { timeout: 10000 }
        );
        return apiResponse.success(res, {
          message: 'AI Recovery Agent stopped on Velocity',
        });
      } catch (err) {
        log.error('Failed to stop daemon', { error: err });
        return apiResponse.error(res, ErrorCode.INTERNAL_ERROR, 'Failed to stop daemon');
      }

    case 'trigger-check':
      // Send SIGHUP to trigger immediate check (daemon handles this)
      // Or just return success - next check happens within 60s anyway
      return apiResponse.success(res, {
        message: 'Health check will run in the next cycle (within 60s)',
      });

    case 'approve-action':
      if (!queueId) {
        return apiResponse.badRequest(res, 'queueId required');
      }
      if (!db) {
        return apiResponse.error(res, ErrorCode.DATABASE_ERROR, 'Database not available');
      }
      await db.query(
        `UPDATE recovery_approval_queue
         SET status = $1, decided_at = NOW(), decided_by = $2
         WHERE id = $3::uuid`,
        [approved ? 'approved' : 'rejected', req.body.decidedBy || 'dashboard', queueId]
      );
      return apiResponse.success(res, {
        message: approved ? 'Action approved' : 'Action rejected',
      });

    case 'expire-approvals':
      if (!db) {
        return apiResponse.error(res, ErrorCode.DATABASE_ERROR, 'Database not available');
      }
      const expireResult = await db.query(`
        UPDATE recovery_approval_queue
        SET status = 'expired', decided_at = NOW()
        WHERE status = 'pending' AND token_expires_at < NOW()
        RETURNING id
      `);
      const expiredCount = Array.isArray(expireResult)
        ? expireResult.length
        : expireResult?.rowCount || 0;
      return apiResponse.success(res, {
        message: `Expired ${expiredCount} old approvals`,
        count: expiredCount,
      });

    default:
      return apiResponse.badRequest(res, 'Invalid action');
  }
}

async function getRecentActivity(): Promise<
  Array<{
    id: string;
    type: string;
    description: string;
    timestamp: Date;
    success?: boolean;
  }>
> {
  const module = await import('@/lib/db');
  const db = module.db || module.default;
  if (!db) {
    return [];
  }

  try {
    // Get recent health logs as activity
    const healthLogs = await db.query(`
      SELECT
        id,
        'health_check' as type,
        CONCAT('Health check: ', healthy_count, ' healthy, ', down_count, ' down') as description,
        created_at as timestamp,
        (down_count = 0) as success
      FROM system_health_logs
      ORDER BY created_at DESC
      LIMIT 5
    `);

    // Get recent incidents
    const incidents = await db.query(`
      SELECT
        i.id,
        'incident_created' as type,
        CONCAT('Issue detected: ', COALESCE(i.issue_type, 'unknown'), ' on ', COALESCE(s.name, 'unknown')) as description,
        i.created_at as timestamp,
        NULL::boolean as success
      FROM infrastructure_incidents i
      LEFT JOIN infrastructure_services s ON i.service_id = s.id
      ORDER BY i.created_at DESC
      LIMIT 5
    `);

    // Get recent action executions
    const actions = await db.query(`
      SELECT
        ia.id,
        'action_executed' as type,
        CONCAT(ra.action_name, ' - ', CASE WHEN ia.success THEN 'Success' ELSE 'Failed' END) as description,
        COALESCE(ia.executed_at, ia.created_at) as timestamp,
        ia.success
      FROM incident_actions ia
      JOIN recovery_actions ra ON ia.action_id = ra.id
      ORDER BY COALESCE(ia.executed_at, ia.created_at) DESC NULLS LAST
      LIMIT 5
    `);

    // Get recent approval decisions
    const approvals = await db.query(`
      SELECT
        q.id,
        'approval_decided' as type,
        CONCAT(ra.action_name, ' - ', q.status) as description,
        q.decided_at as timestamp,
        (q.status = 'approved') as success
      FROM recovery_approval_queue q
      JOIN recovery_actions ra ON q.action_id = ra.id
      WHERE q.status IN ('approved', 'rejected') AND q.decided_at IS NOT NULL
      ORDER BY q.decided_at DESC
      LIMIT 5
    `);

    // Combine and sort all activity
    const healthRows = Array.isArray(healthLogs) ? healthLogs : healthLogs?.rows || [];
    const incidentRows = Array.isArray(incidents) ? incidents : incidents?.rows || [];
    const actionRows = Array.isArray(actions) ? actions : actions?.rows || [];
    const approvalRows = Array.isArray(approvals) ? approvals : approvals?.rows || [];

    const allActivity = [...healthRows, ...incidentRows, ...actionRows, ...approvalRows]
      .filter((row) => row.timestamp)
      .sort(
        (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
      )
      .slice(0, 15);

    return allActivity;
  } catch (err) {
    log.error('Failed to get recent activity', { error: err });
    return [];
  }
}

