/**
 * Result from WA photo serial extraction
 */
export interface WaPhotoExtractionResult {
  success: boolean;
  ontSerial: string | null;
  upsSerial: string | null;
  confidence: number;
  ontConfidence: number;
  upsConfidence: number;
  processingTimeMs: number;
  error?: string;
}

/**
 * Prompt for extracting ONT and UPS serials from WA photo sticker
 * WA photos typically show a printed sticker with both serials clearly visible
 */
const WA_PHOTO_SERIAL_PROMPT = `You are extracting device serial numbers from a WhatsApp-submitted installation photo.

This photo shows a printed sticker with TWO serial numbers:

1. ONT SERIAL NUMBER:
   FORMAT: ALCLB4 + 6 hex characters = exactly 12 characters
   - The 7th char is "8" (64%), "7" (26%), or "6" (10%) — read carefully, don't assume
   - Top patterns: ALCLB48D (20%), ALCLB477 (15%), ALCLB48C (12%), ALCLB48A (9%), ALCLB48F (6%)
   - Only hex chars (0-9, A-F) after the ALCLB4 prefix
   - NEVER letters M, N, P, R, S, Y, Z — those mean you misread
   - Usually labeled "S/N:" or "ONT Serial"
   ❌ Do NOT extract SSID values (start with "ALHN-")
   ❌ Do NOT extract model/part numbers (start with "STN")

2. UPS SERIAL NUMBER:
   - Starts with "GU18W" followed by 8-10 alphanumeric characters
   - Usually labeled "UPS Serial" or "Gizzu Serial"
   - 13-15 characters total

⚠️ VALIDATION (check before answering):
- ONT serial must be exactly 12 chars starting with ALCLB4
- If you read 11 chars, you likely dropped a char at position 7
- If chars after ALCLB4 include M/N/P/R/Y, re-read — those aren't hex

Respond in this exact JSON format:
{
  "ontSerial": {
    "found": true/false,
    "serial": "<12-char serial starting with ALCLB4, or null>",
    "confidence": <0.0 to 1.0>
  },
  "upsSerial": {
    "found": true/false,
    "serial": "<serial starting with GU18W, or null>",
    "confidence": <0.0 to 1.0>
  }
}

CRITICAL: Only extract serials you can ACTUALLY READ. null is better than wrong.`;

/**
 * Serials used as examples in VLM prompts — if the model returns
 * one of these exactly it is regurgitating the prompt, not reading
 * the photo.  Normalised to uppercase, stripped of whitespace/dashes.
 */
const PROMPT_EXAMPLE_SERIALS = new Set([
  'ALCLB6A9C97',
  'ALCLB48CC3CA',
  'ALCLB48F2939',
  'ALCL12345678',
  'ALCLM1234567',
  'ALCL8400821',
  'ALCL6400821',
  'ALCL8408021',
  'ALCL84080311',
  'GU18W220901234',
]);

/** Minimum confidence we accept from VLM serial extraction */
const VLM_CONFIDENCE_FLOOR = 0.65;

/**
 * Returns true if the serial is a known prompt example (hallucination).
 */
function isPromptExampleSerial(serial: string | null): boolean {
  if (!serial) return false;
  const s = serial.trim().toUpperCase().replace(/[\s-]/g, '');
  if (PROMPT_EXAMPLE_SERIALS.has(s)) {
    logger.warn(`Rejected prompt-example hallucination: ${serial}`);
    return true;
  }
  return false;
}

/**
 * Validate UPS/Gizzu serial format
 * - Must start with GU18W
 * - Must be 13-15 characters
 * - Must not be a prompt example (hallucination guard)
 */
function isValidUpsSerial(serial: string | null): boolean {
  if (!serial) return false;
  const s = serial.trim().toUpperCase();

  // Hallucination guard — reject prompt examples
  if (isPromptExampleSerial(s)) return false;

  // Must start with GU18W (Gizzu UPS pattern)
  if (!s.startsWith('GU18W')) {
    logger.debug(`Rejected non-GU18W UPS serial: ${serial}`);
    return false;
  }

  // Should be 13-15 chars
  if (s.length < 12 || s.length > 16) {
    logger.debug(`Rejected UPS serial with wrong length (${s.length}): ${serial}`);
    return false;
  }

  return true;
}

/**
 * Extract ONT and UPS serials from a WhatsApp photo
 * WA photos typically show a sticker with both serials clearly visible
 *
 * @param photoUrl - URL or local path to the WA photo
 * @returns Extraction result with both serials
 */
export async function extractSerialsFromWaPhoto(photoUrl: string): Promise<WaPhotoExtractionResult> {
  const startTime = Date.now();
  logger.info(`Extracting serials from WA photo: ${photoUrl}`);

  try {
    let base64 = await fetchPhotoAsBase64(photoUrl);

    // Preprocess image (blur detection + optimization)
    const preprocessed = await preprocessForVlm(base64, 'WA photo serial');
    base64 = preprocessed.base64;

    // Try barcode extraction first for ONT (faster, more reliable)
    let ontFromBarcode: string | null = null;
    if (ENABLE_BARCODE_EXTRACTION) {
      try {
        const barcodeResult = await extractOntSerialFromBarcode(base64);
        if (barcodeResult.success && barcodeResult.serial) {
          logger.info(`WA photo barcode scan: ${barcodeResult.serial}`);
          ontFromBarcode = barcodeResult.serial;
        }
      } catch (barcodeError) {
        logger.warn(`WA photo barcode scan failed: ${barcodeError}`);
      }
    }

    // Call VLM for both serials (or just UPS if barcode got ONT)
    const result = await callVlmExtraction<{
      ontSerial: {
        found: boolean;
        serial: string | null;
        confidence: number;
      };
      upsSerial: {
        found: boolean;
        serial: string | null;
        confidence: number;
      };
    }>(base64, WA_PHOTO_SERIAL_PROMPT, 'WA photo serial extraction');

    const processingTimeMs = Date.now() - startTime;

    if (!result.success || !result.data) {
      return {
        success: false,
        ontSerial: ontFromBarcode,
        upsSerial: null,
        confidence: ontFromBarcode ? 0.95 : 0,
        ontConfidence: ontFromBarcode ? 0.95 : 0,
        upsConfidence: 0,
        processingTimeMs,
        error: result.error || 'VLM extraction failed',
      };
    }

    const { ontSerial: ontResult, upsSerial: upsResult } = result.data;

    // Use barcode ONT if available (higher reliability), otherwise VLM
    let finalOnt: string | null = null;
    let ontConfidence = 0;
    if (ontFromBarcode) {
      finalOnt = ontFromBarcode;
      ontConfidence = 0.98; // Barcode is highly reliable
    } else if (ontResult.found && ontResult.serial) {
      if (ontResult.confidence < VLM_CONFIDENCE_FLOOR) {
        logger.warn(`WA photo ONT below confidence floor (${ontResult.confidence.toFixed(2)} < ${VLM_CONFIDENCE_FLOOR}): ${ontResult.serial}`);
      } else {
        const normalized = normalizeSerial(ontResult.serial);
        if (isValidOntSerial(normalized)) {
          finalOnt = normalized;
          ontConfidence = ontResult.confidence;
        } else {
          logger.warn(`WA photo VLM returned invalid ONT: ${ontResult.serial}`);
        }
      }
    }

    // Validate UPS serial
    let finalUps: string | null = null;
    let upsConfidence = 0;
    if (upsResult.found && upsResult.serial) {
      if (upsResult.confidence < VLM_CONFIDENCE_FLOOR) {
        logger.warn(`WA photo UPS below confidence floor (${upsResult.confidence.toFixed(2)} < ${VLM_CONFIDENCE_FLOOR}): ${upsResult.serial}`);
      } else {
        const normalized = upsResult.serial.trim().toUpperCase().replace(/[\s-]/g, '');
        if (isValidUpsSerial(normalized)) {
          finalUps = normalized;
          upsConfidence = upsResult.confidence;
        } else {
          logger.warn(`WA photo VLM returned invalid UPS: ${upsResult.serial}`);
        }
      }
    }

    // Calculate overall confidence
    const overallConfidence = Math.max(ontConfidence, upsConfidence);
    const success = !!finalOnt || !!finalUps;

    logger.info(`WA photo extraction: ONT=${finalOnt || 'none'} (${ontConfidence.toFixed(2)}), UPS=${finalUps || 'none'} (${upsConfidence.toFixed(2)})`);

    return {
      success,
      ontSerial: finalOnt,
      upsSerial: finalUps,
      confidence: overallConfidence,
      ontConfidence,
      upsConfidence,
      processingTimeMs,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    log.error(`WA photo extraction failed: ${message}`, undefined, 'VlmExtraction');

    return {
      success: false,
      ontSerial: null,
      upsSerial: null,
      confidence: 0,
      ontConfidence: 0,
      upsConfidence: 0,
      processingTimeMs: Date.now() - startTime,
      error: message,
    };
  }
}

/**
 * Fleet VLM (Vision Language Model) Service
 * Extracts data from vehicle check-in photos using Qwen3-VL-8B-Instruct
 *
 * Features:
 * - Odometer OCR extraction
 * - License plate verification
 * - Fuel gauge level reading
 */

import { log } from '@/lib/logger';
import sharp from 'sharp';
import { neon } from '@/lib/db-neon';
import {
  OdometerExtractionResult,
  LicensePlateExtractionResult,
  FuelGaugeExtractionResult,
  FuelReceiptExtractionResult,
  LicenseDiskExtractionResult,
  VlmAnalysisType,
} from '../types/check-in.types';
import {
  getVlmFewShotExamples,
  buildVlmFewShotPrompt,
  recordCorrectExtraction,
} from '@/services/vlmLearningService';

// Database connection for calibration queries
const sql = neon(process.env.DATABASE_URL!);

// VLM API configuration
const VLM_API_BASE = process.env.VLM_API_URL || 'http://100.96.203.105:8100';
const VLM_API_ENDPOINT = `${VLM_API_BASE}/v1/chat/completions`;
const VLM_MODEL = process.env.FLEET_VLM_MODEL || 'Qwen/Qwen3-VL-8B-Instruct';
const VLM_TIMEOUT_MS = 60000; // 1 minute for single image

// Image size limits for VLM processing
// Large images (4K+) cause token limit errors and incorrect readings
const VLM_MAX_WIDTH = 1280;
const VLM_MAX_HEIGHT = 960;
const VLM_JPEG_QUALITY = 85;

// ============================================================================
// Calibration Data Types
// ============================================================================

export interface VehicleCalibration {
  id: string;
  vehicleId: string;
  calibratedAt: string;
  calibratedByName: string | null;
  baselineOdometer: number;
  baselineFuelLevel: number;
  dashboardPhotoUrl: string | null;
  vlmLearningStatus: 'pending' | 'learning' | 'ready';
}

/**
 * Resize image to fit within VLM limits
 * CRITICAL: 4K images (4032x3024) cause VLM to misread odometer/fuel readings
 * Resizing to ~1280x960 fixes accuracy issues
 */
async function resizeImageForVlm(base64Image: string): Promise<string> {
  try {
    const inputBuffer = Buffer.from(base64Image, 'base64');

    // Get image metadata to check if resizing is needed
    const metadata = await sharp(inputBuffer).metadata();
    const width = metadata.width || 0;
    const height = metadata.height || 0;
    const format = metadata.format || 'unknown';

    const needsResize = width > VLM_MAX_WIDTH || height > VLM_MAX_HEIGHT;
    const needsConvert = format !== 'jpeg' && format !== 'jpg';

    if (!needsResize && !needsConvert) {
      log.info('FleetVlmService', `Image ${width}x${height} JPEG already within limits, skipping`);
      return base64Image;
    }

    log.info('FleetVlmService', `Processing image ${width}x${height} ${format} (resize: ${needsResize}, convert: ${needsConvert})`);

    let pipeline = sharp(inputBuffer);
    if (needsResize) {
      pipeline = pipeline.resize(VLM_MAX_WIDTH, VLM_MAX_HEIGHT, {
        fit: 'inside',
        withoutEnlargement: true,
      });
    }
    const outputBuffer = await pipeline.jpeg({ quality: VLM_JPEG_QUALITY }).toBuffer();

    const outputBase64 = outputBuffer.toString('base64');

    const originalSize = Math.round(inputBuffer.length / 1024);
    const outputSize = Math.round(outputBuffer.length / 1024);
    log.info('FleetVlmService', `Image processed: ${originalSize}KB -> ${outputSize}KB (${format} -> jpeg)`);

    return outputBase64;
  } catch (error) {
    log.error('FleetVlmService', `Image processing failed: ${error}`);
    throw new FleetVlmError(
      `Failed to process image for VLM: ${error instanceof Error ? error.message : 'Unknown error'}`,
      'IMAGE_PROCESSING_ERROR',
      error
    );
  }
}

/**
 * VLM API Error
 */
export class FleetVlmError extends Error {
  constructor(
    message: string,
    public readonly code?: string,
    public readonly details?: unknown
  ) {
    super(message);
    this.name = 'FleetVlmError';
  }
}

