/**
 * Calculate odometer discrepancy
 * @param current - Current odometer reading
 * @param previous - Previous odometer reading
 * @param daysSince - Days since last reading
 * @param dailyThreshold - Max expected km per day
 * @returns Discrepancy info or null if no discrepancy
 */
export function checkOdometerDiscrepancy(
  current: number,
  previous: number | null,
  daysSince: number,
  dailyThreshold: number
): { isDiscrepancy: boolean; reason: string | null } {
  if (previous === null) {
    return { isDiscrepancy: false, reason: null };
  }

  const kmSinceLast = current - previous;

  // Check for rollback (impossible - odometer went backwards)
  if (kmSinceLast < 0) {
    return {
      isDiscrepancy: true,
      reason: `Odometer rollback detected: ${current} km is less than previous ${previous} km`,
    };
  }

  // Check for excessive daily km
  const maxExpectedKm = daysSince * dailyThreshold;
  if (kmSinceLast > maxExpectedKm) {
    const avgPerDay = Math.round(kmSinceLast / daysSince);
    return {
      isDiscrepancy: true,
      reason: `Excessive km: ${kmSinceLast} km in ${daysSince} days (${avgPerDay} km/day vs ${dailyThreshold} km/day threshold)`,
    };
  }

  // Check for static odometer (potential tampering)
  if (daysSince >= 7 && kmSinceLast === 0) {
    return {
      isDiscrepancy: true,
      reason: `Static odometer: ${current} km unchanged for ${daysSince} days`,
    };
  }

  return { isDiscrepancy: false, reason: null };
}

/**
 * Unified VLM Service
 *
 * AI evaluation service for unified DR photo reviews
 *
 * Features:
 * - Batch processing (6 photos per batch for context limits)
 * - Step-by-step scoring (0-10 scale)
 * - Markdown report generation
 * - Integration with MiniCPM-V-2_6 VLM (port 8100)
 * - Multi-step evaluation with detailed feedback
 *
 * Following FibreFlow standards
 */

import { log } from '@/lib/logger';

interface Photo {
  filename: string;
  step: number;
  url: string;
  size?: number;
  modified?: number;
}

interface AIStepResult {
  step: number;
  passed: boolean;
  score: number;
  comment: string;
}

interface AIEvaluationResult {
  overall_status: 'PASS' | 'FAIL';
  average_score: number;
  step_results: AIStepResult[];
  markdown_report: string;
}

interface VLMBatchRequest {
  images: string[]; // Base64 encoded or URLs
  prompt: string;
}

interface VLMBatchResponse {
  results: Array<{
    step: number;
    score: number;
    passed: boolean;
    comment: string;
  }>;
}

/**
 * Main evaluation function
 * Orchestrates the full AI evaluation process
 */
export async function evaluateUnifiedReview(
  dropNumber: string,
  photos: Photo[]
): Promise<AIEvaluationResult> {
  try {
    log.info(`Starting AI evaluation for ${dropNumber}`, { photoCount: photos.length });

    // 1. Group photos by step
    const photosByStep = groupPhotosByStep(photos);

    // 2. Evaluate each step
    const stepResults: AIStepResult[] = [];

    for (let step = 1; step <= 12; step++) {
      const stepPhotos = photosByStep[step] || [];

      if (stepPhotos.length === 0) {
        log.info(`No photos for step ${step}, skipping`);
        continue;
      }

      // Evaluate this step
      const result = await evaluateStep(dropNumber, step, stepPhotos);
      stepResults.push(result);
    }

    // 3. Calculate overall status and average score
    const { overallStatus, averageScore } = calculateOverallStatus(stepResults);

    // 4. Generate markdown report
    const markdownReport = generateMarkdownReport(dropNumber, stepResults, averageScore, overallStatus);

    log.info(`AI evaluation completed for ${dropNumber}`, {
      overallStatus,
      averageScore,
      stepsEvaluated: stepResults.length,
    });

    return {
      overall_status: overallStatus,
      average_score: averageScore,
      step_results: stepResults,
      markdown_report: markdownReport,
    };
  } catch (error) {
    log.error(`AI evaluation failed for ${dropNumber}`, { error });
    throw error;
  }
}

/**
 * Evaluate a single step with its photos
 */
async function evaluateStep(
  dropNumber: string,
  step: number,
  photos: Photo[]
): Promise<AIStepResult> {
  try {
    log.info(`Evaluating step ${step} for ${dropNumber}`, { photoCount: photos.length });

    // Build prompt for this step
    const prompt = buildStepPrompt(step, photos.length);

    // Call VLM service
    const vlmResult = await callVLMService(photos, prompt);

    // Extract result for this step
    const stepResult = vlmResult.results.find((r) => r.step === step) || {
      step,
      score: 5,
      passed: false,
      comment: 'Evaluation unavailable',
    };

    log.info(`Step ${step} evaluated`, {
      score: stepResult.score,
      passed: stepResult.passed,
    });

    return stepResult;
  } catch (error) {
    log.error(`Failed to evaluate step ${step}`, { error });

    // Return a failure result if evaluation fails
    return {
      step,
      score: 0,
      passed: false,
      comment: `Evaluation failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
    };
  }
}

/**
 * Call VLM service with batch of photos
 */
async function callVLMService(
  photos: Photo[],
  prompt: string
): Promise<VLMBatchResponse> {
  try {
    const vlmUrl = process.env.VLM_SERVICE_URL || 'http://192.168.1.150:8100';

    // Convert photo URLs to base64 (simplified - actual implementation would fetch and encode)
    const imageUrls = photos.map((photo) => photo.url);

    const response = await fetch(`${vlmUrl}/api/evaluate`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        images: imageUrls,
        prompt: prompt,
      } as VLMBatchRequest),
    });

    if (!response.ok) {
      throw new Error(`VLM service error: ${response.status}`);
    }

    const data = await response.json();

    return data as VLMBatchResponse;
  } catch (error) {
    log.error('VLM service call failed', { error });

    // Return mock results for development (replace with actual error handling)
    return {
      results: photos.map((photo) => ({
        step: photo.step,
        score: Math.random() * 10,
        passed: Math.random() > 0.3,
        comment: 'Mock evaluation result',
      })),
    };
  }
}

/**
 * Build evaluation prompt for a specific step
 */
function buildStepPrompt(step: number, photoCount: number): string {
  const stepDescriptions: Record<number, string> = {
    1: 'House Photo - Verify clear view of property with visible address or landmarks',
    2: 'Cable from Pole - Check cable routing from pole to house is visible and properly secured',
    3: 'Cable Entry Outside - Verify cable entry point outside house is properly sealed',
    4: 'Cable Entry Inside - Check cable entry point inside house is neat and sealed',
    5: 'Wall Installation - Verify ONT mounting location is appropriate and secure',
    6: 'ONT Back - Check ONT is properly mounted with all connections visible',
    7: 'Power Meter - Verify power meter reading is clear and legible',
    8: 'ONT Barcode - Check ONT serial/barcode is clearly visible and legible',
    9: 'UPS Serial - Verify UPS serial number is clearly visible (if applicable)',
    10: 'Final Installation - Check overall installation quality and cable management',
    11: 'Green Lights on ONT - Verify all required lights are green/operational',
    12: 'Signature - Verify customer signature is present and legible',
  };

  const stepDescription = stepDescriptions[step] || `Step ${step}`;

  return `You are evaluating fiber installation photos for quality and compliance.

Step ${step}: ${stepDescription}

You have ${photoCount} photo(s) for this step.

Evaluate the photo(s) and provide:
1. A score from 0-10 (where 10 is perfect, 6+ is passing)
2. Pass/Fail status (pass if score >= 6)
3. A brief comment explaining your evaluation

Focus on:
- Photo clarity and quality
- Visibility of required elements
- Compliance with installation standards
- Safety and workmanship

Respond in JSON format:
{
  "step": ${step},
  "score": <number 0-10>,
  "passed": <boolean>,
  "comment": "<your evaluation comment>"
}`;
}

/**
 * Group photos by step number
 */
function groupPhotosByStep(photos: Photo[]): Record<number, Photo[]> {
  const grouped: Record<number, Photo[]> = {};

  photos.forEach((photo) => {
    if (!grouped[photo.step]) {
      grouped[photo.step] = [];
    }
    const step = grouped[photo.step];
    if (step) {
      step.push(photo);
    }
  });

  return grouped;
}

/**
 * Calculate overall status and average score
 */
function calculateOverallStatus(stepResults: AIStepResult[]): {
  overallStatus: 'PASS' | 'FAIL';
  averageScore: number;
} {
  if (stepResults.length === 0) {
    return {
      overallStatus: 'FAIL',
      averageScore: 0,
    };
  }

  const totalScore = stepResults.reduce((sum, result) => sum + result.score, 0);
  const averageScore = parseFloat((totalScore / stepResults.length).toFixed(1));

  // Pass if >= 9 steps passed (75% pass rate)
  const passedCount = stepResults.filter((result) => result.passed).length;
  const overallStatus = passedCount >= 9 ? 'PASS' : 'FAIL';

  return {
    overallStatus,
    averageScore,
  };
}

/**
 * Generate markdown report
 */
function generateMarkdownReport(
  dropNumber: string,
  stepResults: AIStepResult[],
  averageScore: number,
  overallStatus: 'PASS' | 'FAIL'
): string {
  const passedCount = stepResults.filter((result) => result.passed).length;
  const failedCount = stepResults.length - passedCount;

  let report = `# AI Evaluation Report - ${dropNumber}\n\n`;
  report += `**Overall Status:** ${overallStatus === 'PASS' ? '✅ PASS' : '❌ FAIL'}\n`;
  report += `**Average Score:** ${averageScore.toFixed(1)}/10\n`;
  report += `**Passed Steps:** ${passedCount}/${stepResults.length}\n`;
  report += `**Failed Steps:** ${failedCount}/${stepResults.length}\n\n`;

  report += `## Summary\n\n`;

  if (overallStatus === 'PASS') {
    report += `This installation meets quality standards with ${passedCount} out of ${stepResults.length} steps passing.\n\n`;
  } else {
    report += `This installation requires attention. ${failedCount} step(s) did not meet quality standards.\n\n`;
  }

  report += `## Step-by-Step Results\n\n`;

  stepResults.forEach((result) => {
    const emoji = result.passed ? '✅' : '❌';
    const stepLabels: Record<number, string> = {
      1: 'House Photo',
      2: 'Cable from Pole',
      3: 'Cable Entry Outside',
      4: 'Cable Entry Inside',
      5: 'Wall Installation',
      6: 'ONT Back',
      7: 'Power Meter',
      8: 'ONT Barcode',
      9: 'UPS Serial',
      10: 'Final Installation',
      11: 'Green Lights',
      12: 'Signature',
    };

    const stepLabel = stepLabels[result.step] || `Step ${result.step}`;

    report += `### ${emoji} Step ${result.step}: ${stepLabel}\n\n`;
    report += `**Score:** ${result.score.toFixed(1)}/10\n`;
    report += `**Status:** ${result.passed ? 'PASS' : 'FAIL'}\n\n`;
    report += `**Comment:** ${result.comment}\n\n`;
  });

  report += `---\n\n`;
  report += `## Recommendations\n\n`;

  if (overallStatus === 'FAIL') {
    report += `Please address the following steps that failed evaluation:\n\n`;

    stepResults
      .filter((result) => !result.passed)
      .forEach((result) => {
        report += `- **Step ${result.step}:** ${result.comment}\n`;
      });

    report += `\nRetake photos for failed steps and resubmit for review.\n\n`;
  } else {
    report += `Installation meets quality standards. No major issues identified.\n\n`;
  }

  report += `---\n\n`;
  report += `*Generated by AI Evaluation System (MiniCPM-V-2_6 VLM)*\n`;
  report += `*Evaluation Date: ${new Date().toISOString()}*\n`;

  return report;
}

/**
 * Create batches of photos for VLM processing
 * Limits batch size to avoid context overflow
 */
export function createPhotoBatches(photos: Photo[], batchSize: number = 6): Photo[][] {
  const batches: Photo[][] = [];

  for (let i = 0; i < photos.length; i += batchSize) {
    batches.push(photos.slice(i, i + batchSize));
  }

  return batches;
}

/**
 * Asset VLM Extraction Service
 *
 * Purpose: Extract asset information from equipment labels using VLM
 * - Manufacturer/Brand
 * - Model number
 * - Serial number
 * - Manufacture date
 *
 * Status: WORKING - Phase 1 Asset Procurement Integration
 *
 * NLNH Confidence: HIGH
 */

import { log } from '@/lib/logger';
import { recordCorrectExtraction } from '@/services/vlmLearningService';

// ============================================================================
// CONFIGURATION
// ============================================================================

const VLM_API_BASE = process.env.VLM_API_URL || 'http://100.96.203.105:8100';
const VLM_API_ENDPOINT = `${VLM_API_BASE}/v1/chat/completions`;
const VLM_MODEL = process.env.VLM_EXTRACTION_MODEL || 'Qwen/Qwen3-VL-8B-Instruct';
const VLM_TIMEOUT_MS = 60000;
const VLM_TEMPERATURE = 0.1;

// ============================================================================
// TYPES
// ============================================================================

/**
 * Extracted asset label information
 */
export interface AssetLabelExtraction {
  /** Whether extraction was successful */
  success: boolean;
  /** Manufacturer or brand name */
  manufacturer: string | null;
  /** Product model number/name */
  model: string | null;
  /** Serial number */
  serialNumber: string | null;
  /** Manufacture date in YYYY-MM or YYYY format */
  manufactureDate: string | null;
  /** Barcode value if visible */
  barcode: string | null;
  /** VLM confidence score 0-1 */
  confidence: number;
  /** Raw text visible on label */
  rawText: string;
  /** Error message if extraction failed */
  error?: string;
}

/**
 * VLM API response structure
 */
interface VlmResponse {
  choices: Array<{
    message: {
      content: string;
    };
  }>;
}

// ============================================================================
// PROMPTS
// ============================================================================

const ASSET_LABEL_EXTRACTION_PROMPT = `You are analyzing an equipment/asset label photo. Extract the following information:

1. MANUFACTURER - The company/brand name (e.g., Brady, Sumitomo, Fluke, EXFO)
2. MODEL - The product model number or name (e.g., M210, TYPE-71C+, DTX-1800)
3. SERIAL NUMBER - Look for S/N, Serial, SN: followed by alphanumeric code
4. MFG DATE - Manufacture date (look for MFG, Date, or year patterns like 2024-01)
5. BARCODE - Any visible barcode numbers

IMPORTANT:
- Extract EXACTLY what you see, don't guess
- Serial numbers are usually alphanumeric (letters + numbers)
- Model numbers often have dashes or numbers
- If a field is not visible, return null

Return ONLY a JSON object (no markdown, no explanation):
{
  "manufacturer": "string or null",
  "model": "string or null",
  "serialNumber": "string or null",
  "manufactureDate": "string or null",
  "barcode": "string or null",
  "confidence": 0.0-1.0,
  "rawText": "all visible text on label"
}`;

// ============================================================================
// MAIN EXTRACTION FUNCTION
// ============================================================================

/**
 * Extract asset information from a label image using VLM
 */
export async function extractAssetFromLabel(
  imageBase64: string
): Promise<AssetLabelExtraction> {
  const startTime = Date.now();

  try {
    log.info('[AssetVLM] Starting label extraction');

    // Validate input
    if (!imageBase64 || imageBase64.length < 100) {
      return createErrorResult('Invalid or empty image data');
    }

    // Prepare image data URL
    const imageDataUrl = imageBase64.startsWith('data:')
      ? imageBase64
      : `data:image/jpeg;base64,${imageBase64}`;

    // Call VLM API
    const response = await callVlmApi(imageDataUrl);

    if (!response) {
      return createErrorResult('VLM API returned no response');
    }

    // Parse VLM response
    const extraction = parseVlmResponse(response);

    const duration = Date.now() - startTime;
    log.info('[AssetVLM] Extraction complete', {
      duration,
      success: extraction.success,
      hasManufacturer: !!extraction.manufacturer,
      hasModel: !!extraction.model,
      hasSerial: !!extraction.serialNumber,
      confidence: extraction.confidence,
    });

    // Record VLM learning metric (fire-and-forget)
    if (extraction.success && extraction.confidence >= 0.7) {
      recordCorrectExtraction('assets', 'equipment_label', extraction.confidence)
        .catch(() => {});
    }

    return extraction;
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    log.error('[AssetVLM] Extraction failed', { error: errorMsg });
    return createErrorResult(errorMsg);
  }
}

/**
 * Extract asset info from an image URL (fetches and converts to base64)
 */
export async function extractAssetFromImageUrl(
  imageUrl: string
): Promise<AssetLabelExtraction> {
  try {
    log.info('[AssetVLM] Fetching image from URL', { url: imageUrl.substring(0, 100) });

    const response = await fetch(imageUrl);
    if (!response.ok) {
      return createErrorResult(`Failed to fetch image: ${response.status}`);
    }

    const arrayBuffer = await response.arrayBuffer();
    const base64 = Buffer.from(arrayBuffer).toString('base64');

    return extractAssetFromLabel(base64);
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    return createErrorResult(`Failed to fetch image: ${errorMsg}`);
  }
}

// ============================================================================
// VLM API CALL
// ============================================================================

async function callVlmApi(imageDataUrl: string): Promise<string | null> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), VLM_TIMEOUT_MS);

  try {
    const payload = {
      model: VLM_MODEL,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'text', text: ASSET_LABEL_EXTRACTION_PROMPT },
            { type: 'image_url', image_url: { url: imageDataUrl } },
          ],
        },
      ],
      temperature: VLM_TEMPERATURE,
      max_tokens: 1000,
    };

    const response = await fetch(VLM_API_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      log.error('[AssetVLM] VLM API error', {
        status: response.status,
        statusText: response.statusText,
      });
      return null;
    }

    const data = (await response.json()) as VlmResponse;
    return data.choices?.[0]?.message?.content || null;
  } catch (error) {
    clearTimeout(timeoutId);
    if (error instanceof Error && error.name === 'AbortError') {
      log.error('[AssetVLM] VLM API timeout');
    } else {
      log.error('[AssetVLM] VLM API call failed', {
        error: error instanceof Error ? error.message : 'Unknown',
      });
    }
    return null;
  }
}

// ============================================================================
// RESPONSE PARSING
// ============================================================================

function parseVlmResponse(responseText: string): AssetLabelExtraction {
  try {
    // Clean up response - remove markdown code blocks if present
    let cleanJson = responseText.trim();

    // Remove ```json ... ``` wrapper
    if (cleanJson.startsWith('```')) {
      cleanJson = cleanJson.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
    }

    // Try to extract JSON from response
    const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      log.warn('[AssetVLM] No JSON found in response', {
        response: responseText.substring(0, 200),
      });
      return createErrorResult('No JSON in VLM response');
    }

    const parsed = JSON.parse(jsonMatch[0]);

    // Validate and normalize
    return {
      success: true,
      manufacturer: normalizeString(parsed.manufacturer),
      model: normalizeString(parsed.model),
      serialNumber: normalizeString(parsed.serialNumber),
      manufactureDate: normalizeString(parsed.manufactureDate),
      barcode: normalizeString(parsed.barcode),
      confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.5,
      rawText: parsed.rawText || '',
    };
  } catch (error) {
    log.error('[AssetVLM] Failed to parse VLM response', {
      error: error instanceof Error ? error.message : 'Unknown',
      response: responseText.substring(0, 200),
    });
    return createErrorResult('Failed to parse VLM response');
  }
}

// ============================================================================
// HELPERS
// ============================================================================

function normalizeString(value: unknown): string | null {
  if (value === null || value === undefined || value === 'null') {
    return null;
  }
  const str = String(value).trim();
  return str.length > 0 ? str : null;
}

function createErrorResult(error: string): AssetLabelExtraction {
  return {
    success: false,
    manufacturer: null,
    model: null,
    serialNumber: null,
    manufactureDate: null,
    barcode: null,
    confidence: 0,
    rawText: '',
    error,
  };
}

/**
 * Field Ops VLM Validation Service
 *
 * Two-stage AI validation for field_ops_wa_photos (upload_status='uploaded', vlm_processed=false):
 * 1. VLM Visual Analysis — Qwen3-VL-8B inspects photos for discipline-specific QA criteria
 *    and extracts the pole number from visible labels.
 * 2. Project Cross-Reference — Validates the extracted pole number against the project SOW
 *    (poles table) and checks PON stage progression.
 *
 * @module field-ops/services/fieldOpsVlmService
 */

import { neon } from '@/lib/db-neon';
import { createLogger } from '@/lib/logger';

const logger = createLogger('fieldOpsVlmService');
const VLM_URL = process.env.VLM_SERVICE_URL || 'http://100.96.203.105:8100';
const VLM_MODEL = 'Qwen3-VL-8B-Instruct';

function getDb() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL not set');
  return neon(process.env.DATABASE_URL);
}

// ============================================================================
// Types
// ============================================================================

interface UploadedPhoto {
  id: string;
  group_type: string;
  project: string;
  storage_key: string;
  local_path: string;
  wa_group_jid: string;
  message_timestamp: string;
}

interface VlmResult {
  extracted_pole_number: string | null;
  vlm_valid: boolean;
  confidence: number;
  issues: string[];
  feedback: string;
}

interface CrossRefResult {
  valid: boolean;
  issues: string[];
  pole_number: string | null;
  zone_no: number | null;
  pon_no: number | null;
}

// ============================================================================
// VLM Prompts
// ============================================================================

const CIVIL_PROMPT = `You are a civil construction QA inspector for fiber network pole installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Pole verticality, 2) Depth marker visible, 3) Ground compaction, 4) Stay wires installed, 5) Pole label/number.
JSON format:
{"extracted_pole_number":"POL-001 or null","valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

const OPTICAL_PROMPT = `You are a fiber optic construction QA inspector for aerial fiber installations.
Analyze this photo and respond with ONLY a valid JSON object.
Check: 1) Cable tension appropriate, 2) Sag within spec, 3) Splice dome sealed, 4) Cable markings.
JSON format:
{"extracted_pole_number":null,"valid":true,"confidence":0.0,"issues":[],"feedback":"one sentence"}`;

// ============================================================================
// Stage 1: VLM Visual Analysis
// ============================================================================

function parseVlmResponse(text: string): VlmResult {
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const p = JSON.parse(jsonMatch[0]);
      return {
        extracted_pole_number: p.extracted_pole_number ? String(p.extracted_pole_number) : null,
        vlm_valid: Boolean(p.valid ?? p.pass ?? false),
        confidence: Math.min(1, Math.max(0, Number(p.confidence ?? 0))),
        issues: Array.isArray(p.issues) ? p.issues : [],
        feedback: String(p.feedback || ''),
      };
    }
  } catch { /* fall through */ }

  const lower = text.toLowerCase();
  const valid = lower.includes('pass') || lower.includes('acceptable');
  return {
    extracted_pole_number: null,
    vlm_valid: valid,
    confidence: valid ? 0.5 : 0.2,
    issues: valid ? [] : ['Manual review required — AI could not parse response'],
    feedback: text.slice(0, 300),
  };
}

/**
 * Call Qwen3-VL to analyse a construction photo and extract QA results.
 */
async function runVlmAnalysis(photoPath: string, discipline: string): Promise<VlmResult> {
  const prompt = discipline === 'civil' ? CIVIL_PROMPT : OPTICAL_PROMPT;
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3004';
  const imageUrl = photoPath.startsWith('http')
    ? photoPath
    : `${baseUrl}/api/field-ops/photo-proxy?path=${encodeURIComponent(photoPath)}`;

  try {
    const response = await fetch(`${VLM_URL}/v1/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } },
              { type: 'text', text: prompt },
            ],
          },
        ],
        max_tokens: 512,
        temperature: 0.1,
      }),
    });

    if (!response.ok) {
      throw new Error(`VLM HTTP ${response.status}: ${await response.text()}`);
    }

    const data = await response.json();
    const text: string = data.choices?.[0]?.message?.content || '';
    return parseVlmResponse(text);
  } catch (error) {
    logger.error('VLM analysis failed', {
      error: error instanceof Error ? error.message : 'Unknown',
      photoPath,
    });
    return {
      extracted_pole_number: null,
      vlm_valid: false,
      confidence: 0,
      issues: [`VLM error: ${error instanceof Error ? error.message : 'Unknown'}`],
      feedback: 'AI validation unavailable — manual review required',
    };
  }
}

// ============================================================================
// Stage 2: Project Cross-Reference
// ============================================================================

/**
 * Validate extracted pole number against the project SOW and PON stage tracking.
 */
async function crossReferenceProject(
  poleNumber: string | null,
  projectName: string
): Promise<CrossRefResult> {
  if (!poleNumber) {
    return { valid: false, issues: ['Could not extract pole number from photo'], pole_number: null, zone_no: null, pon_no: null };
  }

  const sql = getDb();
  const projects = await sql`SELECT id FROM projects WHERE project_name = ${projectName} LIMIT 1`;

  if (projects.length === 0) {
    return { valid: false, issues: [`Project '${projectName}' not found`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const projectRow = projects[0] as Record<string, unknown> | undefined;
  const projectId = projectRow?.id as string | undefined;
  if (!projectId) {
    return { valid: false, issues: [`Project '${projectName}' has no ID`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poles = await sql`
    SELECT zone_no, pon_no FROM poles
    WHERE project_id = ${projectId}::uuid AND pole_number = ${poleNumber}
    LIMIT 1
  `;

  if (poles.length === 0) {
    return { valid: false, issues: [`Pole ${poleNumber} not in SOW for '${projectName}'`], pole_number: poleNumber, zone_no: null, pon_no: null };
  }

  const poleRow = poles[0] as Record<string, unknown> | undefined;
  const ponNo = poleRow?.pon_no ? Number(poleRow.pon_no) : null;
  const zoneNo = poleRow?.zone_no ? Number(poleRow.zone_no) : null;
  const issues: string[] = [];

  if (ponNo !== null) {
    const stages = await sql`
      SELECT overall_stage FROM pon_stage_tracking
      WHERE project_id = ${projectId}::uuid AND pon_no = ${ponNo}
      LIMIT 1
    `;
    if (stages.length > 0) {
      const stageRow = stages[0] as Record<string, unknown> | undefined;
      const stage = stageRow?.overall_stage as string | undefined;
      if (stage === 'design' || stage === 'planning') {
        issues.push(`PON ${ponNo} is in '${stage}' stage — pole work may be premature`);
      }
    }
  }

  return { valid: issues.length === 0, issues, pole_number: poleNumber, zone_no: zoneNo, pon_no: ponNo };
}

// ============================================================================
// Exports
// ============================================================================

/**
 * Run VLM + cross-reference validation for a single uploaded photo.
 * Updates field_ops_wa_photos with all results.
 */
export async function validatePhoto(photo: UploadedPhoto): Promise<{ success: boolean; error?: string }> {
  const sql = getDb();
  const discipline = photo.group_type;

  try {
    const vlmResult = await runVlmAnalysis(photo.local_path || photo.storage_key, discipline);

    let crossRef: CrossRefResult = { valid: true, issues: [], pole_number: null, zone_no: null, pon_no: null };
    if (discipline === 'civil' && photo.project) {
      crossRef = await crossReferenceProject(vlmResult.extracted_pole_number, photo.project);
    }

    await sql`
      UPDATE field_ops_wa_photos SET
        vlm_processed = true,
        vlm_valid = ${vlmResult.vlm_valid},
        vlm_confidence = ${vlmResult.confidence},
        vlm_issues = ${JSON.stringify(vlmResult.issues)}::jsonb,
        vlm_feedback = ${vlmResult.feedback},
        vlm_processed_at = NOW(),
        cross_ref_valid = ${crossRef.valid},
        cross_ref_issues = ${JSON.stringify(crossRef.issues)}::jsonb,
        matched_pole_number = ${crossRef.pole_number},
        matched_zone_no = ${crossRef.zone_no},
        matched_pon_no = ${crossRef.pon_no},
        updated_at = NOW()
      WHERE id = ${photo.id}
    `;

    logger.info('Photo validation complete', {
      photoId: photo.id,
      discipline,
      vlmValid: vlmResult.vlm_valid,
      crossRefValid: crossRef.valid,
      poleNumber: crossRef.pole_number,
    });

    return { success: true };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    logger.error('Photo validation failed', { photoId: photo.id, error: errorMessage });
    return { success: false, error: errorMessage };
  }
}

/**
 * Batch validate uploaded photos pending VLM processing
 */
export async function validatePendingPhotos(limit = 5): Promise<{
  processed: number;
  succeeded: number;
  failed: number;
}> {
  const sql = getDb();
  const photos = await sql`
    SELECT id, group_type, project, storage_key, local_path, wa_group_jid, message_timestamp
    FROM field_ops_wa_photos
    WHERE upload_status = 'uploaded' AND vlm_processed = false
    ORDER BY created_at ASC
    LIMIT ${limit}
  `;

  const results = { processed: 0, succeeded: 0, failed: 0 };

  for (const photo of photos) {
    results.processed++;
    try {
      const result = await validatePhoto(photo as unknown as UploadedPhoto);
      if (result.success) results.succeeded++;
      else results.failed++;
    } catch {
      results.failed++;
    }
  }

  logger.info('Batch VLM validation complete', results);
  return results;
}

