    );

    if (drResult.rows.length === 0) {
      result.error = 'DR not found';
      return result;
    }

    const dr = drResult.rows[0];
    let photos: Array<{ filename: string; url: string; step?: number }> = [];

    try {
      photos = dr.photos ? JSON.parse(dr.photos) : [];
    } catch {
      result.error = 'Failed to parse photos';
      return result;
    }

    if (photos.length === 0) {
      result.error = 'No photos available';
      return result;
    }

    // Step 1: Categorize if not done
    let categorization = dr.categorization ? JSON.parse(dr.categorization) : [];

    if (dr.vlm_categorization_status !== 'categorized' && dr.vlm_categorization_status !== 'approved') {
      log.info('ProcessVlmQueue', `Categorizing photos for ${dropNumber}`);

      // Prepare photos for categorization - pass URLs, categorizePhotos will fetch them
      const photoInputs: PhotoInput[] = photos.map((photo) => ({
        filename: photo.filename,
        url: `${ONEMAP_HOST}/api/photo/${dropNumber}/${photo.filename}`,
        original_type: null,
        original_step: photo.step ?? null,
      }));

      if (photoInputs.length > 0) {
        // Run VLM categorization
        const catResult = await categorizePhotos(dropNumber, photoInputs);

        // Store the full VlmCategorizationResult objects (use correct property names!)
        categorization = catResult;

        // Save categorization results with proper timestamp
        await pool.query(
          `UPDATE dr_photo_unified_reviews
           SET vlm_categorization_status = 'categorized',
               vlm_categorization_results = $1,
               vlm_categorized_at = NOW(),
               updated_at = NOW()
           WHERE drop_number = $2`,
          [JSON.stringify(categorization), dropNumber]
        );

        result.categorized = true;
        log.info('ProcessVlmQueue', `Categorized ${photoInputs.length} photos for ${dropNumber}`);
      }
    } else {
      result.categorized = true;
    }

    // Step 2: Extract data from Step 6, 7, 9 photos
    // Find photos for each step
    const photosWithSteps = photos.map((p) => {
      const cat = categorization.find(
        (c: { photo_filename: string; vlm_predicted_step?: number; human_override_step?: number }) =>
          c.photo_filename === p.filename
      );
      return {
        ...p,
        step: cat?.human_override_step ?? cat?.vlm_predicted_step ?? p.step ?? null,
      };
    });

    // Get ALL photos for each step - VLM will try each to find best result
    const step6Photos = photosWithSteps.filter((p) => p.step === 6);
    const step7Photos = photosWithSteps.filter((p) => p.step === 7);
    const step9Photos = photosWithSteps.filter((p) => p.step === 9);

    // Only run extraction if we have at least one of these photos
    if (step6Photos.length > 0 || step7Photos.length > 0 || step9Photos.length > 0) {
      log.info('ProcessVlmQueue', `Extracting data for ${dropNumber}`, {
        step6Count: step6Photos.length,
        step7Count: step7Photos.length,
        step9Count: step9Photos.length,
      });

      const extraction = await runFullExtraction(dropNumber, {
        step6Urls: step6Photos.length > 0 ? step6Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
        step7Urls: step7Photos.length > 0 ? step7Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
        step9Urls: step9Photos.length > 0 ? step9Photos.map(p => `${ONEMAP_HOST}/api/photo/${dropNumber}/${p.filename}`) : undefined,
      });

      // Build validation data
      const validationData: DrValidationData = {
        drNumber: dropNumber,
        photoCount: photos.length,
        photos: photosWithSteps.map((p) => ({ filename: p.filename, step: p.step ?? null })),
        ontSerial: dr.onemap_ont_serial,
        upsSerial: dr.onemap_ups_serial,
        powerMeterDbm: extraction.powerMeter?.value ?? null,
        vlmOntSerialStep6: extraction.ontSerialStep6?.serial ?? null,
        vlmOntSerialStep9: extraction.step9?.ontSerial.serial ?? null,
        vlmDrNumberStep9: extraction.step9?.drNumber.drNumber ?? null,
      };

      const powerMeterResult = validatePowerMeter(validationData.powerMeterDbm);
      const serialResult = validateSerialCrossReference(validationData);

      const serialValidationDetails = JSON.stringify({
        onemapSerial: serialResult.onemapSerial,
        step6Serial: serialResult.step6Serial,
        step9Serial: serialResult.step9Serial,
        step9DrNumber: serialResult.step9DrNumber,
        ontMatch: serialResult.ontMatch,
        drMatch: serialResult.drMatch,
      });

      // Save extraction results directly to unified table (migration 127)
      await pool.query(
        `UPDATE dr_photo_unified_reviews SET
           vlm_power_meter_dbm = $1,
           vlm_power_meter_status = $2,
           vlm_ont_serial_step6 = $3,
           vlm_ont_serial_step9 = $4,
           vlm_dr_number_step9 = $5,
           serial_validation_status = $6,
           serial_validation_details = $7,
           serial_extraction_method_step6 = $8,
           serial_extraction_method_step9 = $9,
           data_validation_completed = true,
           data_validation_completed_at = NOW(),
           qa_phase = 'final_decision',
           onemap_ont_serial = COALESCE($10, onemap_ont_serial),
           onemap_ups_serial = COALESCE($11, onemap_ups_serial),
           overall_status = 'PASS',
           updated_at = NOW()
         WHERE drop_number = $12`,
        [
          extraction.powerMeter?.value ?? null,
          powerMeterResult.status,
          extraction.ontSerialStep6?.serial ?? null,
          extraction.step9?.ontSerial.serial ?? null,
          extraction.step9?.drNumber.drNumber ?? null,
          serialResult.status,
          serialValidationDetails,
          extraction.ontSerialStep6?.extractionMethod ?? 'vlm',
          extraction.step9?.ontSerial.extractionMethod ?? 'vlm',
          dr.onemap_ont_serial ?? null,
          dr.onemap_ups_serial ?? null,
          dropNumber,
        ]
      );

      result.extracted = true;
      result.powerMeter = extraction.powerMeter?.value ?? null;
      result.ontSerial = extraction.ontSerialStep6?.serial ?? extraction.step9?.ontSerial.serial ?? null;
      result.drNumber = extraction.step9?.drNumber.drNumber ?? null;

      log.info('ProcessVlmQueue', `Extraction complete for ${dropNumber}`, {
        powerMeter: result.powerMeter,
        ontSerial: result.ontSerial,
        drNumber: result.drNumber,
      });
    } else {
      // No step 6/7/9 photos found — mark as done so cron doesn't re-process
      log.info('ProcessVlmQueue', `No step 6/7/9 photos for ${dropNumber}, marking extraction complete`);
      await pool.query(
        `UPDATE dr_photo_unified_reviews SET
           data_validation_completed = true,
           data_validation_completed_at = NOW(),
           vlm_power_meter_status = 'no_photo',
           serial_validation_status = 'no_photo',
           qa_phase = 'final_decision',
           overall_status = 'NEEDS_REVIEW',
           updated_at = NOW()
         WHERE drop_number = $1`,
        [dropNumber]
      );
      result.extracted = false;
    }

    result.success = true;
    return result;
  } catch (error) {
    result.error = error instanceof Error ? error.message : 'Unknown error';
    log.error('ProcessVlmQueue', `Error processing ${dropNumber}`, { error: result.error });
    return result;
  }
}

/**
 * Main handler
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<ProcessResponse | { error: string }>
): Promise<void> {
  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', ['GET', 'POST']);
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // Verify cron secret in production
  const authHeader = req.headers.authorization;
  const cronSecret = process.env.CRON_SECRET;

  if (process.env.NODE_ENV === 'production' && cronSecret) {
    if (authHeader !== `Bearer ${cronSecret}`) {
      log.error('ProcessVlmQueue', 'Unauthorized request');
      return res.status(401).json({ error: 'Unauthorized' });
    }
  }

  const limit = Number(req.query.limit) || Number(req.body?.limit) || 20;
  const concurrency = Number(req.query.concurrency) || Number(req.body?.concurrency) || 3;

  log.info('ProcessVlmQueue', `Starting VLM queue processing (limit: ${limit}, concurrency: ${concurrency})`);

  try {
    // Find DRs that need VLM processing:
    // 1. Uncategorized DRs (need full pipeline: categorize + extract)
    // 2. Categorized but not extracted (need extraction only - faster)
    const pendingResult = await pool.query(
      `SELECT drop_number
       FROM dr_photo_unified_reviews
       WHERE photo_count > 0
         AND (
           -- Uncategorized: need full pipeline
           (vlm_categorization_status IS NULL OR vlm_categorization_status = 'pending')
           OR
           -- Categorized but missing extraction data (and not already marked as no-photo)
           (vlm_categorization_status IN ('categorized', 'approved')
            AND vlm_power_meter_dbm IS NULL
            AND vlm_ont_serial_step6 IS NULL
            AND vlm_ont_serial_step9 IS NULL
            AND (data_validation_completed IS NULL OR data_validation_completed = false))
         )
       ORDER BY
         -- Prioritize already-categorized (extraction-only = faster)
         CASE WHEN vlm_categorization_status IN ('categorized', 'approved') THEN 0 ELSE 1 END,
         created_at DESC
       LIMIT $1`,
      [limit]
    );

    const pendingDRs = pendingResult.rows;

    if (pendingDRs.length === 0) {
      log.info('ProcessVlmQueue', 'No DRs need VLM processing');
      return res.status(200).json({
        success: true,
        processed: 0,
        succeeded: 0,
        failed: 0,
        results: [],
        timestamp: new Date().toISOString(),
      });
    }

    log.info('ProcessVlmQueue', `Found ${pendingDRs.length} DRs to process (${concurrency} concurrent)`);

    const results: ProcessResult[] = [];
    let succeeded = 0;
    let failed = 0;

    // Process DRs in parallel batches of `concurrency`
    for (let i = 0; i < pendingDRs.length; i += concurrency) {
      const batch = pendingDRs.slice(i, i + concurrency);
      const batchResults = await Promise.allSettled(
        batch.map((row) => processVlmForDr(row.drop_number))
      );

      for (const settled of batchResults) {
        if (settled.status === 'fulfilled') {
          results.push(settled.value);
          if (settled.value.success) succeeded++;
          else failed++;
        } else {
          failed++;
          results.push({
            dropNumber: 'unknown',
            success: false,
            categorized: false,
            extracted: false,
            powerMeter: null,
            ontSerial: null,
            drNumber: null,
            error: settled.reason?.message || 'Promise rejected',
          });
        }
      }

      // Brief pause between batches to let VLM breathe
      if (i + concurrency < pendingDRs.length) {
        await new Promise((resolve) => setTimeout(resolve, 500));
      }
    }

    log.info('ProcessVlmQueue', `Completed: ${succeeded}/${pendingDRs.length} succeeded`, {
      failed,
    });

    return res.status(200).json({
      success: true,
      processed: pendingDRs.length,
      succeeded,
      failed,
      results,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    const errorStack = error instanceof Error ? error.stack : undefined;
    log.error('ProcessVlmQueue', `Fatal error: ${errorMessage}`, { stack: errorStack });
    return res.status(500).json({
      error: errorMessage || 'Failed to process VLM queue',
    });
  }
}

/**
 * VLM Learning Service
 *
 * Enterprise-wide service for VLM learning using HITL corrections.
 * Provides:
 * - Correction recording across all modules
 * - Few-shot example retrieval for prompt enhancement
 * - Error pattern classification
 * - Metrics recording and aggregation
 *
 * @module services/vlmLearningService
 */

import { neon } from '@/lib/db-neon';
import { log } from '@/lib/logger';
import { createHash } from 'crypto';
import type {
  VlmModule,
  VlmAnalysisType,
  VlmCorrection,
  RecordCorrectionInput,
  FewShotExample,
  GetFewShotOptions,
  VlmMetricsSummary,
  CorrectionReason,
  ErrorPattern,
  ModuleAccuracySummary,
} from '@/types/vlm-learning';

const sql = neon(process.env.DATABASE_URL!);

// ============================================================================
// CORRECTION RECORDING
// ============================================================================

/**
 * Record a VLM correction for learning
 *
 * @param input - Correction details
 * @returns The created correction record
 */
export async function recordVlmCorrection(
  input: RecordCorrectionInput
): Promise<VlmCorrection> {
  const {
    module,
    analysisType,
    sourceId,
    sourceTable,
    photoUrl,
    vlmExtractedValue,
    vlmConfidence,
    vlmModel,
    vlmPromptHash,
    correctedValue,
    correctionReason,
    correctionNotes,
    context,
    correctedByName,
    correctedById,
  } = input;

  // Auto-classify error pattern if not provided
  const errorPattern = classifyErrorPattern(vlmExtractedValue, correctedValue, analysisType);

  try {
    const result = await sql`
      INSERT INTO vlm_corrections (
        module, analysis_type, source_id, source_table, photo_url,
        vlm_extracted_value, vlm_confidence, vlm_model, vlm_prompt_hash,
        corrected_value, correction_reason, error_pattern, correction_notes,
        context_json, reviewed_by, corrected_by_name
      ) VALUES (
        ${module}, ${analysisType}, ${sourceId || null}, ${sourceTable || null}, ${photoUrl || null},
        ${vlmExtractedValue}, ${vlmConfidence || null}, ${vlmModel || null}, ${vlmPromptHash || null},
        ${correctedValue}, ${correctionReason || null}, ${errorPattern}, ${correctionNotes || null},
        ${JSON.stringify(context || {})}, ${correctedById || null}, ${correctedByName || null}
      )
      RETURNING *
    `;

    const row = result[0];
    log.info(`Recorded correction: ${module}/${analysisType} - "${vlmExtractedValue}" → "${correctedValue}"`);

    // Record metric for the correction
    await recordExtractionMetric({
      module,
      analysisType,
      wasCorrect: false,
      wasCorrected: true,
      errorPattern: errorPattern || undefined,
    });

    return mapCorrectionRow(row as Record<string, unknown>);
  } catch (error) {
    log.error(`Failed to record correction: ${error}`);
    throw error;
  }
}

/**
 * Mark a correction as canonical (high-quality example)
 */
export async function markAsCanonical(
  correctionId: string,
  isCanonical: boolean,
  priority?: number
): Promise<void> {
  try {
    await sql`
      UPDATE vlm_corrections
      SET is_canonical = ${isCanonical}, priority = COALESCE(${priority}, priority)
      WHERE id = ${correctionId}
    `;
    log.info(`Updated correction ${correctionId} canonical=${isCanonical}`);
  } catch (error) {
    log.error(`Failed to update canonical status: ${error}`);
    throw error;
  }
}

// ============================================================================
// FEW-SHOT RETRIEVAL
// ============================================================================

/**
 * Get few-shot examples for prompt enhancement
 *
 * Retrieves relevant correction examples to inject into VLM prompts.
 * Prioritizes canonical examples and matches by context when available.
 *
 * @param options - Retrieval options
 * @returns Array of few-shot examples
 */
export async function getVlmFewShotExamples(
  options: GetFewShotOptions
): Promise<FewShotExample[]> {
  const {
    module,
    analysisType,
    context,
    maxExamples = 3,
    prioritizeCanonical = true,
    includePhotos = false,
  } = options;

  try {
    // Query: prioritize canonical, then recent, with context matching
    const rows = await sql`
      SELECT
        vlm_extracted_value,
        corrected_value,
        correction_notes,
        error_pattern,
        context_json,
        photo_url,
        is_canonical,
        priority
      FROM vlm_corrections
      WHERE module = ${module}
        AND analysis_type = ${analysisType}
        AND corrected_value IS NOT NULL
      ORDER BY
        is_canonical DESC,
        priority DESC,
        created_at DESC
      LIMIT ${maxExamples * 2}
    `;

    // If we have context, score by similarity
    let examples = rows.map((row) => ({
      incorrect: row.vlm_extracted_value,
      correct: row.corrected_value,
      context: row.correction_notes || undefined,
      errorPattern: row.error_pattern as ErrorPattern | undefined,
      photoUrl: includePhotos ? row.photo_url : undefined,
      isCanonical: row.is_canonical,
      priority: row.priority || 0,
      contextJson: row.context_json || {},
    }));

    // Score by context similarity if context provided
    if (context && Object.keys(context).length > 0) {
      examples = examples.map((ex) => ({
        ...ex,
        _score: calculateContextSimilarity(ex.contextJson, context),
      }));
      examples.sort((a, b) => {
        // Canonical first, then by score, then by priority
        if (a.isCanonical !== b.isCanonical) return a.isCanonical ? -1 : 1;
        const aScore = (a as { _score?: number })._score || 0;
        const bScore = (b as { _score?: number })._score || 0;
        if (aScore !== bScore) return bScore - aScore;
        return b.priority - a.priority;
      });
    }

    // Take top N examples
    const result: FewShotExample[] = examples.slice(0, maxExamples).map((ex) => ({
      incorrect: ex.incorrect,
      correct: ex.correct,
      context: ex.context,
      errorPattern: ex.errorPattern,
      photoUrl: ex.photoUrl,
    }));

    log.info(`Retrieved ${result.length} few-shot examples for ${module}/${analysisType}`);
    return result;
  } catch (error) {
    log.error(`Failed to get few-shot examples: ${error}`);
    return [];
  }
}

/**
 * Build a few-shot prompt section from examples
 *
 * @param examples - Few-shot examples
 * @param format - Output format
 * @returns Formatted prompt section
 */
export function buildVlmFewShotPrompt(
  examples: FewShotExample[],
  format: 'markdown' | 'json' = 'markdown'
): string {
  if (examples.length === 0) return '';

  if (format === 'json') {
    return JSON.stringify(
      {
        correction_examples: examples.map((ex) => ({
          incorrect: ex.incorrect,
          correct: ex.correct,
          note: ex.context,
        })),
      },
      null,
      2
    );
  }

  // Markdown format
  const lines = ['### CORRECTION EXAMPLES (Learn from past mistakes):', ''];

  for (const ex of examples) {
    if (ex.incorrect) {
      lines.push(`❌ WRONG: "${ex.incorrect}"`);
    }
    lines.push(`✅ CORRECT: "${ex.correct}"`);
    if (ex.context) {
      lines.push(`   Note: ${ex.context}`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Calculate similarity between two context objects
 */
function calculateContextSimilarity(
  storedContext: Record<string, unknown>,
  queryContext: Record<string, unknown>
): number {
  if (!storedContext || !queryContext) return 0;

  const storedKeys = Object.keys(storedContext);
  const queryKeys = Object.keys(queryContext);

  if (storedKeys.length === 0 || queryKeys.length === 0) return 0;

  let matches = 0;
  let total = 0;

  for (const key of queryKeys) {
    if (key in storedContext) {
      total++;
      if (storedContext[key] === queryContext[key]) {
        matches++;
      }
    }
  }

  return total > 0 ? matches / total : 0;
}

// ============================================================================
// ERROR CLASSIFICATION
// ============================================================================

/**
 * Classify the error pattern based on VLM vs correct value
 *
 * @param vlmValue - What VLM extracted
 * @param correctValue - The correct value
 * @param analysisType - Type of analysis
 * @returns Classified error pattern or null
 */
export function classifyErrorPattern(
  vlmValue: string | null,
  correctValue: string,
  analysisType: VlmAnalysisType
): ErrorPattern | null {
  if (!vlmValue) return null;

  const vlm = vlmValue.toString().trim();
  const correct = correctValue.toString().trim();

  // Check for ONT serial field confusion
  if (analysisType === 'ont_serial_back' || analysisType === 'ont_serial_front') {
    if (vlm.startsWith('ALHN-')) return 'ssid_not_serial';
    if (vlm.startsWith('STN')) return 'part_number_not_serial';
    if (/^[0-9A-F]{12}$/i.test(vlm)) return 'mac_not_serial';

    // Serial-specific digit confusion (hex chars, not just numeric)
    if (vlm.length !== correct.length) return 'length_mismatch' as ErrorPattern;
    let diffCount = 0;
    const diffs: string[] = [];
    for (let i = 0; i < vlm.length; i++) {
      if (vlm[i] !== correct[i]) {
        diffCount++;
        diffs.push(`${vlm[i]}${correct[i]}`);
      }
    }
    if (diffCount === 1 && diffs[0]) {
      const pair = diffs[0];
      const confusions: Record<string, ErrorPattern> = {
        '17': 'digit_1_7', '71': 'digit_1_7',
        '16': 'digit_1_6', '61': 'digit_1_6',
        '68': 'digit_6_8', '86': 'digit_6_8',
        '80': 'digit_8_0', '08': 'digit_8_0',
        '94': 'digit_9_4', '49': 'digit_9_4',
        '23': 'digit_2_3', '32': 'digit_2_3',
      };
      return confusions[pair] || `single_char_${diffCount}` as ErrorPattern;
    }
    if (diffCount <= 3) return `multi_char_${diffCount}` as ErrorPattern;
    return 'totally_wrong' as ErrorPattern;
  }

  // Check for CQA step mis-assignment
  if (analysisType === 'construction_photo_qa') {
    const vlmStep = parseInt(vlm.charAt(0));
    const correctStep = parseInt(correct.charAt(0));
    if (!isNaN(vlmStep) && !isNaN(correctStep)) {
      if (vlmStep === 0) return 'step_classified_unrelated' as ErrorPattern;
      if (vlmStep === 2 && correctStep !== 2) return 'step_2_overassigned' as ErrorPattern;
      return `step_${vlmStep}_to_${correctStep}` as ErrorPattern;
    }
    return 'step_misassignment' as ErrorPattern;
  }

  // Check for odometer digit confusion
  if (analysisType === 'odometer') {
    const pattern = detectDigitConfusionPattern(vlm, correct);
    if (pattern) return pattern;

    // Check for trip meter vs odometer
    if (vlm.length < correct.length - 1) return 'trip_not_odometer';
  }

  // Check for fuel gauge reversed
  if (analysisType === 'fuel_gauge') {
    const vlmNum = parseFloat(vlm);
    const correctNum = parseFloat(correct);
    if (!isNaN(vlmNum) && !isNaN(correctNum)) {
      // If difference is roughly 100 - x, gauge might be read backwards
      if (Math.abs(vlmNum + correctNum - 100) < 10) return 'gauge_reversed';
    }
  }

  // Check for decimal issues
  if (vlm.includes('.') !== correct.includes('.')) {
    return vlm.includes('.') ? 'extra_decimal' : 'missed_decimal';
  }

  return null;
}

/**
 * Detect digit confusion patterns between two number strings
 */
function detectDigitConfusionPattern(vlm: string, correct: string): ErrorPattern | null {
  // Must be same length for digit confusion
  if (vlm.length !== correct.length) return null;

  // Only consider numeric strings
  if (!/^\d+$/.test(vlm) || !/^\d+$/.test(correct)) return null;

  const confusionPairs: Record<string, ErrorPattern> = {
    '16': 'digit_1_6',
    '61': 'digit_1_6',
    '17': 'digit_1_7',
    '71': 'digit_1_7',
    '23': 'digit_2_3',
    '32': 'digit_2_3',
    '68': 'digit_6_8',
    '86': 'digit_6_8',
    '80': 'digit_8_0',
    '08': 'digit_8_0',
    '94': 'digit_9_4',
    '49': 'digit_9_4',
  };

  for (let i = 0; i < vlm.length; i++) {
    const vlmChar = vlm[i];
    const correctChar = correct[i];
    if (vlmChar && correctChar && vlmChar !== correctChar) {
      const pair = vlmChar + correctChar;
      if (confusionPairs[pair]) {
        return confusionPairs[pair];
      }
    }
  }

  return null;
}

// ============================================================================
// METRICS RECORDING
// ============================================================================

interface RecordMetricInput {
  module: VlmModule;
  analysisType: VlmAnalysisType;
  wasCorrect: boolean;
  wasCorrected?: boolean;
  confidence?: number;
  errorPattern?: ErrorPattern;
}

/**
 * Record a VLM extraction metric
 *
 * Upserts into daily metrics table for aggregation.
 */
export async function recordExtractionMetric(input: RecordMetricInput): Promise<void> {
  const { module, analysisType, wasCorrect, wasCorrected, confidence, errorPattern } = input;

  const today = new Date().toISOString().split('T')[0];

  try {
    // Build error count increments
    const digitConfusionInc = errorPattern?.startsWith('digit_') ? 1 : 0;
    const formatErrorInc =
      errorPattern === 'missed_decimal' || errorPattern === 'extra_decimal' ? 1 : 0;
    const partialExtractionInc = 0; // TODO: detect partial extractions
    const fieldConfusionInc =
      errorPattern === 'ssid_not_serial' ||
      errorPattern === 'part_number_not_serial' ||
      errorPattern === 'mac_not_serial'
        ? 1
        : 0;

    await sql`
      INSERT INTO vlm_metrics (
        metric_date, module, analysis_type,
        total_extractions, correct_extractions, corrected_extractions, failed_extractions,
        avg_confidence,
        digit_confusion_count, format_error_count, partial_extraction_count, field_confusion_count
      ) VALUES (
        ${today}::date, ${module}, ${analysisType},
        1,
        ${wasCorrect && !wasCorrected ? 1 : 0},
        ${wasCorrected ? 1 : 0},
        ${!wasCorrect && !wasCorrected ? 1 : 0},
        ${confidence || null},
        ${digitConfusionInc}, ${formatErrorInc}, ${partialExtractionInc}, ${fieldConfusionInc}
      )
      ON CONFLICT (metric_date, module, analysis_type) DO UPDATE SET
        total_extractions = vlm_metrics.total_extractions + 1,
        correct_extractions = vlm_metrics.correct_extractions + ${wasCorrect && !wasCorrected ? 1 : 0},
        corrected_extractions = vlm_metrics.corrected_extractions + ${wasCorrected ? 1 : 0},
        failed_extractions = vlm_metrics.failed_extractions + ${!wasCorrect && !wasCorrected ? 1 : 0},
        avg_confidence = CASE
          WHEN ${confidence || null}::numeric IS NOT NULL THEN
            (COALESCE(vlm_metrics.avg_confidence, 0) * vlm_metrics.total_extractions + ${confidence || 0}) / (vlm_metrics.total_extractions + 1)
          ELSE vlm_metrics.avg_confidence
        END,
        digit_confusion_count = vlm_metrics.digit_confusion_count + ${digitConfusionInc},
        format_error_count = vlm_metrics.format_error_count + ${formatErrorInc},
        partial_extraction_count = vlm_metrics.partial_extraction_count + ${partialExtractionInc},
        field_confusion_count = vlm_metrics.field_confusion_count + ${fieldConfusionInc},
        updated_at = NOW()
    `;
  } catch (error) {
    // Don't fail the main operation if metrics recording fails
    log.error(`Failed to record metric: ${error}`);
  }
}

