function mapCorrectionRow(row: Record<string, unknown>): VlmCorrection {
  return {
    id: row.id as string,
    module: row.module as VlmModule,
    analysisType: row.analysis_type as VlmAnalysisType,
    sourceId: row.source_id as string | null,
