    >
      {/* Header */}
      <div className="flex items-start justify-between mb-3">
        <h3 className="text-base font-semibold text-white group-hover:text-blue-400 transition-colors">
          {project.project_name}
        </h3>
        <span className="text-xs text-gray-500 font-mono">
          {total.toLocaleString()} feat
        </span>
      </div>

      {/* Progress bar */}
      <div className="mb-3">
        <div className="flex items-center justify-between mb-1">
          <span className="text-xs text-gray-400">QA Progress</span>
          <span className="text-xs font-medium text-gray-300">{approvalPct}%</span>
        </div>
        <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden flex">
          {total > 0 && (
            <>
              <div
                className="h-full bg-green-500 transition-all"
                style={{ width: `${(approved / total) * 100}%` }}
              />
              <div
                className="h-full bg-red-500 transition-all"
                style={{ width: `${(rejected / total) * 100}%` }}
              />
              <div
                className="h-full bg-yellow-500 transition-all"
                style={{ width: `${(pending / total) * 100}%` }}
              />
            </>
          )}
        </div>
        <div className="flex items-center gap-3 mt-1.5">
          <span className="text-xs text-green-400">{approved} approved</span>
          <span className="text-xs text-yellow-400">{pending} pending</span>
          {rejected > 0 && <span className="text-xs text-red-400">{rejected} rejected</span>}
        </div>
      </div>

      {/* Discipline breakdown */}
      <div className="grid grid-cols-2 gap-2 mb-3 text-center">
        <div className="bg-gray-800/50 rounded px-2 py-1.5">
          <div className="text-xs text-gray-500">Civil</div>
          <div className="text-sm font-medium text-gray-300">{project.civil.total}</div>
        </div>
        <div className="bg-gray-800/50 rounded px-2 py-1.5">
          <div className="text-xs text-gray-500">Optical</div>
          <div className="text-sm font-medium text-gray-300">{project.optical.total}</div>
        </div>
      </div>

      {/* Infrastructure stats — matches table columns: Poles(Total/Planted/QA'd), Joints(Total/QA'd), Spans(Total/QA'd) */}
      <div className="grid grid-cols-3 gap-2 mb-3">
        <InfraStat label="Poles" icon={Milestone} stats={project.infrastructure.poles} showAssignment />
        <InfraStat label="Joints" icon={CircleDot} stats={project.infrastructure.joints} />
        <InfraStat label="Spans" icon={Cable} stats={project.infrastructure.cable_spans} />
      </div>

      {/* Photo Completeness */}
      {project.photo_completeness && project.photo_completeness.total_reviews > 0 && (
        <div className="mb-3">
          <div className="flex items-center justify-between mb-1">
            <span className="flex items-center gap-1 text-xs text-gray-400">
              <ClipboardCheck className="w-3.5 h-3.5" />
              Photo Steps (7-step)
            </span>
            <span className={`text-xs font-medium ${
              project.photo_completeness.completeness_pct >= 50 ? 'text-green-400' :
              project.photo_completeness.completeness_pct >= 20 ? 'text-yellow-400' : 'text-red-400'
            }`}>
              {project.photo_completeness.completeness_pct}%
            </span>
          </div>
          <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden flex">
            <div
              className="h-full bg-green-500 transition-all"
              style={{ width: `${(project.photo_completeness.complete_7 / project.photo_completeness.total_reviews) * 100}%` }}
              title={`${project.photo_completeness.complete_7} complete (all 7 steps)`}
            />
            <div
              className="h-full bg-yellow-500 transition-all"
              style={{ width: `${(project.photo_completeness.steps_4_to_6 / project.photo_completeness.total_reviews) * 100}%` }}
              title={`${project.photo_completeness.steps_4_to_6} partial (4-6 steps)`}
            />
            <div
              className="h-full bg-orange-500 transition-all"
              style={{ width: `${(project.photo_completeness.steps_1_to_3 / project.photo_completeness.total_reviews) * 100}%` }}
              title={`${project.photo_completeness.steps_1_to_3} incomplete (1-3 steps)`}
            />
            <div
              className="h-full bg-red-500/60 transition-all"
              style={{ width: `${(project.photo_completeness.no_photos / project.photo_completeness.total_reviews) * 100}%` }}
              title={`${project.photo_completeness.no_photos} no photos`}
            />
          </div>
          <div className="flex items-center gap-2 mt-1 flex-wrap">
            <span className="text-[10px] text-green-400">{project.photo_completeness.complete_7} full</span>
            <span className="text-[10px] text-yellow-400">{project.photo_completeness.steps_4_to_6} partial</span>
            <span className="text-[10px] text-orange-400">{project.photo_completeness.steps_1_to_3} low</span>
            {project.photo_completeness.no_photos > 0 && (
              <span className="text-[10px] text-red-400">{project.photo_completeness.no_photos} none</span>
            )}
          </div>
          {project.photo_completeness.most_missing_step && (
            <div className="text-[10px] text-gray-500 mt-0.5">
              Most skipped: {project.photo_completeness.most_missing_step}
            </div>
          )}
        </div>
      )}

      {/* Meta row — matches table: Zones, PONs, Photos, OTDR */}
      <div className="flex items-center gap-4 text-xs text-gray-500">
        <span className="flex items-center gap-1">
          <MapPin className="w-3.5 h-3.5" />
          {project.zone_count} zones
        </span>
        <span className="flex items-center gap-1">
          <Layers className="w-3.5 h-3.5" />
          {project.pon_count} PONs
        </span>
        <span className="flex items-center gap-1">
          <Camera className="w-3.5 h-3.5" />
          {project.photo_count > 0 ? project.photo_count.toLocaleString() : '-'}
        </span>
        <span className="flex items-center gap-1">
          <Radio className="w-3.5 h-3.5" />
          {project.otdr_count > 0 ? `${project.otdr_count.toLocaleString()} OTDR` : '-'}
        </span>
      </div>
    </button>
  );
}

/**
 * Construction QA Review API
 *
 * GET  /api/construction-qa/review?id={reviewId}
 *   - Returns full review detail with photos and activity
 *
 * POST /api/construction-qa/review
 *   - Updates review checklist steps and extracted data (Phase 2/3)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET', 'POST']);
}

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { id } = req.query;

  if (!id || typeof id !== 'string') {
    return apiResponse.badRequest(res, 'Review id is required');
  }

  try {
    // Fetch review with project name
    const reviews = await sql`
      SELECT
        r.*,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE r.id = ${id}::uuid
      LIMIT 1
    `;

    if (reviews.length === 0) {
      return apiResponse.notFound(res, 'Review', id);
    }

    const review = reviews[0];

    // Fetch photos
    const photos = await sql`
      SELECT *
      FROM construction_qa_photos
      WHERE review_id = ${id}::uuid
      ORDER BY checklist_step ASC NULLS LAST, created_at ASC
    `;

    // Fetch recent activity (last 50 entries)
    const activity = await sql`
      SELECT *
      FROM construction_qa_activity
      WHERE review_id = ${id}::uuid
      ORDER BY created_at DESC
      LIMIT 50
    `;

    return apiResponse.success(res, {
      review,
      photos,
      activity,
    });
  } catch (error) {
    log.error('Review GET error', { module: 'construction-qa', error: (error as Error).message });

    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, { review: null, photos: [], activity: [] });
    }

    return apiResponse.internalError(res, error);
  }
}

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { reviewId, stepUpdates, extractedDataUpdates, notes, reviewedBy, featureIdUpdate } = req.body;

    if (!reviewId) {
      return apiResponse.badRequest(res, 'reviewId is required');
    }

    // Build SET clauses from step updates
    const setClauses: string[] = ['updated_at = NOW()'];
    const params: (string | number | boolean)[] = [reviewId];
    let paramIdx = 2;

    // Valid step column names (whitelist to prevent SQL injection)
    const validStepColumns = new Set([
      // Civil — Pole Install Capture Checklist (8 steps)
      'civil_step_01_before_photo', 'civil_step_02_during_photo', 'civil_step_03_depth_photo',
      'civil_step_04_end_plates', 'civil_step_05_compaction', 'civil_step_06_level_check',
      'civil_step_07_after_photo', 'civil_step_08_signature',
      // Optical — Phase A / Distribution Dome (steps 1-8)
      'optical_step_01_dome_on_pole', 'optical_step_02_dome_label',
      'optical_step_03_open_dome', 'optical_step_04_splice_protectors',
      'optical_step_05_slack_management', 'optical_step_06_strength_members',
      'optical_step_07_seals_dustcaps', 'optical_step_08_pole_id',
      // Optical — Phase B / Main Joint (steps 11-16)
      'optical_step_11_cable_entries', 'optical_step_12_strength_members',
      'optical_step_13_tube_routing', 'optical_step_14_tray_entries',
      'optical_step_15_coiling_protectors', 'optical_step_16_readable_labels',
    ]);

    const updatedFields: string[] = [];

    if (stepUpdates && typeof stepUpdates === 'object') {
      for (const [col, val] of Object.entries(stepUpdates)) {
        if (validStepColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(Boolean(val));
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    // Valid extracted data columns
    const validExtractedColumns = new Set([
      'extracted_pole_number', 'extracted_pole_height', 'extracted_cable_type',
      'extracted_joint_type', 'extracted_splice_count',
    ]);

    if (extractedDataUpdates && typeof extractedDataUpdates === 'object') {
      for (const [col, val] of Object.entries(extractedDataUpdates)) {
        if (validExtractedColumns.has(col)) {
          setClauses.push(`${col} = $${paramIdx}`);
          params.push(val as string | number);
          paramIdx++;
          updatedFields.push(col);
        }
      }
    }

    if (notes) {
      setClauses.push(`qa_notes = $${paramIdx}`);
      params.push(notes);
      paramIdx++;
      updatedFields.push('qa_notes');
    }

    // Feature ID rename/reassign
    if (featureIdUpdate && typeof featureIdUpdate === 'string') {
      setClauses.push(`feature_id = $${paramIdx}`);
      params.push(featureIdUpdate.trim());
      paramIdx++;
      updatedFields.push('feature_id');

      // If renaming to a valid pole pattern, try to backfill zone/PON and clear unidentified
      const validPolePattern = /^[A-Z]{3}\.P\./;
      if (validPolePattern.test(featureIdUpdate.trim())) {
        setClauses.push(`workflow_status = CASE WHEN workflow_status = 'unidentified' THEN 'pending' ELSE workflow_status END`);
      }
    }

    // Move to in_review if currently pending
    setClauses.push(`workflow_status = CASE WHEN workflow_status = 'pending' THEN 'in_review' ELSE workflow_status END`);

    // Execute update
    const updateQuery = `
      UPDATE construction_qa_reviews
      SET ${setClauses.join(', ')}
      WHERE id = $1::uuid
      RETURNING id
    `;

    const result = await sql.query(updateQuery, params);

    if (result.length === 0) {
      return apiResponse.notFound(res, 'Review', reviewId);
    }

    // Log activity
    if (updatedFields.length > 0) {
      const eventType = updatedFields.includes('feature_id') ? 'comment_added' : 'step_checked';
      const payload = updatedFields.includes('feature_id')
        ? { action: 'feature_id_renamed', new_feature_id: featureIdUpdate, updated_fields: updatedFields }
        : { updated_fields: updatedFields };

      await sql`
        INSERT INTO construction_qa_activity (review_id, event_type, actor, payload)
        VALUES (
          ${reviewId}::uuid,
          ${eventType},
          ${reviewedBy || 'unknown'},
          ${JSON.stringify(payload)}::jsonb
        )
      `;
    }

    return apiResponse.success(res, {
      reviewId,
      updatedFields,
    });
  } catch (error) {
    log.error('Review POST error', { module: 'construction-qa', error: (error as Error).message });
    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

/**
 * Construction QA Features API
 *
 * GET /api/construction-qa/features
 *   - List features with filters, pagination, and stats
 *   - ?action=projects returns project list only
 *
 * Follows apiResponse pattern from @/lib/apiResponse
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  try {
    const { action } = req.query;

    // Return project list
    if (action === 'projects') {
      const projects = await sql`
        SELECT DISTINCT p.id, p.project_name AS name
        FROM projects p
        INNER JOIN construction_qa_reviews r ON r.project_id = p.id
        ORDER BY p.project_name
      `;
      return apiResponse.success(res, { projects });
    }

    // Parse filters
    const projectId = req.query.projectId as string || '';
    const discipline = req.query.discipline as string || '';
    const zoneNo = req.query.zoneNo as string || '';
    const ponNo = req.query.ponNo as string || '';
    const workflowStatus = req.query.workflowStatus as string || '';
    const priority = req.query.priority as string || '';
    const search = req.query.search as string || '';
    const page = Math.max(1, parseInt(req.query.page as string || '1', 10));
    const pageSize = Math.min(200, Math.max(1, parseInt(req.query.pageSize as string || '50', 10)));
    const offset = (page - 1) * pageSize;

    // Build WHERE conditions
    const conditions: string[] = [];
    const params: (string | number)[] = [];
    let paramIdx = 1;

    if (discipline) {
      conditions.push(`r.discipline = $${paramIdx}`);
      params.push(discipline);
      paramIdx++;
    }

    if (projectId) {
      conditions.push(`r.project_id = $${paramIdx}::uuid`);
      params.push(projectId);
      paramIdx++;
    }

    if (zoneNo) {
      if (zoneNo === '-1') {
        conditions.push('r.zone_no IS NULL');
      } else {
        conditions.push(`r.zone_no = $${paramIdx}`);
        params.push(parseInt(zoneNo, 10));
        paramIdx++;
      }
    }

    if (ponNo) {
      if (ponNo === '-1') {
        conditions.push('r.pon_no IS NULL');
      } else {
        conditions.push(`r.pon_no = $${paramIdx}`);
        params.push(parseInt(ponNo, 10));
        paramIdx++;
      }
    }

    if (workflowStatus) {
      conditions.push(`r.workflow_status = $${paramIdx}`);
      params.push(workflowStatus);
      paramIdx++;
    }

    if (priority) {
      conditions.push(`r.priority = $${paramIdx}`);
      params.push(priority);
      paramIdx++;
    }

    if (search) {
      conditions.push(`(r.feature_id ILIKE $${paramIdx} OR r.extracted_pole_number ILIKE $${paramIdx})`);
      params.push(`%${search}%`);
      paramIdx++;
    }

    const whereClause = conditions.length > 0 ? conditions.join(' AND ') : '1=1';

    // Fetch features with project name
    const featuresQuery = `
      SELECT
        r.id,
        r.feature_id,
        r.feature_type,
        r.discipline,
        r.zone_no,
        r.pon_no,
        r.photo_count,
        r.vlm_confidence,
        r.vlm_status,
        r.workflow_status,
        r.qa_decision,
        r.priority,
        r.assigned_to,
        r.created_at,
        r.updated_at,
        p.project_name
      FROM construction_qa_reviews r
      JOIN projects p ON p.id = r.project_id
      WHERE ${whereClause}
      ORDER BY
        CASE r.priority
          WHEN 'urgent' THEN 0
          WHEN 'high' THEN 1
          WHEN 'normal' THEN 2
          WHEN 'low' THEN 3
        END,
        r.updated_at DESC
      LIMIT $${paramIdx} OFFSET $${paramIdx + 1}
    `;

    const countQuery = `
      SELECT COUNT(*) AS total
      FROM construction_qa_reviews r
      WHERE ${whereClause}
    `;

    // Stats query (optionally filtered by discipline and project)
    const statsConditions: string[] = [];
    const statsParams: (string | number)[] = [];
    let statsParamIdx = 1;

    if (discipline) {
      statsConditions.push(`discipline = $${statsParamIdx}`);
      statsParams.push(discipline);
      statsParamIdx++;
    }

    if (projectId) {
      statsConditions.push(`project_id = $${statsParamIdx}::uuid`);
      statsParams.push(projectId);
      statsParamIdx++;
    }

    const statsWhere = statsConditions.length > 0 ? statsConditions.join(' AND ') : '1=1';
    const statsQuery = `
      SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE workflow_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE workflow_status = 'approved') AS approved,
        COUNT(*) FILTER (WHERE workflow_status = 'rejected') AS rejected,
        COUNT(*) FILTER (WHERE workflow_status = 'rework_needed') AS rework_needed,
        COUNT(*) FILTER (WHERE workflow_status = 'escalated') AS escalated,
        COUNT(*) FILTER (WHERE workflow_status = 'unidentified') AS unidentified
      FROM construction_qa_reviews
      WHERE ${statsWhere}
    `;

    // Execute all queries in parallel
    const [features, countResult, statsResult] = await Promise.all([
      sql.query(featuresQuery, [...params, pageSize, offset]),
      sql.query(countQuery, params),
      sql.query(statsQuery, statsParams),
    ]);

    const total = Number(countResult[0]?.total || 0);
    const statsRow = statsResult[0] || {};

    return apiResponse.success(res, {
      features,
      stats: {
        total: Number(statsRow.total || 0),
        pending: Number(statsRow.pending || 0),
        approved: Number(statsRow.approved || 0),
        rejected: Number(statsRow.rejected || 0),
        rework_needed: Number(statsRow.rework_needed || 0),
        escalated: Number(statsRow.escalated || 0),
        unidentified: Number(statsRow.unidentified || 0),
      },
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize),
      },
    });
  } catch (error) {
    log.error('Features API error', { module: 'construction-qa', error: (error as Error).message });

    // If table doesn't exist yet (pre-migration), return empty data
    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, {
        features: [],
        stats: { total: 0, pending: 0, approved: 0, rejected: 0, rework_needed: 0, escalated: 0, unidentified: 0 },
        pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 },
      });
    }

    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

/**
 * PON Features Panel
 *
 * Paginated feature table for a selected PON.
 * Filterable by discipline / workflow status.
 * Row click → navigate to review wizard.
 */

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { RefreshCw, ChevronLeft, ChevronRight } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { log } from '@/lib/logger';
import type { PonFeatureRow } from '../../types/dashboard.types';

interface PonFeaturesPanelProps {
  projectId: string;
  zoneNo: number;
  ponNo: number;
  highlightId?: string;
  dateFrom?: string;
  dateTo?: string;
  parentDiscipline?: string;
}

const STATUS_COLORS: Record<string, string> = {
  pending: 'bg-yellow-500/20 text-yellow-400',
  in_review: 'bg-blue-500/20 text-blue-400',
  approved: 'bg-green-500/20 text-green-400',
  rejected: 'bg-red-500/20 text-red-400',
  rework_needed: 'bg-orange-500/20 text-orange-400',
  escalated: 'bg-purple-500/20 text-purple-400',
  unidentified: 'bg-gray-500/20 text-gray-400',
};

export function PonFeaturesPanel({ projectId, zoneNo, ponNo, highlightId, dateFrom, dateTo, parentDiscipline }: PonFeaturesPanelProps) {
  const router = useRouter();
  const [features, setFeatures] = useState<PonFeatureRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [total, setTotal] = useState(0);
  const [discipline, setDiscipline] = useState(parentDiscipline || '');
  const [status, setStatus] = useState('');

  const fetchFeatures = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        projectId,
        zoneNo: String(zoneNo),
        ponNo: String(ponNo),
        page: String(page),
        pageSize: '50',
      });
      if (discipline) params.set('discipline', discipline);
      if (status) params.set('status', status);
      if (dateFrom) params.set('dateFrom', dateFrom);
      if (dateTo) params.set('dateTo', dateTo);

      const res = await fetch(`/api/construction-qa/pon-features?${params}`, {
        credentials: 'include',
      });
      if (res.ok) {
        const data = await res.json();
        setFeatures(data.data?.features || []);
        setTotal(data.data?.pagination?.total || 0);
        setTotalPages(data.data?.pagination?.totalPages || 0);
      }
    } catch (err) {
      log.error('Failed to fetch PON features', { error: (err as Error).message }, 'construction-qa');
    } finally {
      setLoading(false);
    }
  }, [projectId, zoneNo, ponNo, page, discipline, status, dateFrom, dateTo]);

  useEffect(() => {
    fetchFeatures();
  }, [fetchFeatures]);

  // Sync with parent discipline filter
  useEffect(() => {
    setDiscipline(parentDiscipline || '');
  }, [parentDiscipline]);

  // Reset page when filters change
  useEffect(() => {
    setPage(1);
  }, [discipline, status]);

  return (
    <div className="bg-[var(--card-bg)] border border-[var(--border-color)] rounded-lg overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-3">
          <h3 className={`text-sm font-semibold ${zoneNo === -1 ? 'text-yellow-400' : 'text-white'}`}>
            {zoneNo === -1 ? 'Unassigned Features' : `Zone ${zoneNo} / PON ${ponNo}`}
          </h3>
          <span className="text-xs text-gray-500">{total} features</span>
        </div>
        <div className="flex items-center gap-2">
          <Select value={discipline || '__all__'} onValueChange={v => setDiscipline(v === '__all__' ? '' : v)}>
            <SelectTrigger className="w-[120px] h-8 text-xs">
              <SelectValue placeholder="All Types" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__all__">All Types</SelectItem>
              <SelectItem value="civil">Civil</SelectItem>
              <SelectItem value="optical">Optical</SelectItem>
            </SelectContent>
          </Select>
          <Select value={status || '__all__'} onValueChange={v => setStatus(v === '__all__' ? '' : v)}>
            <SelectTrigger className="w-[130px] h-8 text-xs">
              <SelectValue placeholder="All Statuses" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__all__">All Statuses</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="approved">Approved</SelectItem>
              <SelectItem value="rejected">Rejected</SelectItem>
              <SelectItem value="rework_needed">Rework</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Table */}
      <table className="w-full">
        <thead>
          <tr className="border-b border-[var(--border-color)]">
            <th className="text-left px-4 py-2 text-xs font-medium text-gray-400 uppercase">Feature</th>
            <th className="text-left px-4 py-2 text-xs font-medium text-gray-400 uppercase">Type</th>
            <th className="text-center px-4 py-2 text-xs font-medium text-gray-400 uppercase">Photos</th>
            <th className="text-center px-4 py-2 text-xs font-medium text-gray-400 uppercase">AI</th>
            <th className="text-center px-4 py-2 text-xs font-medium text-gray-400 uppercase">Status</th>
            <th className="text-center px-4 py-2 text-xs font-medium text-gray-400 uppercase">Decision</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-[var(--border-color)]">
          {loading && features.length === 0 ? (
            <tr>
              <td colSpan={6} className="px-4 py-8 text-center text-gray-500">
                <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2" />
                Loading...
              </td>
            </tr>
          ) : features.length === 0 ? (
            <tr>
              <td colSpan={6} className="px-4 py-8 text-center text-gray-500 text-sm">
                No features in this PON.
              </td>
            </tr>
          ) : (
            features.map(f => {
              const isHighlighted = f.id === highlightId;
              return (
                <tr
                  key={f.id}
                  onClick={() => router.push(`/field-ops/${f.id}`)}
                  className={`cursor-pointer transition-colors ${
                    isHighlighted
                      ? 'bg-blue-500/10 ring-1 ring-inset ring-blue-500/30'
                      : 'hover:bg-[var(--hover-bg)]'
                  }`}
                >
                  <td className="px-4 py-2.5 text-sm font-medium text-white">{f.feature_id}</td>
                  <td className="px-4 py-2.5 text-xs text-gray-400 capitalize">{f.discipline}</td>
                  <td className="px-4 py-2.5 text-center text-sm text-gray-300">{f.photo_count}</td>
                  <td className="px-4 py-2.5 text-center">
                    {f.vlm_confidence !== null ? (
                      <span className={`text-xs font-mono font-medium ${
                        Math.round(Number(f.vlm_confidence) * 100) >= 80 ? 'text-green-400' :
                        Math.round(Number(f.vlm_confidence) * 100) >= 60 ? 'text-yellow-400' : 'text-red-400'
                      }`}>
                        {Math.round(Number(f.vlm_confidence) * 100)}%
                      </span>
                    ) : (
                      <span className="text-gray-500 text-xs">—</span>
                    )}
                  </td>
                  <td className="px-4 py-2.5 text-center">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium ${STATUS_COLORS[f.workflow_status] || 'bg-gray-500/20 text-gray-400'}`}>
                      {f.workflow_status.replace('_', ' ')}
                    </span>
                  </td>
                  <td className="px-4 py-2.5 text-center text-sm">
                    {f.qa_decision ? (
                      <span className={`font-medium ${
                        f.qa_decision === 'PASS' ? 'text-green-400' :
                        f.qa_decision === 'FAIL' ? 'text-red-400' : 'text-orange-400'
                      }`}>
                        {f.qa_decision}
                      </span>
                    ) : (
                      <span className="text-gray-500">—</span>
                    )}
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between px-4 py-2 border-t border-[var(--border-color)]">
          <button
            disabled={page <= 1}
            onClick={() => setPage(p => p - 1)}
            className="flex items-center gap-1 px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-40"
          >
            <ChevronLeft className="w-3.5 h-3.5" /> Prev
          </button>
          <span className="text-xs text-gray-500">
            Page {page} of {totalPages}
          </span>
          <button
            disabled={page >= totalPages}
            onClick={() => setPage(p => p + 1)}
            className="flex items-center gap-1 px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-40"
          >
            Next <ChevronRight className="w-3.5 h-3.5" />
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * PON Features API
 *
 * GET /api/construction-qa/pon-features?projectId=UUID&zoneNo=1&ponNo=12
 *   Paginated feature list scoped to project + zone + PON.
 *   Optional: ?discipline=civil&status=pending
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { withAuth, withPermission } from '@/lib/auth/middleware';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'unknown', ['GET']);
  }

  const projectId = req.query.projectId as string;
  const zoneNo = req.query.zoneNo as string;
  const ponNo = req.query.ponNo as string;

  if (!projectId || !zoneNo || !ponNo) {
    return apiResponse.badRequest(res, 'projectId, zoneNo, and ponNo are required');
  }

  const discipline = req.query.discipline as string || '';
  const status = req.query.status as string || '';
  const page = Math.max(1, parseInt(req.query.page as string || '1', 10));
  const pageSize = Math.min(200, Math.max(1, parseInt(req.query.pageSize as string || '50', 10)));
  const offset = (page - 1) * pageSize;

  try {
    // zone=-1 / pon=-1 is the sentinel for unassigned features (NULL zone/pon)
    const zoneInt = parseInt(zoneNo, 10);
    const ponInt = parseInt(ponNo, 10);
    const isUnassigned = zoneInt === -1;

    const conditions: string[] = ['r.project_id = $1::uuid'];
    const params: (string | number)[] = [projectId];
    let paramIdx = 2;

    if (isUnassigned) {
      conditions.push('r.zone_no IS NULL');
    } else {
      conditions.push(`r.zone_no = $${paramIdx}`);
      params.push(zoneInt);
      paramIdx++;
      conditions.push(`r.pon_no = $${paramIdx}`);
      params.push(ponInt);
      paramIdx++;
    }

    if (discipline) {
      conditions.push(`r.discipline = $${paramIdx}`);
      params.push(discipline);
      paramIdx++;
    }

    if (status) {
      conditions.push(`r.workflow_status = $${paramIdx}`);
      params.push(status);
      paramIdx++;
    }

    const dateFrom = req.query.dateFrom as string || '';
    const dateTo = req.query.dateTo as string || '';

    if (dateFrom) {
      conditions.push(`COALESCE(r.last_photo_at, r.created_at) >= $${paramIdx}::timestamptz`);
      params.push(dateFrom);
      paramIdx++;
    }

    if (dateTo) {
      conditions.push(`COALESCE(r.last_photo_at, r.created_at) < $${paramIdx}::timestamptz`);
      params.push(dateTo);
      paramIdx++;
    }

    const whereClause = conditions.join(' AND ');

    const featuresQuery = `
      SELECT
        r.id,
        r.feature_id,
        r.feature_type,
        r.discipline,
        r.zone_no,
        r.pon_no,
        r.photo_count,
        r.vlm_confidence,
        r.vlm_status,
        r.workflow_status,
        r.qa_decision,
        r.priority,
        r.assigned_to,
        r.updated_at
      FROM construction_qa_reviews r
      WHERE ${whereClause}
      ORDER BY r.feature_id
      LIMIT $${paramIdx} OFFSET $${paramIdx + 1}
    `;

    const countQuery = `
      SELECT COUNT(*)::int AS total
      FROM construction_qa_reviews r
      WHERE ${whereClause}
    `;

    const [features, countResult] = await Promise.all([
      sql.query(featuresQuery, [...params, pageSize, offset]),
      sql.query(countQuery, params),
    ]);

    const total = Number(countResult[0]?.total || 0);

    return apiResponse.success(res, {
      features,
      pagination: {
        page,
        pageSize,
        total,
        totalPages: Math.ceil(total / pageSize),
      },
    });
  } catch (error) {
    log.error('PON features API error', {
      module: 'construction-qa',
      error: (error as Error).message,
    });

    if ((error as Error).message?.includes('does not exist')) {
      return apiResponse.success(res, {
        features: [],
        pagination: { page: 1, pageSize: 50, total: 0, totalPages: 0 },
      });
    }

    return apiResponse.internalError(res, error);
  }
}

export default withAuth(withPermission('construction-qa.qa-centre')(handler));

