/**
 * TicketList Component - Main ticket list view
 *
 * 🟢 WORKING: Production-ready ticket list component
 *
 * Features:
 * - Display tickets in a filterable, paginated list
 * - Search and filter tickets
 * - Sort tickets
 * - Pagination controls
 * - Loading and error states
 * - Empty state handling
 * - Responsive design
 */

'use client';

import React, { useState } from 'react';
import {
  FileText,
  Loader2,
  AlertTriangle,
  ChevronLeft,
  ChevronRight,
  RefreshCw,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useTickets } from '../../hooks/useTickets';
import { TicketFilters } from './TicketFilters';
import { TicketListItem } from './TicketListItem';
import type { TicketFilters as TicketFiltersType, Ticket } from '../../types/ticket';

interface TicketListProps {
  /** Initial filters */
  initialFilters?: TicketFiltersType;
  /** Compact mode */
  compact?: boolean;
  /** Custom item click handler */
  onTicketClick?: (ticket: Ticket) => void;
  /** Hide filters */
  hideFilters?: boolean;
}

/**
 * 🟢 WORKING: Main ticket list component
 */
export function TicketList({
  initialFilters = {},
  compact = false,
  onTicketClick,
  hideFilters = false,
}: TicketListProps) {
  const [filters, setFilters] = useState<TicketFiltersType>({
    page: 1,
    pageSize: 20,
    ...initialFilters,
  });

  const { tickets, pagination, isLoading, isError, error, refetch } = useTickets(filters);

  // 🟢 WORKING: Handle filter change
  const handleFiltersChange = (newFilters: TicketFiltersType) => {
    setFilters({
      ...newFilters,
      page: 1, // Reset to first page when filters change
      pageSize: filters.pageSize,
    });
  };

  // 🟢 WORKING: Handle page change
  const handlePageChange = (newPage: number) => {
    setFilters({ ...filters, page: newPage });
  };

  // 🟢 WORKING: Handle refresh
  const handleRefresh = () => {
    refetch();
  };

  // 🟢 WORKING: Loading state
  if (isLoading && tickets.length === 0) {
    return (
      <div className="flex items-center justify-center p-12">
        <div className="text-center">
          <Loader2 className="w-8 h-8 text-[var(--ff-text-secondary)] animate-spin mx-auto mb-3" />
          <p className="text-[var(--ff-text-secondary)]">Loading tickets...</p>
        </div>
      </div>
    );
  }

  // 🟢 WORKING: Error state
  if (isError && tickets.length === 0) {
    return (
      <div className="p-8">
        <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-6">
          <div className="flex items-start gap-3 mb-4">
            <AlertTriangle className="w-6 h-6 text-red-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <h3 className="text-lg font-semibold text-red-400 mb-1">Error Loading Tickets</h3>
              <p className="text-sm text-red-300">
                {error?.message || 'Failed to fetch tickets'}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={handleRefresh}
            className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
          >
            <RefreshCw className="w-4 h-4" />
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-[var(--ff-text-primary)]">Tickets</h2>
          {pagination && (
            <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
              {pagination.total} total tickets
            </p>
          )}
        </div>

        <button
          type="button"
          onClick={handleRefresh}
          disabled={isLoading}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          aria-label="Refresh tickets"
        >
          <RefreshCw className={cn('w-4 h-4', isLoading && 'animate-spin')} />
          Refresh
        </button>
      </div>

      {/* Filters */}
      {!hideFilters && (
        <TicketFilters
          filters={filters}
          onFiltersChange={handleFiltersChange}
          compact={compact}
        />
      )}

      {/* Empty State */}
      {tickets.length === 0 && !isLoading && (
        <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-12">
          <div className="flex flex-col items-center justify-center text-center">
            <FileText className="w-16 h-16 text-[var(--ff-text-tertiary)] mb-4" />
            <h3 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-2">No tickets found</h3>
            <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
              {Object.keys(filters).some(k => k !== 'page' && k !== 'pageSize' && filters[k as keyof TicketFiltersType])
                ? 'Try adjusting your filters to see more results'
                : 'No tickets have been created yet'}
            </p>
            {Object.keys(filters).some(k => k !== 'page' && k !== 'pageSize' && filters[k as keyof TicketFiltersType]) && (
              <button
                type="button"
                onClick={() => handleFiltersChange({})}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                Clear Filters
              </button>
            )}
          </div>
        </div>
      )}

      {/* Tickets List */}
      {tickets.length > 0 && (
        <div className="space-y-3">
          <ul className="space-y-3" role="list">
            {tickets.map((ticket) => (
              <li key={ticket.id} role="listitem">
                <TicketListItem
                  ticket={ticket}
                  compact={compact}
                  onClick={onTicketClick}
                />
              </li>
            ))}
          </ul>

          {/* Pagination */}
          {pagination && pagination.totalPages > 1 && (
            <div className="flex items-center justify-between pt-4">
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Showing {((pagination.page - 1) * pagination.pageSize) + 1} to{' '}
                {Math.min(pagination.page * pagination.pageSize, pagination.total)} of{' '}
                {pagination.total} tickets
              </p>

              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1 || isLoading}
                  className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Previous page"
                >
                  <ChevronLeft className="w-4 h-4" />
                  Previous
                </button>

                <span className="text-sm text-[var(--ff-text-secondary)] px-4">
                  Page {pagination.page} of {pagination.totalPages}
                </span>

                <button
                  type="button"
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page === pagination.totalPages || isLoading}
                  className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Next page"
                >
                  Next
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * TicketFilters Component - Ticket filtering interface
 *
 * 🟢 WORKING: Production-ready ticket filters component
 *
 * Features:
 * - Filter by status, type, priority, assignee
 * - Search by ticket UID, DR number, or description
 * - QA ready filter
 * - SLA breach filter
 * - Clear filters option
 * - Responsive layout
 */

'use client';

import React, { useState } from 'react';
import { Search, Filter, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { TicketFilters as TicketFiltersType } from '../../types/ticket';

interface TicketFiltersProps {
  /** Current filters */
  filters: TicketFiltersType;
  /** Callback when filters change */
  onFiltersChange: (filters: TicketFiltersType) => void;
  /** Show compact version */
  compact?: boolean;
}

/**
 * 🟢 WORKING: Ticket filters component
 */
export function TicketFilters({ filters, onFiltersChange, compact = false }: TicketFiltersProps) {
  const [showFilters, setShowFilters] = useState(false);

  // 🟢 WORKING: Handle filter change
  const handleFilterChange = (key: keyof TicketFiltersType, value: any) => {
    onFiltersChange({
      ...filters,
      [key]: value || undefined,
    });
  };

  // 🟢 WORKING: Clear all filters
  const handleClearFilters = () => {
    onFiltersChange({});
  };

  // 🟢 WORKING: Check if any filters are active
  const hasActiveFilters = Object.keys(filters).some(
    (key) => key !== 'page' && key !== 'pageSize' && filters[key as keyof TicketFiltersType] !== undefined
  );

  return (
    <div className="space-y-4">
      {/* Search and Toggle */}
      <div className="flex items-center gap-3">
        {/* Search Input */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--ff-text-tertiary)]" />
          <input
            type="text"
            placeholder="Search tickets..."
            value={filters.search || ''}
            onChange={(e) => handleFilterChange('search', e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
          />
        </div>

        {/* Filter Toggle */}
        <button
          type="button"
          onClick={() => setShowFilters(!showFilters)}
          className={cn(
            'flex items-center gap-2 px-4 py-2 rounded-lg border transition-colors',
            showFilters
              ? 'bg-blue-500/20 border-blue-500/30 text-blue-400'
              : 'bg-[var(--ff-bg-secondary)] border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)]'
          )}
        >
          <Filter className="w-4 h-4" />
          {!compact && <span>Filters</span>}
          {hasActiveFilters && (
            <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-blue-500 text-white text-xs font-medium">
              {Object.keys(filters).filter(k => k !== 'page' && k !== 'pageSize' && filters[k as keyof TicketFiltersType]).length}
            </span>
          )}
        </button>

        {/* Clear Filters */}
        {hasActiveFilters && (
          <button
            type="button"
            onClick={handleClearFilters}
            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            aria-label="Clear all filters"
          >
            <X className="w-4 h-4" />
            {!compact && <span>Clear</span>}
          </button>
        )}
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className={cn(
          'grid gap-4 p-4 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg',
          compact ? 'grid-cols-1' : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4'
        )}>
          {/* Status Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              Status
            </label>
            <select
              value={filters.status || ''}
              onChange={(e) => handleFilterChange('status', e.target.value)}
              className="w-full px-3 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            >
              <option value="">All Statuses</option>
              <option value="open">Open</option>
              <option value="assigned">Assigned</option>
              <option value="in_progress">In Progress</option>
              <option value="pending_qa">Pending QA</option>
              <option value="qa_in_progress">QA In Progress</option>
              <option value="qa_rejected">QA Rejected</option>
              <option value="qa_approved">QA Approved</option>
              <option value="pending_handover">Pending Handover</option>
              <option value="handed_to_maintenance">Handed to Maintenance</option>
              <option value="closed">Closed</option>
              <option value="cancelled">Cancelled</option>
            </select>
          </div>

          {/* Type Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              Type
            </label>
            <select
              value={filters.ticket_type || ''}
              onChange={(e) => handleFilterChange('ticket_type', e.target.value)}
              className="w-full px-3 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            >
              <option value="">All Types</option>
              <option value="maintenance">Maintenance</option>
              <option value="new_installation">New Installation</option>
              <option value="modification">Modification</option>
              <option value="ont_swap">ONT Swap</option>
              <option value="incident">Incident</option>
            </select>
          </div>

          {/* Priority Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              Priority
            </label>
            <select
              value={filters.priority || ''}
              onChange={(e) => handleFilterChange('priority', e.target.value)}
              className="w-full px-3 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            >
              <option value="">All Priorities</option>
              <option value="low">Low</option>
              <option value="normal">Normal</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
              <option value="critical">Critical</option>
            </select>
          </div>

          {/* QA Ready Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              QA Status
            </label>
            <select
              value={filters.qa_ready === undefined ? '' : filters.qa_ready ? 'true' : 'false'}
              onChange={(e) =>
                handleFilterChange('qa_ready', e.target.value === '' ? undefined : e.target.value === 'true')
              }
              className="w-full px-3 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            >
              <option value="">All</option>
              <option value="true">QA Ready</option>
              <option value="false">Not QA Ready</option>
            </select>
          </div>

          {/* SLA Breach Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              SLA Status
            </label>
            <select
              value={filters.sla_breached === undefined ? '' : filters.sla_breached ? 'true' : 'false'}
              onChange={(e) =>
                handleFilterChange('sla_breached', e.target.value === '' ? undefined : e.target.value === 'true')
              }
              className="w-full px-3 py-2 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            >
              <option value="">All</option>
              <option value="true">SLA Breached</option>
              <option value="false">Within SLA</option>
            </select>
          </div>

          {/* DR Number Filter */}
          <div>
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-2">
              DR Number
            </label>
            <input
              type="text"
              placeholder="e.g., DR12345"
