/**
 * useTickets Hook - Fetch and manage tickets list
 *
 * 🟢 WORKING: Production-ready hook for tickets list management
 *
 * Features:
 * - List tickets with filtering (status, type, priority, assignee, etc.)
 * - Pagination support
 * - Sort and search
 * - React Query integration for caching and auto-refresh
 * - Loading and error states
 */

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type {
  Ticket,
  TicketFilters,
  TicketListResult,
  CreateTicketPayload,
} from '../types/ticket';

// ==================== Query Keys ====================

/**
 * 🟢 WORKING: Query keys factory for tickets
 */
export const ticketsKeys = {
  all: ['tickets'] as const,
  lists: () => [...ticketsKeys.all, 'list'] as const,
  list: (filters?: TicketFilters) => [...ticketsKeys.lists(), filters] as const,
  details: () => [...ticketsKeys.all, 'detail'] as const,
  detail: (id: string) => [...ticketsKeys.details(), id] as const,
};

// ==================== API Functions ====================

/**
 * 🟢 WORKING: Fetch tickets list from API
 */
async function fetchTickets(filters?: TicketFilters): Promise<TicketListResult> {
  // Build query string from filters
  const params = new URLSearchParams();

  if (filters) {
    if (filters.status) params.append('status', filters.status);
    if (filters.ticket_type) params.append('ticket_type', filters.ticket_type);
    if (filters.priority) params.append('priority', filters.priority);
    if (filters.source) params.append('source', filters.source);
    if (filters.assigned_to) params.append('assigned_to', filters.assigned_to);
    if (filters.assigned_team_id) params.append('assigned_team_id', filters.assigned_team_id);
    if (filters.project_id) params.append('project_id', filters.project_id);
    if (filters.dr_number) params.append('dr_number', filters.dr_number);
    if (filters.qa_ready !== undefined) params.append('qa_ready', String(filters.qa_ready));
    if (filters.sla_breached !== undefined) params.append('sla_breached', String(filters.sla_breached));
    if (filters.search) params.append('search', filters.search);
    if (filters.created_after) params.append('created_after', new Date(filters.created_after).toISOString());
    if (filters.created_before) params.append('created_before', new Date(filters.created_before).toISOString());
    if (filters.sort) params.append('sort', filters.sort);
    if (filters.page !== undefined) params.append('page', String(filters.page));
    if (filters.pageSize !== undefined) params.append('pageSize', String(filters.pageSize));
  }

  const url = `/api/noc/tickets?${params.toString()}`;
  const response = await fetch(url);

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.error?.message || 'Failed to fetch tickets');
  }

  const result = await response.json();

  if (!result.success) {
    throw new Error(result.error?.message || 'Failed to fetch tickets');
  }

  return {
    tickets: result.data || [],
    pagination: result.pagination || {
      page: 1,
      pageSize: 20,
      total: 0,
      totalPages: 0,
    },
  };
}

/**
 * 🟢 WORKING: Create new ticket
 */
async function createTicketRequest(payload: CreateTicketPayload): Promise<Ticket> {
  const response = await fetch('/api/noc/tickets', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.error?.message || 'Failed to create ticket');
  }

  const result = await response.json();

  if (!result.success) {
    throw new Error(result.error?.message || 'Failed to create ticket');
  }

  return result.data;
}

// ==================== React Query Hooks ====================

/**
 * 🟢 WORKING: Hook to fetch tickets list with filters
 *
 * @example
 * ```tsx
 * const { tickets, pagination, isLoading, error } = useTickets({
 *   status: 'open',
 *   page: 1,
 *   pageSize: 20,
 * });
 * ```
 */
export function useTickets(filters?: TicketFilters) {
  const query = useQuery({
    queryKey: ticketsKeys.list(filters),
    queryFn: () => fetchTickets(filters),
    staleTime: 30000, // 30 seconds
    refetchInterval: 60000, // Refresh every minute
  });

  return {
    tickets: query.data?.tickets || [],
    pagination: query.data?.pagination,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
    refetch: query.refetch,
  };
}

/**
 * 🟢 WORKING: Hook to create new ticket
 *
 * @example
 * ```tsx
 * const createTicket = useCreateTicket();
 *
 * createTicket.mutate({
 *   title: 'New Ticket',
 *   source: 'manual',
 *   ticket_type: 'maintenance',
 *   priority: 'normal',
 * });
 * ```
 */
export function useCreateTicket() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: createTicketRequest,
    onSuccess: () => {
      // Invalidate all ticket lists on successful creation
      queryClient.invalidateQueries({ queryKey: ticketsKeys.lists() });
    },
  });
}

/**
 * Ticket Service - CRUD Operations
 *
 * 🟢 WORKING: Production-ready ticket service with full CRUD operations
 *
 * Provides:
 * - Create ticket with validation and UID generation
 * - Read ticket by ID
 * - Update ticket (partial updates)
 * - Delete ticket (soft delete - marks as CANCELLED)
 * - List tickets with filters and pagination
 *
 * Features:
 * - Input validation
 * - SQL injection prevention (parameterized queries)
 * - Soft delete (never hard delete tickets)
 * - Pagination support
 * - Multi-criteria filtering
 * - Automatic ticket UID generation (VF-YYYYMMDD-NNN format)
 *   - VF = Velocity Fibre
 *   - YYYYMMDD = Date
 *   - NNN = Daily sequence (001, 002, etc.)
 *   - Uses atomic database sequence for collision-free generation
 */

import { query, queryOne } from '../utils/db';
import {
  Ticket,
  CreateTicketPayload,
  UpdateTicketPayload,
  TicketSource,
  TicketType,
  TicketPriority,
  TicketStatus,
  TicketFilters,
  TicketListResponse
} from '../types/ticket';
import { createLogger } from '@/lib/logger';

const logger = createLogger('maintenance:service');

/**
 * UUID validation regex
 */
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Validate UUID format
 */
function isValidUUID(id: string): boolean {
  return UUID_REGEX.test(id);
}

/**
 * Generate unique ticket UID using atomic database sequence
 * Format: VF-YYYYMMDD-NNN (e.g., VF-20260122-001)
 *
 * - VF = Velocity Fibre
 * - YYYYMMDD = Date of creation
 * - NNN = Daily sequence number (resets each day)
 *
 * Uses INSERT...ON CONFLICT for atomic, collision-free generation.
 *
 * @param forDate - Optional date to generate UID for (used during migration)
 * @returns Promise<string> The generated VF ticket UID
 */
async function generateTicketUID(forDate?: Date, prefix = 'VF'): Promise<string> {
  const targetDate = forDate || new Date();
  const isoStr = targetDate.toISOString();
  const dateStr = isoStr.slice(0, 10); // YYYY-MM-DD for SQL
  const formattedDate = dateStr.replace(/-/g, ''); // YYYYMMDD for UID

  // Atomic sequence generation using INSERT...ON CONFLICT
  const result = await queryOne<{ last_sequence: number }>(
    `INSERT INTO maintenance_ticket_sequences (sequence_date, last_sequence)
     VALUES ($1::date, 1)
     ON CONFLICT (sequence_date)
     DO UPDATE SET
       last_sequence = maintenance_ticket_sequences.last_sequence + 1,
       updated_at = NOW()
     RETURNING last_sequence`,
    [dateStr]
  );

  if (!result) {
    throw new Error(`Failed to generate ${prefix} ticket UID - sequence query returned no result`);
  }

  const seqNum = result.last_sequence;
  const paddedSeq = String(seqNum).padStart(3, '0');

  return `${prefix}-${formattedDate}-${paddedSeq}`;
}

/**
 * Legacy function for backward compatibility
 * @deprecated Use generateTicketUID() instead
 */
function generateLegacyTicketUID(): string {
  const randomDigits = Math.floor(100000 + Math.random() * 900000);
  return `FF${randomDigits}`;
}

/**
 * Validate ticket source enum
 */
function isValidSource(source: string): source is TicketSource {
  return Object.values(TicketSource).includes(source as TicketSource);
}

/**
 * Validate ticket type enum
 */
function isValidTicketType(ticketType: string): ticketType is TicketType {
  return Object.values(TicketType).includes(ticketType as TicketType);
}

/**
 * Create a new ticket
 *
 * @param payload - Ticket creation data
 * @returns Created ticket with generated ID and UID
 * @throws {Error} If validation fails or database error occurs
 */
export async function createTicket(payload: CreateTicketPayload): Promise<Ticket> {
  // 🟢 WORKING: Validate required fields
  if (!payload.source) {
    throw new Error('source is required');
  }

